-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 010: 2FA por TOTP (RFC 6238) para la firma personal (E06,
-- elevando el OTP-correo del Inc.2). El secreto vive en AUTH-SERVICE, junto a
-- auth_users (D1 ownership) — signature-service NUNCA lo ve, solo llama al
-- endpoint interno de verificación.
--
-- Tabla SEPARADA de auth_users (no la carga en lecturas normales de auth_users):
-- 1:1 lógico por usuario, pero solo UNA fila activa/pendiente a la vez —
-- ``uq_auth_user_totp_activo`` es un índice único PARCIAL sobre estado <> 'revocado',
-- mismo patrón que ``uq_firma_challenge_activo`` (signature-service 011) para el
-- reemplazo idempotente en re-enroll (revoke-then-insert dentro de una transacción).
--
-- INVARIANTE RECTOR: el secreto se cifra en reposo con AESGCM (secret_cifrado +
-- secret_nonce) y solo se descifra en memoria al verificar/reenrolar/revocar con
-- step-up. NUNCA se persiste, loguea, ni figura en respuesta o evento algunos.
--
-- Rollback:
--   DROP TABLE IF EXISTS auth_user_totp;

CREATE TABLE IF NOT EXISTS auth_user_totp (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id           UUID NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,
    secret_cifrado    BYTEA NOT NULL,            -- AESGCM ciphertext del secreto TOTP (20 bytes)
    secret_nonce      BYTEA NOT NULL,             -- nonce aleatorio de 12 bytes, uno por fila
    algoritmo         TEXT NOT NULL DEFAULT 'SHA1'
                      CHECK (algoritmo IN ('SHA1')),
    digitos           SMALLINT NOT NULL DEFAULT 6,
    periodo           SMALLINT NOT NULL DEFAULT 30,
    estado            TEXT NOT NULL DEFAULT 'pendiente_activacion'
                      CHECK (estado IN ('pendiente_activacion', 'activo', 'revocado')),
    last_timestep     BIGINT NOT NULL DEFAULT 0,  -- anti-replay (RFC 6238): solo Tm > last_timestep
    failed_attempts   SMALLINT NOT NULL DEFAULT 0,
    locked_until      TIMESTAMPTZ,
    key_version       SMALLINT NOT NULL DEFAULT 1, -- rotación futura de totp_encryption_key
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    activated_at      TIMESTAMPTZ,
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Un solo TOTP activo/pendiente por usuario — el enroll/re-enroll reemplaza
-- (revoca la fila vieja e inserta una nueva) dentro de la misma transacción.
CREATE UNIQUE INDEX IF NOT EXISTS uq_auth_user_totp_activo
    ON auth_user_totp (user_id)
    WHERE estado <> 'revocado';

CREATE INDEX IF NOT EXISTS ix_auth_user_totp_user ON auth_user_totp (user_id);

COMMENT ON TABLE auth_user_totp IS
    'Credencial TOTP (RFC 6238) para el segundo factor de la firma personal '
    '(E06). El secreto se cifra en reposo (AESGCM) y solo se descifra en '
    'memoria al verificar — NUNCA se persiste, loguea, ni figura en '
    'respuesta o evento algunos. GET /me/totp jamás lo devuelve.';

COMMENT ON COLUMN auth_user_totp.secret_cifrado IS
    'Ciphertext AESGCM del secreto (20 bytes). AAD = '
    '"tenant:{slug}:user:{user_id}:totp" — ata el ciphertext a la fila/tenant; '
    'movido a otra fila/tenant, el descifrado falla.';

COMMENT ON COLUMN auth_user_totp.last_timestep IS
    'Último timestep (T = floor(unix/periodo)) aceptado. El verify solo acepta '
    'Tm > last_timestep (anti-replay) — avance atómico en un único UPDATE '
    'condicional (WHERE last_timestep < Tm).';

COMMENT ON COLUMN auth_user_totp.failed_attempts IS
    'Contador de verificaciones fallidas (activate + verify comparten la misma '
    'fila). Al alcanzar totp_max_failed_attempts, locked_until = now() + '
    'totp_lockout_seconds; ninguno de los dos es reseteable por el caller.';

-- >>> auth-service/tenant/011_user_signing_key.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 011: firma electrónica PERSONAL PKI por-usuario (E17/F4,
-- Incremento 1) — custodia SERVIDOR (postura B), marco honesto "no
-- acreditado" (mismo nivel legal art. 7 que la firma electrónica simple),
-- forward-compatible a HSM (ver app/core/signing_keys.py).
--
-- CAVEAT explícito (C7, honestidad RF-FIR-15): custodia SERVIDOR ⇒ NO hay
-- sole-control del titular sobre su clave (las columnas de este archivo
-- cifran la clave EN REPOSO — property de SEGURIDAD: no se filtra — pero
-- el custodio conserva acceso técnico a ella — property LEGAL, distinta:
-- no puede excluirse como autor material). Este esquema es firma
-- electrónica art. 7 Ley 527/1999 (atribución + integridad verificable),
-- NO da no-repudio oponible contra el operador/institución y NO equivale a
-- firma digital cualificada (art. 28); ese tier exige clave bajo control
-- EXCLUSIVO del firmante + CA acreditada ONAC — roadmap HSM/PKI.
--
-- Espeja el patrón de ``010_totp.sql``: tabla SEPARADA de auth_users, 1:1
-- lógico por usuario pero solo UNA fila no-revocada a la vez
-- (``uq_auth_user_signing_key_activa``, índice único PARCIAL sobre
-- estado <> 'revocado' — mismo reemplazo idempotente en re-enroll que
-- ``uq_auth_user_totp_activo``).
--
-- INVARIANTE RECTOR (no negociable, ver CLAUDE.md de este incremento): la
-- clave privada del usuario JAMÁS sale de este servicio en claro — se cifra
-- en reposo con AESGCM (``private_key_cifrado`` + ``private_key_nonce``) y
-- solo se descifra en memoria, dentro de auth-service, para el tiempo mínimo
-- indispensable de firmar UN digest (``sign_digest``, dentro de la misma
-- transacción que verifica-y-consume el TOTP). Ni un endpoint, log, evento o
-- entrada de auditoría de este servicio emite la clave privada — ni una sola
-- vez (a diferencia del secreto TOTP, que SÍ se revela una vez en el enroll).
--
-- ``estado``: 'pendiente_emision' (keygen + CSR generados, a la espera de que
-- el emisor OFFLINE — scripts/gen-user-cert.sh, o el flujo de test con CA en
-- memoria — cargue el certificado firmado), 'activo' (certificado cargado,
-- utilizable para firmar), 'revocado' (reemplazada por un re-enroll, o
-- revocada explícitamente).
--
-- Rollback:
--   DROP TABLE IF EXISTS auth_user_signing_key;

CREATE TABLE IF NOT EXISTS auth_user_signing_key (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id               UUID NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,
    cert_pem              TEXT,               -- NULL hasta 'activo' (emisión offline)
    csr_pem               TEXT,               -- CSR generado en el enroll (público)
    private_key_cifrado   BYTEA NOT NULL,      -- AESGCM ciphertext de la clave privada (PEM)
    private_key_nonce     BYTEA NOT NULL,      -- nonce aleatorio de 12 bytes, uno por fila
    subject_dn            TEXT,
    cargo                 TEXT,
    serial                TEXT,               -- serial del certificado emitido (hex)
    not_before            TIMESTAMPTZ,
    not_after             TIMESTAMPTZ,
    key_version           SMALLINT NOT NULL DEFAULT 1, -- rotación futura de signing_key_encryption_key
    estado                TEXT NOT NULL DEFAULT 'pendiente_emision'
                          CHECK (estado IN ('pendiente_emision', 'activo', 'revocado')),
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
    activated_at          TIMESTAMPTZ,
    updated_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Una sola clave de firma no-revocada por usuario — el enroll/re-enroll
-- reemplaza (revoca la fila vieja e inserta una nueva) dentro de la misma
-- transacción, mismo patrón que ``uq_auth_user_totp_activo``.
CREATE UNIQUE INDEX IF NOT EXISTS uq_auth_user_signing_key_activa
    ON auth_user_signing_key (user_id)
    WHERE estado <> 'revocado';

CREATE INDEX IF NOT EXISTS ix_auth_user_signing_key_user ON auth_user_signing_key (user_id);

COMMENT ON TABLE auth_user_signing_key IS
    'Clave de firma PKI personal por-usuario (E17/F4, Incremento 1, custodia '
    'servidor). La clave privada se cifra en reposo (AESGCM) y solo se '
    'descifra en memoria dentro de auth-service, para firmar UN digest — '
    'NUNCA se persiste en claro, ni se loguea, ni figura en respuesta o '
    'evento algunos. GET /me/signing-key jamás la devuelve.';

COMMENT ON COLUMN auth_user_signing_key.private_key_cifrado IS
    'Ciphertext AESGCM de la clave privada RSA-2048 (PEM). AAD = '
    '"tenant:{slug}:user:{user_id}:signing" — ata el ciphertext a la '
    'fila/tenant; movido a otra fila/tenant, el descifrado falla.';

COMMENT ON COLUMN auth_user_signing_key.cert_pem IS
    'Certificado X.509 emitido OFFLINE por scripts/gen-user-cert.sh (o por '
    'una CA de test en memoria en los tests) contra el CSR de esta fila. '
    'NULL mientras estado=''pendiente_emision''. Material PÚBLICO.';

COMMENT ON COLUMN auth_user_signing_key.estado IS
    'pendiente_emision: keygen+CSR listos, a la espera del certificado '
    'emitido offline. activo: certificado cargado, utilizable para firmar. '
    'revocado: reemplazada por un re-enroll o revocada explícitamente.';

-- >>> auth-service/tenant/012_signing_key_revocacion.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 012: revocación de certificados de firma personal PKI +
-- anclaje de la sub-CA de usuarios (E17/F4, Incremento 2 — cierra la Baja #4
-- del incremento anterior). Aditiva sobre ``011_user_signing_key.sql``.
--
-- ``estado`` YA admite 'revocado' desde la 011 (CHECK sin cambios) — este
-- archivo solo añade las columnas que registran CUÁNDO/QUIÉN/POR QUÉ se
-- revocó una credencial, y las dos huellas SHA-256 que ancla la Baja #4:
--
--   - ``certificado_fingerprint``: huella del certificado LEAF (del usuario)
--     — la MISMA que ``activar_certificado`` ya computaba en memoria
--     (``_cert_fingerprint``) pero nunca persistía; ahora se guarda para que
--     ``GET /internal/signing-key/revocation-status`` (signature-service)
--     pueda resolver el estado de revocación por huella SIN reconstruir el
--     certificado.
--   - ``user_ca_fingerprint``: huella de la sub-CA de usuarios (``ca-users.crt``,
--     montada SOLO por su certificado PÚBLICO — nunca ``ca.key``) que emitió
--     ese leaf, verificada por ``activar_certificado`` vía
--     ``leaf.verify_directly_issued_by(sub_ca)`` (fail-closed: un leaf que no
--     encadena con la sub-CA montada nunca llega a 'activo').
--
-- BACKFILL: las filas existentes (``activo``/``revocado`` con ``cert_pem``
-- poblado) no tienen ``certificado_fingerprint`` — se computa aquí mismo
-- (SHA-256 del DER, decodificado del PEM) con ``pgcrypto.digest()`` para que
-- la revocación cubra TAMBIÉN las firmas personales emitidas antes de este
-- incremento (el propio requisito D de la Baja #4: "la revocación cubre
-- TODAS las firmas personales, por identidad del cert"). ``user_ca_fingerprint``
-- NO se backfillea (no hay forma de saber, para una fila histórica, qué sub-CA
-- la emitió sin volver a verificar la cadena — queda NULL; el efecto es que
-- una firma Inc.1 histórica simplemente no entra a la rama de anclaje de
-- ``verify_xades`` — grandfather ESTRUCTURAL, ver docstring de esa función).
--
-- Rollback:
--   DROP INDEX IF EXISTS ix_auth_user_signing_key_certificado_fingerprint;
--   ALTER TABLE auth_user_signing_key
--       DROP COLUMN IF EXISTS revocado_at,
--       DROP COLUMN IF EXISTS revocado_por,
--       DROP COLUMN IF EXISTS motivo_revocacion,
--       DROP COLUMN IF EXISTS certificado_fingerprint,
--       DROP COLUMN IF EXISTS user_ca_fingerprint;

-- pgcrypto (digest()) para el backfill de abajo — instalado en `public`
-- (ya presente en el search_path de toda migración de tenant, ver
-- migrations/runner.py) para que se resuelva sin importar qué tenant
-- ejecute esta migración primero. Idempotente a nivel de BASE DE DATOS
-- (CREATE EXTENSION IF NOT EXISTS no falla si otro tenant ya la instaló).
CREATE EXTENSION IF NOT EXISTS pgcrypto WITH SCHEMA public;

ALTER TABLE auth_user_signing_key
    ADD COLUMN IF NOT EXISTS revocado_at            TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS revocado_por            UUID REFERENCES auth_users(id) ON DELETE SET NULL,
    ADD COLUMN IF NOT EXISTS motivo_revocacion        TEXT,
    ADD COLUMN IF NOT EXISTS certificado_fingerprint  TEXT,
    ADD COLUMN IF NOT EXISTS user_ca_fingerprint       TEXT;

-- Lookup por huella del certificado LEAF — usado por
-- GET /internal/signing-key/revocation-status (signature-service, D-02).
-- Parcial (WHERE NOT NULL): la inmensa mayoría de filas 'pendiente_emision'
-- nunca tienen huella (cert_pem NULL hasta la activación).
CREATE INDEX IF NOT EXISTS ix_auth_user_signing_key_certificado_fingerprint
    ON auth_user_signing_key (certificado_fingerprint)
    WHERE certificado_fingerprint IS NOT NULL;

-- Backfill: SHA-256 del DER del certificado LEAF (mismo cálculo que
-- ``cert.fingerprint(hashes.SHA256()).hex()`` en Python — ver
-- app/services/signing_key_service.py::_cert_fingerprint). ``cert_pem``
-- SIEMPRE debería contener un único certificado (así lo escribe
-- ``activar_certificado``), pero si una fila histórica guardara una CADENA
-- (varios bloques BEGIN/END concatenados, leaf+CA), hashear el PEM completo
-- daría una huella que NO coincide con la del leaf que Python calcula —
-- ``revocation-status`` reportaría ``desconocido`` de forma espuria
-- (fail-closed, sin fuga, pero imperfecto). Por eso el ``substring(... from
-- '...')`` de abajo aísla PRIMERO el primer bloque
-- ``-----BEGIN CERTIFICATE----- ... -----END CERTIFICATE-----`` (no-greedy,
-- ARE de Postgres) ANTES de quitar la armadura/espacios y decodificar
-- base64 — el DER resultante es siempre el del leaf, sin importar cuántos
-- certificados adicionales (CA intermedia, etc.) traiga la fila.
UPDATE auth_user_signing_key
SET certificado_fingerprint = encode(
    public.digest(
        decode(
            regexp_replace(
                substring(
                    cert_pem
                    from '-----BEGIN CERTIFICATE-----.*?-----END CERTIFICATE-----'
                ),
                '-----BEGIN CERTIFICATE-----|-----END CERTIFICATE-----|\s',
                '',
                'g'
            ),
            'base64'
        ),
        'sha256'
    ),
    'hex'
)
WHERE cert_pem IS NOT NULL
  AND certificado_fingerprint IS NULL;

COMMENT ON COLUMN auth_user_signing_key.revocado_at IS
    'Momento de la revocación (self-revoke o admin-revoke) — NULL mientras '
    'estado <> ''revocado''. Fuente de verdad de GET .../revocation-status.';

COMMENT ON COLUMN auth_user_signing_key.revocado_por IS
    'auth_users.id del actor que revocó (el propio titular en self-revoke, '
    'un administrador en admin-revoke). ON DELETE SET NULL: no bloquea '
    'borrar al admin, y la fila revocada en sí ya cae por CASCADE si se '
    'borra su PROPIO titular (user_id, ver 011).';

COMMENT ON COLUMN auth_user_signing_key.motivo_revocacion IS
    'Motivo opcional en texto libre aportado por quien revoca (self-revoke '
    'o admin-revoke). Nunca material de firma.';

COMMENT ON COLUMN auth_user_signing_key.certificado_fingerprint IS
    'SHA-256 hex del DER del certificado LEAF (mismo valor que '
    'certificado_fingerprint en signature-service.firma) — clave de '
    'búsqueda de GET /internal/signing-key/revocation-status. Poblada por '
    'activar_certificado() a partir del Incremento 2; backfilleada aquí '
    'para las filas emitidas antes.';

COMMENT ON COLUMN auth_user_signing_key.user_ca_fingerprint IS
    'SHA-256 hex de la sub-CA de usuarios (ca-users.crt) que emitió este '
    'leaf — verificada por activar_certificado() vía '
    'leaf.verify_directly_issued_by(sub_ca), fail-closed. NULL en filas '
    'emitidas antes del Incremento 2 (grandfather estructural, sin '
    'backfill posible sin volver a verificar la cadena).';

-- >>> auth-service/tenant/013_signing_key_kek_rotation.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
