-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E17/F4 -- rotación de la KEK de custodia): soporte al
-- barrido del re-wrap y a la verificación de retirada de una KEK.
--
-- La columna `key_version` YA existe (migración 011, DEFAULT 1). Esta migración
-- SOLO añade un índice: durante una rotación la inmensa mayoría de filas ya
-- está en la versión activa, así que `WHERE key_version <> activa` (barrido) y
-- `GROUP BY key_version` (conteo de retirada, cross-tenant) se benefician de él.
-- No cambia datos ni el esquema lógico; el tracking de la rotación son los
-- asientos `signing_key.rewrapped` (uno por credencial) en `audit_log` + este
-- conteo por versión, sin tabla nueva.

CREATE INDEX IF NOT EXISTS ix_auth_user_signing_key_key_version
    ON auth_user_signing_key (key_version);

-- Rollback: DROP INDEX IF EXISTS ix_auth_user_signing_key_key_version;

-- >>> auth-service/tenant/014_signing_key_purge_revocada.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E17/F4 -- purga del material privado de credenciales de
-- firma REVOCADAS): minimización de datos. Una privada de FIRMA revocada no
-- tiene uso operativo (el path de firma exige estado='activo'; verificación y
-- revocation-status usan solo el cert PÚBLICO + estado en BD, nunca la privada),
-- así que se ANULA su material (`private_key_cifrado`/`private_key_nonce`) tras
-- una ventana de retención, conservando TODO lo público (la fila NO se borra).
--
-- Cambios: hace NULLABLE el material privado (para poder purgarlo), añade la
-- marca `private_key_purgado_at`, y un CHECK invariante que ata el estado físico:
--   * fila CON material  -> ambas columnas NOT NULL y purgado_at NULL;
--   * fila PURGADA        -> ambas columnas NULL, purgado_at NOT NULL, y
--                            SOLO si estado='revocado' (nunca se purga una activa).
-- Las filas existentes (con material, purgado_at NULL) satisfacen la 1ra rama,
-- así que la migración no falla sobre datos. Idempotente.

ALTER TABLE auth_user_signing_key
    ALTER COLUMN private_key_cifrado DROP NOT NULL,
    ALTER COLUMN private_key_nonce  DROP NOT NULL;

ALTER TABLE auth_user_signing_key
    ADD COLUMN IF NOT EXISTS private_key_purgado_at TIMESTAMPTZ;

ALTER TABLE auth_user_signing_key
    DROP CONSTRAINT IF EXISTS chk_auth_user_signing_key_purga;

ALTER TABLE auth_user_signing_key
    ADD CONSTRAINT chk_auth_user_signing_key_purga CHECK (
        (
            private_key_cifrado    IS NOT NULL
            AND private_key_nonce  IS NOT NULL
            AND private_key_purgado_at IS NULL
        )
        OR (
            private_key_cifrado    IS NULL
            AND private_key_nonce  IS NULL
            AND private_key_purgado_at IS NOT NULL
            AND estado = 'revocado'
        )
    );

COMMENT ON COLUMN auth_user_signing_key.private_key_purgado_at IS
    'Marca de purga del material privado (E17/F4): non-NULL ⟺ private_key_cifrado/nonce anulados. Solo credenciales revocadas se purgan; lo público (cert_pem, huellas, serial, revocado_*) queda intacto para verificación/revocation-status.';

-- Backfill: las credenciales SUPERSEDED por re-enroll se revocaban vía
-- `revoke()` que (antes de este incremento) NO sellaba `revocado_at` (solo
-- `updated_at`). El reloj de la ventana de purga es
-- `COALESCE(revocado_at, updated_at)`, y el re-wrap de KEK mueve `updated_at`
-- -> sin un `revocado_at` inmutable, esas filas nunca vencerían la ventana bajo
-- rotación (hallazgo Media de seguridad). Se congela su reloj al `updated_at`
-- actual. Idempotente (`WHERE ... IS NULL`). `revocado_por`/`motivo` quedan NULL
-- (el supersede no es una revocación atribuible a un actor).
UPDATE auth_user_signing_key
   SET revocado_at = updated_at
 WHERE estado = 'revocado' AND revocado_at IS NULL;

-- >>> auth-service/tenant/015_totp_recovery_codes.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 015: códigos de recuperación del 2FA TOTP (E06, brecha de
-- producto declarada en el roadmap).
--
-- QUÉ PROBLEMA CIERRA. El TOTP (migración 010) es un factor de POSESIÓN: el
-- secreto vive en el teléfono del usuario. Todas las salidas de esa credencial
-- --revocarla (`DELETE /me/totp`), reenrolarla (`POST /me/totp/enroll` sobre una
-- activa) y revocar la clave PERSONAL de firma (`DELETE /me/signing-key`)--
-- exigen un código TOTP vigente, es decir, exigen el mismo teléfono que se
-- perdió. Un usuario que pierde el dispositivo queda ENCERRADO: no puede
-- recuperar su segundo factor ni retirar su credencial de firma, y la única
-- salida era una intervención manual sobre la base de datos.
--
-- POR QUÉ UN HASH Y NO CIFRADO (a diferencia del secreto TOTP). El secreto TOTP
-- se CIFRA porque el servidor necesita recuperarlo en claro para calcular el
-- código esperado. Un código de recuperación no: solo hay que comprobar que el
-- que presenta el usuario es uno de los emitidos. Guardar un hash (scrypt, con
-- sal por código) hace que una copia de esta tabla NO permita autenticarse,
-- mientras que una copia de `auth_user_totp` más la KEK sí. Es una propiedad
-- estrictamente mejor y aquí es alcanzable, así que se toma.
--
-- FRONTERA DE USO (deliberada, no una omisión). Estos códigos sirven para
-- RECUPERAR LA CUENTA -- revocar/reenrolar el TOTP -- y NO para FIRMAR. El
-- endpoint interno `/internal/totp/verify`, que signature-service invoca al
-- firmar, no los acepta: un código de recuperación está escrito en papel o en
-- un gestor de contraseñas, no es posesión de un dispositivo, y admitirlo como
-- segundo factor de un acto de firma debilitaría la atribución que RF-FIR-13
-- persigue. Recuperar el acceso y firmar son actos distintos y se exigen
-- pruebas distintas.
--
-- Rollback:
--   DROP TABLE IF EXISTS auth_user_totp_recovery;

CREATE TABLE IF NOT EXISTS auth_user_totp_recovery (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- Cuelga del TOTP, no del usuario: revocar o reenrolar la credencial
    -- INVALIDA sus códigos por ON DELETE CASCADE... salvo que la fila del TOTP
    -- no se borra, se marca 'revocado'. Por eso el servicio borra los códigos
    -- explícitamente al revocar/reenrolar, dentro de la MISMA transacción --
    -- un código que sobreviviera a la revocación sería una puerta abierta a
    -- una credencial que el usuario ya dio por retirada.
    totp_id       UUID NOT NULL REFERENCES auth_user_totp(id) ON DELETE CASCADE,
    user_id       UUID NOT NULL REFERENCES auth_users(id) ON DELETE CASCADE,
    -- scrypt(code, salt) -- el código en claro NUNCA se persiste ni se loguea,
    -- y se muestra UNA sola vez en la respuesta que lo genera.
    code_hash     BYTEA NOT NULL,
    code_salt     BYTEA NOT NULL,
    -- Consumo de un solo uso. NULL = disponible. El consumo es un UPDATE
    -- condicional (`WHERE used_at IS NULL`) para que dos peticiones
    -- concurrentes con el mismo código no lo gasten dos veces.
    used_at       TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_auth_user_totp_recovery_totp
    ON auth_user_totp_recovery (totp_id);

-- El verify recorre los códigos NO usados del usuario (son ~10): índice parcial
-- para que ese barrido no toque los ya consumidos.
CREATE INDEX IF NOT EXISTS ix_auth_user_totp_recovery_disponibles
    ON auth_user_totp_recovery (user_id)
    WHERE used_at IS NULL;

COMMENT ON TABLE auth_user_totp_recovery IS
    'Códigos de recuperación de un solo uso del 2FA TOTP (E06). Sirven para '
    'RECUPERAR la cuenta (revocar/reenrolar el TOTP perdido), NUNCA para '
    'firmar: /internal/totp/verify no los acepta. Se guardan como hash scrypt '
    'con sal por código -- una copia de esta tabla no permite autenticarse.';

COMMENT ON COLUMN auth_user_totp_recovery.code_hash IS
    'scrypt(code_utf8, salt) con los parámetros de app/core/recovery_codes.py. '
    'El código en claro se muestra UNA vez, al generarlo, y no se persiste.';

COMMENT ON COLUMN auth_user_totp_recovery.used_at IS
    'NULL = disponible. El consumo es un UPDATE condicional WHERE used_at IS '
    'NULL, de modo que dos peticiones concurrentes con el mismo código no lo '
    'gastan dos veces (una gana, la otra ve 0 filas y lo trata como inválido).';

-- >>> auth-service/tenant/016_permissions_tramite.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Los SEIS permisos de trámite que el código exige y que NADIE podía tener.
--
-- Hallazgo de la verificación extremo a extremo del plan MCP funcional
-- (2026-08-16), con un tenant real levantado: `tenant_demo.auth_permissions`
-- traía 20 filas y ninguna de estas. No es una omisión menor:
--
--   * `PERM_TRAMITAR` gatea `assign`, `transfer`, `complete`, `devolver` y
--     `rollback` en workflow-service, y es el suelo de `execute_transaction`.
--   * Los otros cinco los declaran las filas sembradas de `transaction_types`
--     (`workflow-service/migrations/tenant/007`) en su columna
--     `requires_permission`.
--
-- Un permiso que no está en `auth_permissions` no se puede conceder a ningún
-- grupo, así que `resolve_effective_permissions` nunca lo devuelve y el gate
-- niega a todo el mundo salvo a ROOT, que hace bypass. Resultado: **los 12 tipos
-- de transacción sembrados y las cinco escrituras de trámite eran ROOT-only**,
-- falla cerrado —el lado correcto— pero es capacidad que existe en el código y
-- que ninguna entidad podía repartir entre sus funcionarios.
--
-- Es el mismo defecto que `RADI_CREAR`, que abrió este plan: una cadena de
-- permiso inventada que solo vivía en el código que la exigía. Aquel se cazó
-- porque alguien fue a usar la tool; estos, porque se levantó el stack. El
-- guardián que debía cazarlos —`test_todo_permiso_del_catalogo_existe_en_el_
-- sistema`— llevaba desde su primer commit **saltándose** en cada corrida: vive
-- en la imagen de mcp-server, que no monta el repositorio, así que no
-- encontraba las migraciones y hacía `skip`. Se movió a `shared/tests/` (el
-- único carril de CI que ve el repositorio entero) y allí ya no puede saltar.
--
-- Los nombres NO se inventan aquí: se toman literalmente de lo que el código y
-- las migraciones de workflow-service ya exigen. Cambiar el nombre en el gate
-- habría sido la corrección de menos riesgo aparente y la peor: dejaría las
-- filas de `transaction_types` de las entidades ya provisionadas apuntando a un
-- permiso que vuelve a no existir.

INSERT INTO auth_permissions (nombre, descripcion) VALUES
  ('PERM_TRAMITAR',   'Tramitar: asignar, trasladar, completar pasos, devolver y revertir'),
  ('PERM_VOBO',       'Dar visto bueno a un documento en trámite'),
  ('PERM_ANULAR',     'Ejecutar la transacción de anulación en el flujo'),
  ('PERM_CERRAR_EXP', 'Ejecutar la transacción de cierre de expediente en el flujo'),
  ('PERM_INFORMAR',   'Ejecutar la transacción de informar en el flujo'),
  ('PERM_AGENDAR',    'Ejecutar la transacción de agendar en el flujo')
ON CONFLICT (nombre) DO NOTHING;

-- >>> auth-service/tenant/017_permisos_por_tipo_sin_efecto.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Dos permisos otorgables que NO limitan nada, y su descripción decía que sí.
--
-- `PERM_RADI_ENTRADA` y `PERM_RADI_INTERNO` se siembran desde la migración 004
-- con las descripciones «Radicar documentos de Entrada» y «Radicar documentos
-- Internos». Ningún gate del sistema los consulta: los tres tipos de radicado
-- exigen `PERM_RADI` y nada más (verificado: 0 apariciones en
-- `require_permission` de cualquier router). Una entidad puede concederlos
-- creyendo que restringe a un funcionario a radicar solo entradas, y no
-- restringe absolutamente nada.
--
-- Lo que se corrige aquí es **la promesa**, no el comportamiento. Las dos
-- alternativas reales son decisiones de producto, no arreglos, y ninguna es
-- inocua:
--
--   * APLICARLOS es una funcionalidad nueva, no un parche. Y choca con la
--     realidad del tercer hermano: `PERM_RADI_SALIDA` sí se usa —en los 6
--     endpoints de envíos postales—, o sea que hoy significa «gestionar
--     envíos», no «radicar salidas». Exigirlo al radicar una Salida cambiaría
--     su significado para quien ya lo tiene concedido.
--   * RETIRARLOS es un borrado de datos: si una entidad ya los concedió a un
--     grupo, eliminar la fila arrastra su concesión.
--
-- Mientras esa decisión no se tome, lo que NO puede quedarse es un catálogo de
-- permisos que le dice a un administrador que está repartiendo un control que
-- el sistema no ejerce. El texto es lo que esa persona lee en la pantalla de
-- grupos antes de conceder, así que el texto es el sitio donde decirlo.
--
-- Cambio no destructivo: solo `descripcion`. Ninguna concesión se toca.

UPDATE auth_permissions
   SET descripcion = 'RESERVADO — hoy NO restringe nada: los tres tipos de radicado '
