-- >>> auth-service/tenant/018_permisos_inertes_declarados.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- SIETE permisos otorgables que no restringen nada, dicho en su descripción.
--
-- Barrido inverso del guardián de permisos (2026-08-17): de los 26 permisos
-- sembrados, **nueve** no los exige ningún gate ni ninguna fila. De esos nueve:
--
--   * `USUA_PERM_ROOT` es legítimo — no se comprueba con `require_permission`
--     sino por `is_root`, que es el bypass. No entra aquí.
--   * `SGD_PERM_ESTADISTICA` era un hueco REAL y se cerró: la interfaz lo
--     honraba (menú «Reportes») y el backend no. Ya lo exigen
--     `GET /api/v1/reports/radicados` y su gemelo CSV. Tampoco entra aquí.
--   * Los SIETE restantes no tienen ni una sola referencia en todo el
--     repositorio. Son nombres heredados de Orfeo que nunca se cablearon.
--
-- Por qué se corrige la DESCRIPCIÓN y no se borran las filas:
--
--   1. `auth_group_permissions.permission_id` es `ON DELETE CASCADE`. Un
--      `DELETE` arrastraría en silencio las concesiones que una entidad ya haya
--      hecho — silencioso es precisamente lo que estamos quitando de en medio.
--   2. Varios corresponden a funciones que SÍ existen pero están gateadas con
--      un permiso más grueso: `nrr` va por `PERM_TRAMITAR`, la descarga del
--      expediente por `USUA_PERM_EXPEDIENTE`, la anulación por
--      `PERM_SOL_ANULAR`/`PERM_PANU_CODI`. Cablear cada uno a su permiso fino
--      es una decisión de producto por función, no un arreglo; borrarlos
--      cerraría esa puerta sin que nadie la hubiera decidido.
--
-- Lo que NO puede quedarse es un catálogo que le dice a un administrador que
-- está repartiendo un control que el sistema no ejerce. El texto es lo que esa
-- persona lee en la pantalla de grupos justo antes de conceder.
--
-- `shared/tests/test_permisos_existen.py` vigila que esta lista no caduque: si
-- alguien cablea uno de estos permisos, el test exige quitarlo de aquí; y si
-- aparece un permiso inerte nuevo, exige añadirlo. Una lista a mano solo es
-- segura cuando algo deriva la verdad y la compara.
--
-- Cambio no destructivo: solo `descripcion`. Ninguna concesión se toca.

UPDATE auth_permissions SET descripcion =
  'RESERVADO — hoy NO restringe nada. Aprobar una anulación exige PERM_PANU_CODI.'
 WHERE nombre = 'PERM_APRO_ANULAR';

UPDATE auth_permissions SET descripcion =
  'RESERVADO — hoy NO restringe nada: ningún gate del sistema lo consulta.'
 WHERE nombre = 'PERM_BORRAR_ANEXO';

UPDATE auth_permissions SET descripcion =
  'RESERVADO — hoy NO restringe nada. Descargar un expediente exige USUA_PERM_EXPEDIENTE.'
 WHERE nombre = 'PERM_DESCARGAEXP';

UPDATE auth_permissions SET descripcion =
  'RESERVADO — hoy NO restringe nada. La transacción «no requiere respuesta» exige PERM_TRAMITAR.'
 WHERE nombre = 'PERM_NRR';

UPDATE auth_permissions SET descripcion =
  'RESERVADO — hoy NO restringe nada: ningún gate del sistema lo consulta.'
 WHERE nombre = 'PERM_TIPIF_ANEXO';

-- Los dos de la migración 017 se reescriben aquí para que las siete
-- descripciones tengan la misma forma y se reconozcan de un vistazo como lo que
-- son. El texto de 017 decía lo mismo con otras palabras.
UPDATE auth_permissions SET descripcion =
  'RESERVADO — hoy NO restringe nada: los tres tipos de radicado exigen solo PERM_RADI.'
 WHERE nombre IN ('PERM_RADI_ENTRADA', 'PERM_RADI_INTERNO');

-- Y el que SÍ está cableado, cuyo nombre engaña: no gatea radicar Salidas, sino
-- los seis endpoints de envío postal (`document-service/app/routers/postal.py`).
-- Un administrador que lo conceda para «dejar radicar salidas» está concediendo
-- otra cosa, y por eso el trío no se puede aplicar por tipo sin rediseñar antes
-- este nombre.
UPDATE auth_permissions SET descripcion =
  'Gestionar ENVÍOS POSTALES de salida (no restringe radicar Salidas: eso exige solo PERM_RADI).'
 WHERE nombre = 'PERM_RADI_SALIDA';

-- >>> auth-service/tenant/019_motivo_revocacion_vocabulario.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Vocabulario cerrado de `motivo_revocacion` (T8, AREA-04-13).
--
-- `/verify` decide si una revocación POSTERIOR a la firma la deja valida: eso
-- solo es sostenible cuando la clave no se comprometió (ETSI EN 319 102-1). Con
-- texto libre el servidor no puede distinguir «salió el funcionario» de «me
-- robaron la clave». Los códigos siguen RFC 5280 §5.3.1 (reasonCode).
--
-- Las filas existentes con texto libre pasan a `unspecified` (el texto original
-- sigue en `public.audit_log`, payload del asiento `signing_key.revocada`).
-- Idempotente: reejecutable sin efecto.

UPDATE auth_user_signing_key
   SET motivo_revocacion = 'unspecified'
 WHERE motivo_revocacion IS NOT NULL
   AND motivo_revocacion NOT IN (
       'key_compromise', 'superseded', 'cessation_of_operation',
       'affiliation_changed', 'privilege_withdrawn', 'unspecified'
   );

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'auth_user_signing_key_motivo_revocacion_vocab'
           AND conrelid = 'auth_user_signing_key'::regclass
    ) THEN
        ALTER TABLE auth_user_signing_key
            ADD CONSTRAINT auth_user_signing_key_motivo_revocacion_vocab
            CHECK (motivo_revocacion IS NULL OR motivo_revocacion IN (
                'key_compromise', 'superseded', 'cessation_of_operation',
                'affiliation_changed', 'privilege_withdrawn', 'unspecified'
            ));
    END IF;
END
$$;

COMMENT ON COLUMN auth_user_signing_key.motivo_revocacion IS
    'Código cerrado (RFC 5280 reasonCode): key_compromise | superseded | '
    'cessation_of_operation | affiliation_changed | privilege_withdrawn | '
    'unspecified. NULL = no informado (se trata como unspecified). '
    'key_compromise invalida hacia atrás las firmas previas en /verify.';

-- >>> auth-service/tenant/020_permiso_conocimiento.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- PERM_CONOCIMIENTO (ADR-037, tanda C-1): quién puede consultar la base de conocimiento
-- (acceso y circulación restringida, Ley 1581 art. 4 lit. f).
--
-- Hasta hoy las cuatro rutas de knowledge-service (/search, /antecedentes, /rag y
-- /suggestions/{id}/aceptar) no pedían permiso: cualquier autenticado de la entidad
-- las usaba. Nivel 1 (Leer) = buscar, antecedentes y respuestas con citas; nivel 2
-- (Editar) = aceptar una sugerencia propia. Además exige que la entidad tenga
-- activado el asistente (public.tenants.asistente_habilitado) y respeta el nivel de
-- reserva (clearance), que sigue en el WHERE.
--
-- Para no producir un fail-closed mudo, el permiso se concede a todo grupo que exista
-- al aplicar la migración Y que ya tenga algún permiso con nivel >= 1 (un grupo vacío
-- no estaba usando nada; recibir acceso a la IA sin pedirlo sería un permiso nuevo, no
-- la continuidad). El nivel sale del propio grupo: quien solo tiene permisos de lectura
-- queda en 1 (consulta, no acepta); quien escribe queda en 2. En un tenant
-- nuevo la migración corre durante la provisión, antes de que haya grupos: no concede
-- nada y el administrador lo reparte a conciencia. ROOT no necesita fila (is_root).

INSERT INTO auth_permissions (nombre, descripcion) VALUES
  ('PERM_CONOCIMIENTO',
   'Usar la base de conocimiento: búsqueda semántica, antecedentes y respuestas con citas (nivel 1); aceptar una sugerencia propia (nivel 2). Además exige que la entidad tenga activado el asistente y respeta el nivel de reserva.')
ON CONFLICT (nombre) DO NOTHING;

INSERT INTO auth_group_permissions (group_id, permission_id, crud)
SELECT g.id, p.id, LEAST(2, mx.max_crud)
  FROM auth_groups g
  CROSS JOIN auth_permissions p
  CROSS JOIN LATERAL (
        SELECT max(gp.crud) AS max_crud FROM auth_group_permissions gp WHERE gp.group_id = g.id
       ) mx
 WHERE p.nombre = 'PERM_CONOCIMIENTO'
   AND mx.max_crud >= 1   -- un grupo sin permisos (o todos en 0) no gana uno por esta vía
ON CONFLICT (group_id, permission_id) DO NOTHING;

