-- >>> tenant-service/tenant/013_dependencia_codigo_inmutable.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 013: la dependencia se correlaciona por CÓDIGO (B5, ADR-032).
-- search_path = tenant_{slug} (ADR-012).
--
--   1. `dependencias.codigo` pasa a ser INMUTABLE (trigger): es la llave con la
--      que 8+ tablas de 5 servicios correlacionan, todas sin FK.
--   2. `nombre` <= 100 caracteres (las instantáneas de flujo son VARCHAR(100)).
--   3. `dependencia_nombre_historico`: nombres anteriores (renombres) y mapeos
--      manuales decididos por un humano. Solo inserción.
--   4. `resolver_codigo_dependencia(nombre, historico)`: UNA definición del
--      criterio «nombre -> código» para los backfills, el alias deprecado de
--      las APIs y el replay de la cola de eventos fallidos.
--
-- Idempotente: CREATE ... IF NOT EXISTS / OR REPLACE / DROP TRIGGER IF EXISTS.
-- Rollback: DROP FUNCTION/TABLE/TRIGGER/CONSTRAINT; ningún dato se reescribe.

-- 1. codigo inmutable ---------------------------------------------------------
CREATE OR REPLACE FUNCTION reject_dependencia_codigo_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.codigo IS DISTINCT FROM OLD.codigo THEN
        RAISE EXCEPTION 'dependencia_codigo_inmutable: el código de una dependencia no se puede cambiar (% -> %)',
            OLD.codigo, NEW.codigo
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_dependencias_codigo_inmutable ON dependencias;
CREATE TRIGGER trg_dependencias_codigo_inmutable
    BEFORE UPDATE OF codigo ON dependencias
    FOR EACH ROW EXECUTE FUNCTION reject_dependencia_codigo_change();

-- 2. nombre <= 100 --------------------------------------------------------------
DO $$
DECLARE
    largas text;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint c JOIN pg_namespace n ON n.oid = c.connamespace
         WHERE n.nspname = current_schema() AND c.conname = 'ck_dependencias_nombre_len'
    ) THEN
        SELECT string_agg(format('%s (%s caracteres)', codigo, char_length(nombre)), ', ')
          INTO largas FROM dependencias WHERE char_length(nombre) > 100;
        IF largas IS NOT NULL THEN
            RAISE EXCEPTION 'dependencias con nombre > 100 caracteres: % — acórtelos antes de migrar', largas;
        END IF;
        ALTER TABLE dependencias
            ADD CONSTRAINT ck_dependencias_nombre_len CHECK (char_length(nombre) <= 100);
    END IF;
END
$$;

-- 3. historial de nombres / mapeos manuales (solo inserción) ---------------------
CREATE TABLE IF NOT EXISTS dependencia_nombre_historico (
    id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    codigo        INTEGER      NOT NULL,
    nombre        TEXT         NOT NULL,
    origen        VARCHAR(30)  NOT NULL CHECK (origen IN ('renombre', 'mapeo_manual')),
    motivo        TEXT,
    registrado_por UUID,
    at            TIMESTAMPTZ  NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_dependencia_nombre_historico_nombre
    ON dependencia_nombre_historico (nombre);

CREATE OR REPLACE FUNCTION reject_dependencia_nombre_historico_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'dependencia_nombre_historico es de solo inserción (% bloqueado)', TG_OP
        USING ERRCODE = 'check_violation';
END
$$;

DROP TRIGGER IF EXISTS trg_dependencia_nombre_historico_solo_insercion ON dependencia_nombre_historico;
CREATE TRIGGER trg_dependencia_nombre_historico_solo_insercion
    BEFORE UPDATE OR DELETE ON dependencia_nombre_historico
    FOR EACH ROW EXECUTE FUNCTION reject_dependencia_nombre_historico_mutation();

-- 4. resolución nombre -> código ---------------------------------------------------
-- p_historico = false: solo dependencias ACTIVAS con ese nombre actual (alias de
-- API). p_historico = true: activas, inactivas, nombres anteriores y mapeos
-- manuales (backfills y replay de la cola de fallidos). `candidatos` distingue
-- huérfano (0) de ambiguo (>=2); `codigo` es NULL salvo con exactamente 1.
CREATE OR REPLACE FUNCTION resolver_codigo_dependencia(p_nombre text, p_historico boolean)
RETURNS TABLE (codigo integer, candidatos integer)
LANGUAGE sql STABLE AS $$
    WITH c AS (
        SELECT d.codigo AS cod FROM dependencias d
         WHERE d.nombre = p_nombre AND (p_historico OR d.activo)
        UNION
        SELECT h.codigo AS cod FROM dependencia_nombre_historico h
         WHERE p_historico AND h.nombre = p_nombre
    )
    SELECT CASE WHEN count(*) = 1 THEN min(c.cod) END, count(*)::int FROM c
$$;

-- >>> tenant-service/tenant/014_dependencia_endurecimiento.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant 014 (B5, ronda de corrección, ADR-032). search_path = tenant_{slug}.
--
--   1. `resolver_codigo_dependencia`: con `p_historico`, un MAPEO MANUAL para ese
--      nombre ES la respuesta (la decisión humana gana a la coincidencia
--      textual). Antes el UNION lo mezclaba con las dependencias homónimas y el
--      mapeo no podía desambiguar nunca: el RAISE de la 019 de workflow no tenía
--      salida. Dos mapeos con códigos distintos siguen siendo ambiguos.
--   2. `SET search_path FROM CURRENT` en la función y en los triggers de la 013:
--      la resolución de `dependencias` no depende del search_path del llamador.
--   3. `dependencia_codigo_retirado` (solo inserción): el código de una
--      dependencia ELIMINADA no se reutiliza jamás; un trigger BEFORE INSERT
--      rechaza crear una dependencia con código retirado o con historial de
--      nombres huérfano. Cierra el hueco de «borrar y recrear el código con otra
--      identidad» que dejaba a los trámites viejos apuntando a otra unidad.
--   4. Siembra de `dependencia_nombre_historico` (origen 'renombre') desde los
--      asientos `dependencia.actualizada` de `public.audit_log` anteriores a B5
--      cuyo payload trae antes.nombre <> despues.nombre.
--
-- Idempotente: CREATE ... IF NOT EXISTS / OR REPLACE / DROP TRIGGER IF EXISTS,
-- siembra con NOT EXISTS. Rollback: DROP TABLE/TRIGGER/FUNCTION de esta migración.

-- 1 y 2. resolución y search_path -----------------------------------------------------
CREATE OR REPLACE FUNCTION resolver_codigo_dependencia(p_nombre text, p_historico boolean)
RETURNS TABLE (codigo integer, candidatos integer)
LANGUAGE sql STABLE
SET search_path FROM CURRENT
AS $$
    WITH mapeo AS (
        SELECT DISTINCT h.codigo AS cod FROM dependencia_nombre_historico h
         WHERE p_historico AND h.origen = 'mapeo_manual' AND h.nombre = p_nombre
    ),
    c AS (
        SELECT m.cod FROM mapeo m
        UNION
        SELECT d.codigo FROM dependencias d
         WHERE NOT EXISTS (SELECT 1 FROM mapeo)
           AND d.nombre = p_nombre AND (p_historico OR d.activo)
        UNION
        SELECT h.codigo FROM dependencia_nombre_historico h
         WHERE p_historico AND NOT EXISTS (SELECT 1 FROM mapeo)
           AND h.origen = 'renombre' AND h.nombre = p_nombre
    )
    SELECT CASE WHEN count(*) = 1 THEN min(c.cod) END, count(*)::int FROM c
$$;

ALTER FUNCTION reject_dependencia_codigo_change() SET search_path FROM CURRENT;
ALTER FUNCTION reject_dependencia_nombre_historico_mutation() SET search_path FROM CURRENT;

-- 3. códigos retirados -----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS dependencia_codigo_retirado (
    codigo      INTEGER     PRIMARY KEY,
    nombre      TEXT        NOT NULL,
    retirado_por UUID,
    retirado_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION reject_dependencia_codigo_retirado_mutation() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
    RAISE EXCEPTION 'dependencia_codigo_retirado es de solo inserción (% bloqueado)', TG_OP
        USING ERRCODE = 'check_violation';
END
$$;

DROP TRIGGER IF EXISTS trg_dependencia_codigo_retirado_solo_insercion ON dependencia_codigo_retirado;
CREATE TRIGGER trg_dependencia_codigo_retirado_solo_insercion
    BEFORE UPDATE OR DELETE ON dependencia_codigo_retirado
    FOR EACH ROW EXECUTE FUNCTION reject_dependencia_codigo_retirado_mutation();

-- Un código retirado no vuelve; tampoco uno con historial de nombres y sin
-- dependencia viva (se borró por fuera de la API). Si la dependencia con ese
-- código existe, el INSERT (p. ej. ON CONFLICT DO NOTHING de un seed) lo resuelve
-- la clave única y no es asunto de este trigger.
CREATE OR REPLACE FUNCTION reject_dependencia_codigo_reutilizado() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
    IF EXISTS (SELECT 1 FROM dependencia_codigo_retirado r WHERE r.codigo = NEW.codigo)
       OR (EXISTS (SELECT 1 FROM dependencia_nombre_historico h WHERE h.codigo = NEW.codigo)
           AND NOT EXISTS (SELECT 1 FROM dependencias d WHERE d.codigo = NEW.codigo)) THEN
        RAISE EXCEPTION 'dependencia_codigo_retirado: el código % perteneció a una dependencia eliminada y no se reutiliza', NEW.codigo
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_dependencias_codigo_no_reutilizable ON dependencias;
CREATE TRIGGER trg_dependencias_codigo_no_reutilizable
    BEFORE INSERT ON dependencias
    FOR EACH ROW EXECUTE FUNCTION reject_dependencia_codigo_reutilizado();

-- 4. siembra del historial de nombres desde el audit_log ------------------------------------
-- Solo asientos con antes.nombre <> despues.nombre. El código sale del payload
-- (B5 en adelante) o de la dependencia citada en object_ref; sin ninguno de los
-- dos (dependencia ya eliminada y asiento antiguo) no se inventa nada.
INSERT INTO dependencia_nombre_historico (codigo, nombre, origen, motivo)
SELECT s.codigo, s.nombre, 'renombre',
       format('Sembrado desde audit_log (asiento %s, B5/014)', s.audit_id)
  FROM (
        SELECT DISTINCT ON (x.codigo, x.nombre) x.codigo, x.nombre, x.audit_id
          FROM (
                SELECT COALESCE(NULLIF(a.payload ->> 'codigo', '')::int, d.codigo) AS codigo,
                       a.payload #>> '{antes,nombre}' AS nombre,
                       a.id AS audit_id
                  FROM public.audit_log a
                  LEFT JOIN dependencias d ON d.id::text = a.object_ref
                 WHERE a.action = 'dependencia.actualizada'
                   AND a.tenant_slug = COALESCE(
                         (SELECT t.slug FROM public.tenants t
                           WHERE 'tenant_' || replace(t.slug, '-', '_') = current_schema()),
                         regexp_replace(current_schema(), '^tenant_', ''))
                   AND a.payload #>> '{antes,nombre}' IS NOT NULL
                   AND a.payload #>> '{despues,nombre}' IS NOT NULL
                   AND a.payload #>> '{antes,nombre}' <> a.payload #>> '{despues,nombre}'
               ) x
         WHERE x.codigo IS NOT NULL
         ORDER BY x.codigo, x.nombre, x.audit_id
       ) s
 WHERE NOT EXISTS (SELECT 1 FROM dependencia_nombre_historico h
                    WHERE h.codigo = s.codigo AND h.nombre = s.nombre AND h.origen = 'renombre');

-- >>> tenant-service/tenant/015_dependencia_sin_ciclos.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant 015 (C-4 / C8, ADR-040). search_path = tenant_{slug}.
--
-- El organigrama es un ÁRBOL, y nada lo imponía: el router solo rechazaba
-- `parent_id == id`, así que A -> B -> A pasaba, y `/dependencias/tree` hacía
-- desaparecer en silencio los nodos del ciclo (ninguno es raíz). Ahora que el
-- cuadro de clasificación (fondo > sección > subsección) se deriva de él, un
-- ciclo convertiría un dato corrupto en un cuadro incompleto que parece completo.
--
--   1. La migración ABORTA si ya hay un ciclo, listando los códigos (sin backfill:
--      qué enlace romper es una decisión humana).
--   2. Trigger BEFORE INSERT OR UPDATE OF parent_id: toma un candado consultivo por
--      schema (sin él, A.parent=B y B.parent=A concurrentes pasan las dos
--      comprobaciones) y sube desde el nuevo padre; si alcanza la propia fila, rechaza
--      con `dependencia_ciclo` (check_violation, que el router mapea a 409).
--
-- Idempotente: OR REPLACE / DROP TRIGGER IF EXISTS.

-- 1. verificación previa ---------------------------------------------------------
DO $$
DECLARE
    en_ciclo text;
BEGIN
    WITH RECURSIVE sube AS (
        SELECT d.id AS origen, d.parent_id AS actual, 1 AS prof FROM dependencias d
        UNION ALL
        SELECT s.origen, p.parent_id, s.prof + 1
          FROM sube s JOIN dependencias p ON p.id = s.actual
         WHERE s.prof < 1000
    )
    SELECT string_agg(DISTINCT d.codigo::text, ', ')
      INTO en_ciclo
      FROM sube s JOIN dependencias d ON d.id = s.origen
     WHERE s.actual = s.origen;
    IF en_ciclo IS NOT NULL THEN
        RAISE EXCEPTION 'dependencias en ciclo (codigos: %) — rompa el enlace parent_id de alguna antes de migrar (C-4/C8)', en_ciclo;
    END IF;
END
$$;

-- 2. trigger anticiclos -------------------------------------------------------------
CREATE OR REPLACE FUNCTION reject_dependencia_ciclo() RETURNS trigger
LANGUAGE plpgsql SET search_path FROM CURRENT AS $$
BEGIN
    IF NEW.parent_id IS NULL THEN
        RETURN NEW;
    END IF;
    IF TG_OP = 'UPDATE' THEN
        IF NEW.parent_id IS NOT DISTINCT FROM OLD.parent_id THEN
            RETURN NEW;
        END IF;
    END IF;

    -- Serializa los cambios de forma del árbol del schema: dos transacciones que
    -- cierran el ciclo cada una por su lado no se ven hasta confirmar.
    PERFORM pg_advisory_xact_lock(hashtext(current_schema() || ':dependencias_arbol'));

    IF NEW.parent_id = NEW.id THEN
        RAISE EXCEPTION 'dependencia_ciclo: una dependencia no puede ser su propio padre'
            USING ERRCODE = 'check_violation';
    END IF;

    IF EXISTS (
        WITH RECURSIVE arriba AS (
            SELECT d.id, d.parent_id FROM dependencias d WHERE d.id = NEW.parent_id
            UNION
            SELECT d.id, d.parent_id FROM dependencias d JOIN arriba a ON d.id = a.parent_id
        )
        SELECT 1 FROM arriba WHERE id = NEW.id
    ) THEN
        RAISE EXCEPTION 'dependencia_ciclo: el nuevo padre es descendiente de la dependencia (cerraria un ciclo en el organigrama)'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END
$$;

DROP TRIGGER IF EXISTS trg_dependencias_sin_ciclos ON dependencias;
CREATE TRIGGER trg_dependencias_sin_ciclos
    BEFORE INSERT OR UPDATE OF parent_id ON dependencias
    FOR EACH ROW EXECUTE FUNCTION reject_dependencia_ciclo();

-- Rollback: DROP TRIGGER trg_dependencias_sin_ciclos ON dependencias;
--   DROP FUNCTION reject_dependencia_ciclo();

-- >>> tenant-service/tenant/016_search_path_sin_public.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 016: re-fija el `search_path` de las funciones del schema sin `public`
-- (ADR-002, addendum C-7 / SEG #12).
--
-- El runner capturaba `SET search_path FROM CURRENT` = `"tenant_x", public` en las
-- funciones creadas por migraciones anteriores (dependencia por código, ciclos de
-- dependencias, TRD productora...). Con el runner nuevo (solo el tenant) las nuevas ya
-- nacen bien; aquí se corrigen las existentes SIN depender del orden de los servicios:
-- toda función del schema cuyo `proconfig` fije un `search_path` que nombre `public`.
-- En un tenant nuevo es un no-op.

DO $$
DECLARE
    f regprocedure;
BEGIN
    FOR f IN
        SELECT p.oid::regprocedure
          FROM pg_proc p
         WHERE p.pronamespace = current_schema()::regnamespace
           AND EXISTS (
                SELECT 1 FROM unnest(p.proconfig) AS c
                 WHERE c LIKE 'search_path=%'
                   AND c ~ '(^|[=, ])"?public"?($|[, ])'
           )
    LOOP
        EXECUTE format('ALTER FUNCTION %s SET search_path = %I', f, current_schema());
    END LOOP;
END $$;

-- >>> document-service/tenant/001_create_documents.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-012): tablas de radicación por institución.
--
-- El runner aplica este archivo dentro de CADA schema tenant_{slug}
-- (SET LOCAL search_path), nunca en public. Así `tracking_sequences` es
-- por-tenant: la numeración no se comparte entre instituciones.
--
-- El schema public sólo retiene el registro de tenants (tenant-service).

CREATE TABLE IF NOT EXISTS tracking_sequences (
    year        INTEGER     NOT NULL,
    doc_type    VARCHAR(1)  NOT NULL,  -- 'E', 'S', 'I'
    last_seq    INTEGER     NOT NULL DEFAULT 0,
    PRIMARY KEY (year, doc_type)
);

CREATE TABLE IF NOT EXISTS radicados (
    id              UUID        NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    tracking_number VARCHAR(50) NOT NULL UNIQUE,
    doc_type        VARCHAR(1)  NOT NULL,
    year            INTEGER     NOT NULL,
    sequence        INTEGER     NOT NULL,

    -- Document classification
    subject         TEXT        NOT NULL,
    doc_class       VARCHAR(100),

    -- Origin and destination
    origin_dept     VARCHAR(100),
    dest_dept       VARCHAR(100),
    sender_name     VARCHAR(255),
    sender_entity   VARCHAR(255),

    -- Lifecycle status
    status          VARCHAR(20) NOT NULL DEFAULT 'registered',

    -- Metadata
    pages           INTEGER     NOT NULL DEFAULT 0,
    observations    TEXT,
    registered_by   UUID,
    registered_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    -- Denormalized tenant code for tracking number reconstruction
    tenant_code     VARCHAR(20) NOT NULL
);

CREATE TABLE IF NOT EXISTS anexos (
    id          UUID        NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    radicado_id UUID        NOT NULL REFERENCES radicados(id) ON DELETE CASCADE,
    -- file_id is the UUID returned by storage-service; no FK across services
    file_id     UUID        NOT NULL,
    filename    VARCHAR(255) NOT NULL,
    file_size   BIGINT,
    mime_type   VARCHAR(100),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_radicados_tracking_number ON radicados (tracking_number);
CREATE INDEX IF NOT EXISTS ix_radicados_doc_type        ON radicados (doc_type);
CREATE INDEX IF NOT EXISTS ix_radicados_status          ON radicados (status);
CREATE INDEX IF NOT EXISTS ix_radicados_registered_at   ON radicados (registered_at);
CREATE INDEX IF NOT EXISTS ix_anexos_radicado_id        ON anexos (radicado_id);

