-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E08, RF-SEG-08 / RF-BUS-04): nivel de seguridad del radicado.
--
-- Implementa la pieza que faltaba del control de acceso: la matriz rol→nivel máximo
-- (role_clearance) y el catálogo de niveles (security_levels) ya viven en el schema
-- del tenant (auth-service, tenant/003_classification.sql), pero el NIVEL CONCRETO de
-- cada documento lo guarda document-service. Esta columna lo materializa.
--
-- Escala (idéntica a security_levels.code): 1=PUBLICA, 2=RESERVADA, 3=CLASIFICADA.
-- DEFAULT 1 (PUBLICA): todo radicado existente y todo el que no se clasifique queda
-- accesible para cualquier usuario autenticado — no rompe el comportamiento previo.
-- La búsqueda (E09) filtra `nivel_seguridad <= clearance_del_llamante` (no read-up,
-- mínimo privilegio, ADR-013: la BD autoriza).

ALTER TABLE radicados
    ADD COLUMN IF NOT EXISTS nivel_seguridad SMALLINT NOT NULL DEFAULT 1;

ALTER TABLE radicados
    DROP CONSTRAINT IF EXISTS ck_radicados_nivel_seguridad;
ALTER TABLE radicados
    ADD CONSTRAINT ck_radicados_nivel_seguridad
    CHECK (nivel_seguridad BETWEEN 1 AND 3);

CREATE INDEX IF NOT EXISTS ix_radicados_nivel_seguridad ON radicados (nivel_seguridad);

-- >>> document-service/tenant/017_postal_webhook.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E20, F5): integración con operador postal como consumidor
-- de webhooks. El operador (4-72/Servientrega) notifica el estado de entrega a un
-- callback ENTRANTE idempotente; se autentica por HMAC-SHA256 con un secreto
-- per-tenant/per-operador (vive en el schema del tenant → un operador de otro
-- tenant no puede firmar callbacks de éste) y se deduplica por (operador,
-- event_id). Cierra el residual D-14 #3 (identidad del callback separada del
-- permiso humano de despacho). Añade `motivo_devolucion` de primera clase
-- (spec invariante 5: devolución trazable).

-- Motivo de devolución como columna propia del envío (antes solo quedaba en el
-- descripcion del evento). Se puebla al pasar a 'devuelto'.
ALTER TABLE postal_shipment
    ADD COLUMN IF NOT EXISTS motivo_devolucion TEXT;

-- Secreto HMAC por operador. FAIL-CLOSED: sin fila para un operador, TODO
-- callback de ese operador se rechaza (401) — no hay modo "abierto" por omisión
-- (mismo principio que internal_service_token / D-02).
CREATE TABLE IF NOT EXISTS postal_operator_credential (
    operador       VARCHAR(20) PRIMARY KEY,
    webhook_secret TEXT NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Registro de deduplicación del webhook (idempotencia bajo entrega at-least-once).
-- Una notificación identificada por (operador, event_id) se aplica UNA sola vez;
-- el reintento del operador cae en el UNIQUE y es un no-op (200 duplicate).
CREATE TABLE IF NOT EXISTS postal_webhook_delivery (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    operador        VARCHAR(20) NOT NULL,
    event_id        VARCHAR(120) NOT NULL,
    guia            VARCHAR(60) NOT NULL,
    estado_operador VARCHAR(40) NOT NULL,
    estado_interno  VARCHAR(16),                 -- NULL si no aplicó transición
    shipment_id     UUID REFERENCES postal_shipment(id) ON DELETE SET NULL,
    aplicada        BOOLEAN NOT NULL DEFAULT FALSE,
    received_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    UNIQUE (operador, event_id)
);
CREATE INDEX IF NOT EXISTS ix_postal_delivery_guia ON postal_webhook_delivery (guia);

-- >>> document-service/tenant/018_radicado_clasificacion_meta.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E08): metadata de clasificación VIGENTE del radicado, para
-- el índice de información clasificada y reservada (Ley 1712/2014 art. 20 +
-- Decreto 1081/2015). El `audit_log` sigue siendo el registro LEGAL inmutable del
-- acto de clasificación (hash-chain); estas columnas son la PROYECCIÓN del estado
-- vigente para poder generar el índice con una consulta directa (sin reconstruir
-- el "último evento por objeto" del log). Se pueblan al reclasificar a nivel ≥ 2
-- y se LIMPIAN al desclasificar (nivel = 1).

ALTER TABLE radicados
    ADD COLUMN IF NOT EXISTS clasificacion_fundamento TEXT,
    ADD COLUMN IF NOT EXISTS clasificacion_causal TEXT,
    ADD COLUMN IF NOT EXISTS clasificacion_plazo_meses INTEGER,
    ADD COLUMN IF NOT EXISTS clasificado_at TIMESTAMPTZ;

-- Índice parcial: el registro solo incluye los radicados clasificados/reservados
-- (nivel ≥ 2), así que el índice cubre exactamente esa población.
CREATE INDEX IF NOT EXISTS ix_radicados_clasificados
    ON radicados (nivel_seguridad, registered_at DESC)
    WHERE nivel_seguridad >= 2;

-- >>> document-service/tenant/019_radicado_publicable.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (11.1): esquema de publicación — Ley 1712/2014 art. 12.
--
-- ── El problema ──────────────────────────────────────────────────────────────
-- Hasta ahora, «público» se DEDUCÍA: un radicado con `nivel_seguridad = 1` y no
-- anulado era cosechable por OAI-PMH y servible por CMIS. Es decir, la ausencia
-- de una decisión de reserva se interpretaba como una decisión de publicación.
--
-- No son lo mismo, ni jurídica ni operativamente. El art. 12 de la Ley 1712
-- exige que el sujeto obligado adopte un **esquema de publicación**: un acto
-- por el que la entidad decide qué información difunde de oficio. Deducirlo del
-- nivel de clasificación significa que un documento se publica por omisión —
-- por no haberse clasificado todavía, por haberse creado con el default, o por
-- una desclasificación hecha con otro propósito.
--
-- El bloque 2 puso un kill-switch de canal (`ENABLE_PUBLIC_INTEROP`) que apaga
-- la interoperabilidad pública entera. Eso ataja la urgencia pero no distingue:
-- o todo o nada. Esta columna es el control fino que faltaba.
--
-- ── El diseño ────────────────────────────────────────────────────────────────
-- `publicable` es un acto POSITIVO y explícito, con `DEFAULT FALSE`: ningún
-- documento existente ni futuro se publica por no haber dicho nada. Se combina
-- con el filtro de clasificación (no lo sustituye — ver `oai_repository._PUBLIC`):
-- publicar algo reservado sigue siendo imposible aunque alguien marque la
-- casilla, porque ambas condiciones tienen que cumplirse.
--
-- El quién y el cuándo se guardan aquí para poder responder «desde cuándo es
-- pública esta información» sin recorrer la cadena de auditoría; el POR QUÉ y la
-- reversión viven en `audit_log`, que es el registro con valor probatorio.

ALTER TABLE radicados
    ADD COLUMN IF NOT EXISTS publicable    BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS publicado_at  TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS publicado_por UUID;

COMMENT ON COLUMN radicados.publicable IS
    'Esquema de publicación (Ley 1712/2014 art. 12): acto EXPLÍCITO por el que la '
    'entidad difunde el documento de oficio. FALSE por defecto — la ausencia de '
    'reserva no equivale a una decisión de publicar. Condición NECESARIA pero no '
    'suficiente: el recorte público exige además nivel_seguridad = 1 y no anulado.';

-- Índice parcial: las consultas públicas (OAI-PMH, CMIS, portal) filtran siempre
-- por este conjunto, que es una fracción pequeña del total de radicados.
CREATE INDEX IF NOT EXISTS ix_radicados_publicables
    ON radicados (registered_at)
    WHERE publicable AND nivel_seguridad = 1 AND status <> 'anulado';

-- >>> document-service/tenant/020_search_unaccent.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- El índice de búsqueda de radicados deja de distinguir acentos (ADR-014).
--
-- Ver `global/002_spanish_unaccent.sql` para el porqué. Aquí se RECREA la
-- columna generada: su expresión forma parte de la definición de la columna, y
-- Postgres no permite alterarla en sitio. Al recrearla, el `search_vector` de
-- cada fila se recalcula — que es justamente el backfill que hace falta, porque
-- un índice viejo con acentos seguiría sin encontrar nada aunque la consulta
-- cambie. Las dos mitades tienen que moverse juntas.
--
-- El `regconfig` va CUALIFICADO y con cast explícito (`'public.spanish_unaccent'::regconfig`):
-- `to_tsvector(text, text)` es STABLE y una columna generada exige IMMUTABLE, así
-- que la variante de dos textos ni siquiera se acepta aquí.
--
-- Idempotente: el guard mira si la columna ya usa la configuración nueva. Sin él,
-- reejecutar la migración recalcularía el índice entero de una entidad grande sin
-- necesidad.

DO $$
DECLARE
    v_expr text;
BEGIN
    SELECT pg_get_expr(d.adbin, d.adrelid)
      INTO v_expr
      FROM pg_attrdef d
      JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
      JOIN pg_class c ON c.oid = d.adrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE c.relname = 'radicados'
       AND a.attname = 'search_vector'
       AND n.nspname = current_schema();

    IF v_expr IS NULL OR v_expr NOT LIKE '%spanish_unaccent%' THEN
        ALTER TABLE radicados DROP COLUMN IF EXISTS search_vector;

        ALTER TABLE radicados
            ADD COLUMN search_vector tsvector
            GENERATED ALWAYS AS (
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(tracking_number, '')), 'A') ||
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(subject, '')), 'B') ||
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(sender_name, '')), 'C') ||
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(sender_entity, '')), 'C') ||
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(dest_dept, '')), 'D') ||
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(observations, '')), 'D')
            ) STORED;

        -- El índice cae con la columna; se vuelve a crear con el mismo nombre.
        CREATE INDEX IF NOT EXISTS ix_radicados_search_vector
            ON radicados USING GIN (search_vector);
    END IF;
END
$$;

-- >>> document-service/tenant/021_email_cuentas.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: se distribuye bajo la Licencia Pública General Affero de GNU
-- (AGPL) versión 3 o posterior. Véase LICENSE y <https://www.gnu.org/licenses/>.

-- ============================================================================
-- E19 Increment 1 — Cuentas de correo para radicación.
--
-- Sustituye la cuenta ÚNICA en variables de entorno (IMAP_HOST/IMAP_USER/...)
-- por un catálogo por entidad. No es una comodidad: el Acuerdo AGN 060/2001
-- art. 13 dice que las entidades «reglamentarán su utilización y asignarán
-- responsabilidades de acuerdo con la cantidad de cuentas habilitadas», y el
-- art. 3 deja el control en la unidad de correspondencia. Una sola cuenta
-- global en el entorno no puede expresar ni la asignación ni el control.
--
-- Dos tipos, porque las entidades trabajan de las dos formas:
--   · institucional — buzón de la ventanilla, COMPARTIDO por varios
--     funcionarios (`email_cuenta_usuario` dice quiénes). Es el que necesita
--     reclamación y aviso de recarga: dos personas mirando la misma bandeja.
--   · personal — el correo del propio funcionario. Su credencial NO se guarda
--     (ver más abajo); se pide al entrar y vive en la sesión, como en el
--     `lock.php` del Orfeo legacy.
--
-- CARPETA parametrizable, y esto es una capacidad NUEVA: el Orfeo legacy
-- abría siempre INBOX (`imap_open` sin sufijo de buzón). La práctica real de
-- las entidades es que una persona revisa el correo y ARRASTRA a una carpeta
-- lo que sí es para radicar, dejando fuera publicidad y spam. Esa carpeta es
-- un filtro humano previo, y por eso `carpeta_origen` es configurable en vez
-- de estar fijada a INBOX.
-- ============================================================================

-- ============================================================================
-- Aplicación OAuth2 registrada por la ENTIDAD ante su proveedor de correo.
--
-- **Por qué es de la entidad y no del despliegue, ni del alta del tenant.**
--
-- Google exige verificación y una evaluación de seguridad CASA anual —cara y
-- por un tercero acreditado— a cualquier aplicación que pida el scope
-- `https://mail.google.com/`, que es el que cubre IMAP. Pero exime
-- explícitamente a las aplicaciones internas: «The app is only used by people
-- in your Google Workspace or Cloud Identity organization. The project must be
-- owned by the organization, and its OAuth Consent Screen must be configured
-- for internal use.» Si cada entidad registra la suya dentro de su propia
-- organización, no pasa por ese proceso. Con una aplicación única de OrpycaMCP
-- para todos, sí habría que pasarlo — y OrpycaMCP es software que cada
-- institución despliega por su cuenta, no un servicio central que pueda
-- sostener esa acreditación. En Microsoft el equivalente es una aplicación
-- *single-tenant* en el Azure AD de la entidad, sin consentimiento cruzado.
--
-- Además es lo correcto en soberanía: la entidad ve qué aplicación accede a su
-- correo, con qué permisos, y puede revocarla sin depender de nadie.
--
-- **No va en el alta del tenant**, y es deliberado: cuando se crea la entidad
-- nadie sabe todavía qué correo usará, quien la da de alta no suele tener los
-- permisos de administrador de Azure o Google Cloud a mano, y muchas entidades
-- trabajarán contra IMAP de hosting sin necesitar nada de esto. Exigirlo en el
-- alta bloquearía la creación de la institución por un dato que puede tardar
-- semanas. Se registra al configurar la primera cuenta OAuth2, desde
-- `/admin/correo`.
--
-- Una fila por proveedor y entidad: la misma aplicación sirve para todas sus
-- cuentas (PQRS, notificaciones judiciales, facturación…).
-- ============================================================================

CREATE TABLE IF NOT EXISTS email_app_oauth (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    proveedor           VARCHAR(20)  NOT NULL,

    client_id           VARCHAR(255) NOT NULL,
    -- Cifrado con el mismo esquema que las contraseñas de cuenta (AESGCM con
    -- AAD tenant+fila): es un secreto, aunque su nombre diga «client».
    secreto_cifrado     BYTEA        NOT NULL,
    secreto_nonce       BYTEA        NOT NULL,

    -- Directorio de Azure AD ("tenant" en vocabulario de Microsoft — NO es el
    -- tenant de OrpycaMCP; el nombre colisiona y por eso se llama así aquí).
    azure_directory_id  VARCHAR(255),

    -- A dónde vuelve el proveedor tras el consentimiento. Se guarda porque debe
    -- coincidir EXACTAMENTE con la registrada en la consola del proveedor: una
    -- diferencia de una barra final rompe el flujo con un error que no explica
    -- nada.
    redirect_uri        VARCHAR(500) NOT NULL,

    notas               TEXT,
    created_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_by          UUID,
    updated_at          TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT chk_email_app_proveedor
        CHECK (proveedor IN ('gmail', 'microsoft')),
    -- Microsoft necesita el directorio; Google no lo usa. Escrito en las dos
    -- direcciones para que un valor puesto en el proveedor equivocado sea un
    -- error y no un campo que nadie mira.
    CONSTRAINT chk_email_app_azure_directory
        CHECK (
            (proveedor = 'microsoft' AND azure_directory_id IS NOT NULL) OR
            (proveedor = 'gmail'     AND azure_directory_id IS NULL)
        )
);

-- Una sola aplicación por proveedor y entidad.
CREATE UNIQUE INDEX IF NOT EXISTS ux_email_app_oauth_proveedor
    ON email_app_oauth (proveedor);


CREATE TABLE IF NOT EXISTS email_cuenta (
    id                    UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- Etiqueta para el operador: «Ventanilla PQRS», «Notificaciones judiciales».
    nombre                VARCHAR(200) NOT NULL,
    tipo                  VARCHAR(20)  NOT NULL,
    proveedor             VARCHAR(20)  NOT NULL,

    -- Conexión. host/puerto se derivan del proveedor para gmail/microsoft, pero
    -- se guardan explícitos: un preset que cambie no debe reescribir en silencio
    -- la configuración de una cuenta que ya funcionaba.
    host                  VARCHAR(255) NOT NULL,
    puerto                INTEGER      NOT NULL DEFAULT 993,
    usa_ssl               BOOLEAN      NOT NULL DEFAULT true,
    direccion             VARCHAR(320) NOT NULL,

    -- Con qué se AUTENTICA, cuando no coincide con la dirección. NULL = usar la
    -- dirección, que es el caso más común.
    --
    -- No son lo mismo y confundirlos rompe la conexión: la dirección es la
    -- identidad del buzón (va en el radicado y en la cadena XOAUTH2), mientras
    -- que el login depende del servidor — Exchange admite `DOMINIO\usuario`,
    -- algunos Zimbra y paneles de hosting quieren solo la parte local. El Orfeo
    -- legacy ya se había topado con esto y lo resolvía a la brava, cortando por
    -- el «@» según el proveedor (`configRadiMail.php`); aquí se declara, porque
    -- adivinar acierta hasta que no acierta y el fallo es «credenciales
    -- rechazadas», que manda a buscar el problema a la contraseña.
    usuario_login         VARCHAR(320),

    auth_tipo             VARCHAR(20)  NOT NULL,

    -- Credencial cifrada en reposo con AESGCM (mismo patrón que la clave de
    -- firma personal y el secreto TOTP de auth-service: AAD = tenant + id de
    -- la fila, así que un ciphertext movido a otra entidad no descifra).
    -- NULL para las cuentas personales: su contraseña NUNCA toca la base de
    -- datos. Guardar la credencial personal de un funcionario convertiría al
    -- custodio en titular de su correo entero, que excede con mucho lo que
    -- hace falta para radicar.
    secreto_cifrado       BYTEA,
    secreto_nonce         BYTEA,

    -- OAuth2. Obligatorio para Microsoft 365 (Exchange Online retiró la
    -- autenticación básica de IMAP a finales de 2022) y para Google Workspace
    -- (desde 2025-05-01 no acepta usuario+contraseña, ni contraseñas de
    -- aplicación). Sin esto, la ingesta simplemente no puede conectarse a las
    -- dos plataformas que usa la mayoría de las entidades.
    --
    -- Dos credenciales distintas, que se confunden a menudo:
    --   · La de la APLICACIÓN (client_id/client_secret) identifica a OrpycaMCP
    --     ante Google o Microsoft. Es de la ENTIDAD y la comparten todas sus
    --     cuentas del mismo proveedor → tabla `email_app_oauth`.
    --   · La AUTORIZACIÓN del buzón (refresh token) dice que esa aplicación
    --     puede leer ESTE buzón concreto. Es por cuenta → aquí.
    app_oauth_id          UUID,
    oauth_refresh_cifrado BYTEA,
    oauth_refresh_nonce   BYTEA,

    -- Carpetas. `carpeta_origen` es el filtro humano descrito arriba.
    -- `carpeta_radicados` es a dónde se mueve el correo una vez radicado: sale
    -- de la vista de todos los operadores a la vez, es reversible y se ve desde
    -- cualquier cliente de correo — a diferencia de la marca \Seen, que es
    -- compartida, la puede quitar cualquiera y no distingue «lo leí» de «lo
    -- radiqué».
    carpeta_origen        VARCHAR(255) NOT NULL DEFAULT 'INBOX',
    carpeta_radicados     VARCHAR(255) NOT NULL DEFAULT 'Radicados',

    -- Valores por defecto de la radicación que produce esta cuenta.
    dependencia_destino   VARCHAR(255),
    tipo_documental_id    UUID,

    -- 'asistida': el correo espera en la bandeja a que un funcionario lo revise
    -- y lo radique — así queda el «funcionario responsable del trámite» que
    -- exige el art. 2 del Acuerdo 060/2001. 'automatica': se radica al llegar,
    -- para entidades que confían en el filtro de carpeta.
    modo                  VARCHAR(20)  NOT NULL DEFAULT 'asistida',

    activa                BOOLEAN      NOT NULL DEFAULT true,

    -- Dueño de una cuenta personal. NULL en las institucionales.
    propietario_user_id   UUID,

    -- Diagnóstico de la última conexión: sin esto, la única forma de saber si
    -- una cuenta funciona es esperar a que no radique nada y no saber por qué.
    ultimo_sondeo_at      TIMESTAMPTZ,
    ultimo_error          TEXT,

    created_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),
    created_by            UUID,
    updated_at            TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT chk_email_cuenta_tipo
        CHECK (tipo IN ('institucional', 'personal')),
    CONSTRAINT chk_email_cuenta_proveedor
        CHECK (proveedor IN ('imap', 'gmail', 'microsoft')),
    CONSTRAINT chk_email_cuenta_auth
        CHECK (auth_tipo IN ('password', 'oauth2')),
    CONSTRAINT chk_email_cuenta_modo
        CHECK (modo IN ('asistida', 'automatica')),
    CONSTRAINT chk_email_cuenta_puerto
        CHECK (puerto BETWEEN 1 AND 65535),

    -- Una cuenta personal SIEMPRE tiene dueño; una institucional NUNCA.
    -- Escrito en ambas direcciones a propósito: una institucional con dueño
    -- sería una personal disfrazada, sin la protección de no guardar la
    -- credencial.
    CONSTRAINT chk_email_cuenta_propietario
        CHECK (
            (tipo = 'personal'      AND propietario_user_id IS NOT NULL) OR
            (tipo = 'institucional' AND propietario_user_id IS NULL)
        ),

    -- La credencial de una cuenta personal no se guarda: ni cifrada.
    CONSTRAINT chk_email_cuenta_personal_sin_secreto
        CHECK (tipo <> 'personal' OR (secreto_cifrado IS NULL AND oauth_refresh_cifrado IS NULL)),

    -- Una cuenta OAuth2 necesita la aplicación de su entidad; una de contraseña
    -- no debe apuntar a ninguna. Sin esta regla, una cuenta podría quedar en
    -- OAuth2 sin aplicación y el fallo aparecería en el primer sondeo, lejos de
    -- donde se cometió.
    CONSTRAINT chk_email_cuenta_app_segun_auth
        CHECK (
            (auth_tipo = 'oauth2'   AND app_oauth_id IS NOT NULL) OR
            (auth_tipo = 'password' AND app_oauth_id IS NULL)
        ),

    -- Y una cuenta con contraseña necesita la contraseña, salvo que sea
    -- personal (cuya credencial se pide en cada sesión y nunca se guarda).
    CONSTRAINT chk_email_cuenta_password_tiene_secreto
        CHECK (
            auth_tipo <> 'password'
            OR tipo = 'personal'
            OR secreto_cifrado IS NOT NULL
        ),

    CONSTRAINT fk_email_cuenta_app_oauth
        FOREIGN KEY (app_oauth_id) REFERENCES email_app_oauth (id) ON DELETE RESTRICT,

    -- Ciphertext y nonce viajan juntos o no viajan: media pareja es un secreto
    -- que no se puede descifrar y que nadie descubre hasta el primer sondeo.
    CONSTRAINT chk_email_cuenta_secreto_par
        CHECK ((secreto_cifrado IS NULL) = (secreto_nonce IS NULL)),
    CONSTRAINT chk_email_cuenta_oauth_par
        CHECK ((oauth_refresh_cifrado IS NULL) = (oauth_refresh_nonce IS NULL)),

    -- Las dos carpetas no pueden ser la misma, o mover el correo tras radicarlo
    -- lo dejaría donde estaba y volvería a ofrecerse indefinidamente.
    CONSTRAINT chk_email_cuenta_carpetas_distintas
        CHECK (carpeta_origen <> carpeta_radicados)
);

-- Una dirección no puede estar dos veces como cuenta institucional: dos filas
-- para el mismo buzón serían dos bandejas del mismo correo, y la reclamación
-- de una no protegería a la otra.
CREATE UNIQUE INDEX IF NOT EXISTS ux_email_cuenta_institucional_direccion
    ON email_cuenta (lower(direccion))
    WHERE tipo = 'institucional';

-- La cuenta personal es única por (dueño, dirección).
CREATE UNIQUE INDEX IF NOT EXISTS ux_email_cuenta_personal
    ON email_cuenta (propietario_user_id, lower(direccion))
    WHERE tipo = 'personal';

CREATE INDEX IF NOT EXISTS ix_email_cuenta_activa
    ON email_cuenta (activa, tipo);


-- ============================================================================
-- Quién puede trabajar cada cuenta institucional.
--
-- Es la «asignación de responsabilidades» del art. 13 hecha dato. Sin esta
-- tabla, «cuenta compartida» significaría «cualquiera con el permiso», y la
-- entidad no podría decir quién responde por la ventanilla de PQRS frente a la
-- de notificaciones judiciales.
-- ============================================================================

CREATE TABLE IF NOT EXISTS email_cuenta_usuario (
    cuenta_id   UUID NOT NULL REFERENCES email_cuenta (id) ON DELETE CASCADE,
    user_id     UUID NOT NULL,
    asignado_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    asignado_by UUID,
    PRIMARY KEY (cuenta_id, user_id)
);

CREATE INDEX IF NOT EXISTS ix_email_cuenta_usuario_user
    ON email_cuenta_usuario (user_id);

-- >>> document-service/tenant/022_email_oauth_state.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: se distribuye bajo la Licencia Pública General Affero de GNU
-- (AGPL) versión 3 o posterior. Véase LICENSE y <https://www.gnu.org/licenses/>.

-- ============================================================================
-- E19 Increment 1 — Autorización OAuth2 en curso.
--
-- Una fila por consentimiento iniciado y todavía sin canjear. Existe por dos
-- razones de seguridad, no por comodidad:
--
-- 1. **`state` de un solo uso** (RFC 6749 §10.12). Sin él, un tercero puede
--    inducir al administrador a completar un flujo que el atacante inició, y la
--    cuenta de la entidad acabaría autorizada contra un buzón ajeno —o, peor, el
--    refresh token del atacante quedaría guardado como si fuera de la entidad—.
--    El `state` se marca usado al canjear: reproducir la redirección no vuelve a
--    funcionar.
--
-- 2. **PKCE** (RFC 7636). El `code_verifier` no puede viajar en la redirección,
--    así que se guarda aquí y se envía solo en el canje servidor-a-servidor. Con
--    él, un código de autorización interceptado en el navegador no sirve de nada
--    sin el verificador, que nunca salió del servidor.
--
-- Las filas caducan: un consentimiento que nadie completó no debe quedar
-- utilizable indefinidamente.
-- ============================================================================

CREATE TABLE IF NOT EXISTS email_oauth_state (
    state          VARCHAR(128) PRIMARY KEY,
    cuenta_id      UUID NOT NULL REFERENCES email_cuenta (id) ON DELETE CASCADE,

    -- Quién inició el flujo. El canje exige que sea la MISMA persona: si no,
    -- bastaría con que un administrador iniciara la autorización para que
    -- cualquier otro pudiera completarla con un buzón suyo.
    iniciado_por   UUID NOT NULL,

    -- PKCE. Nunca sale del servidor.
    code_verifier  VARCHAR(128) NOT NULL,

    -- Se guarda el `redirect_uri` usado: el proveedor exige que el del canje sea
    -- IDÉNTICO al de la autorización, y si la configuración de la cuenta cambia
    -- entre medias, el canje fallaría con un error que no explica nada.
    redirect_uri   VARCHAR(500) NOT NULL,

    creado_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    expira_at      TIMESTAMPTZ NOT NULL,
    usado_at       TIMESTAMPTZ,

    CONSTRAINT chk_email_oauth_state_vigencia CHECK (expira_at > creado_at)
);

CREATE INDEX IF NOT EXISTS ix_email_oauth_state_cuenta
    ON email_oauth_state (cuenta_id);

-- Para la limpieza de los caducados sin recorrer la tabla entera.
CREATE INDEX IF NOT EXISTS ix_email_oauth_state_expira
    ON email_oauth_state (expira_at)
    WHERE usado_at IS NULL;

-- >>> document-service/tenant/023_email_mensaje.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: se distribuye bajo la Licencia Pública General Affero de GNU
-- (AGPL) versión 3 o posterior. Véase LICENSE y <https://www.gnu.org/licenses/>.

-- ============================================================================
-- E19 Increment 2 — Espejo local del buzón: la bandeja compartida.
--
-- El modelo lo acertaba ya el Orfeo legacy (`radimail`, con `uniqueid UNIQUE` y
-- `radi_nume_radi`): el correo se materializa en la base ANTES de radicar, y la
-- unicidad la garantiza la base de datos, no una marca del servidor de correo.
-- Lo que Orfeo hacía mal —y es justo lo que esto corrige— es que un correo ya
-- radicado **seguía en la lista** con una «R» roja, sin reserva ni aviso: dos
-- personas podían abrirlo a la vez y radicarlo dos veces.
--
-- IDENTIDAD. Un `uid` de IMAP **no identifica un mensaje por sí solo**: solo es
-- único dentro de una carpeta y mientras el `UIDVALIDITY` de esa carpeta no
-- cambie (RFC 3501 §2.3.1.1). Si el servidor la recrea —una restauración, una
-- migración de buzón— los uid se reutilizan desde cero y el mensaje nº 7 nuevo
-- se confundiría con el nº 7 viejo, dándose por radicado sin estarlo. Por eso:
--   · identidad estable = `message_id` (RFC 5322 §3.6.4), único globalmente y
--     que sobrevive incluso a que el correo cambie de carpeta;
--   · localizador = (`carpeta`, `uidvalidity`, `uid`), para ir a buscarlo.
--
-- FECHA DE RECIBO. Se guarda la del correo, no la del sondeo. La Circular
-- Externa AGN 001/2020 exige «dejando constancia de la fecha y hora de recibo», y
-- de ella dependen los plazos del derecho de petición: un correo que llega el
-- viernes y se sondea el lunes no puede nacer con fecha de lunes.
--
-- EL MENSAJE ORIGINAL se conserva (`crudo_file_id`), no solo su transcripción a
-- texto. La Ley 527/1999 art. 12 exige conservar el mensaje **en el formato en
-- que se recibió**, con su origen, destino, fecha y hora.
-- ============================================================================

CREATE TABLE IF NOT EXISTS email_mensaje (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cuenta_id         UUID NOT NULL REFERENCES email_cuenta (id) ON DELETE CASCADE,

    -- Identidad estable. Un correo sin `Message-ID` es raro pero posible (un
    -- cliente mal hecho); en ese caso el sincronizador sintetiza uno a partir de
    -- la terna del localizador, y por eso la columna es NOT NULL: preferimos un
    -- sustituto explícito a un NULL que rompería la unicidad.
    message_id        VARCHAR(998) NOT NULL,

    -- Localizador dentro del buzón.
    carpeta           VARCHAR(255) NOT NULL,
    uidvalidity       BIGINT       NOT NULL,
    uid               BIGINT       NOT NULL,

    -- Cabeceras, para la bandeja. El CUERPO no se guarda aquí: se lee del
    -- mensaje original cuando alguien abre el correo.
    remitente_nombre  VARCHAR(500),
    remitente_email   VARCHAR(320),
    asunto            VARCHAR(2000),
    fecha_recibo      TIMESTAMPTZ  NOT NULL,
    num_adjuntos      INTEGER      NOT NULL DEFAULT 0,

    -- El `.eml` íntegro en storage (Ley 527/1999 art. 12).
    crudo_file_id     UUID,

    estado            VARCHAR(20)  NOT NULL DEFAULT 'pendiente',

    -- ── Reserva ────────────────────────────────────────────────────────────
    -- Lo que Orfeo no tenía. Al abrir un correo queda reservado para ese
    -- funcionario unos minutos; los demás lo ven ocupado y no pueden radicarlo.
    --
    -- Con EXPIRACIÓN, y es deliberado: sin ella, alguien que cierra el navegador
    -- —o se va a comer— dejaría el correo bloqueado para siempre, y la ventanilla
    -- necesitaría un administrador para desatascarlo. Un bloqueo que solo se
    -- libera a mano acaba siendo un bloqueo que nadie usa.
    reservado_por     UUID,
    reservado_hasta   TIMESTAMPTZ,

    -- ── Resultado ──────────────────────────────────────────────────────────
    radicado_id       UUID,
    tracking_number   VARCHAR(50),
    radicado_por      UUID,
    radicado_at       TIMESTAMPTZ,

    -- Descartar es para lo que llegó a la carpeta y no debía radicarse. Exige
    -- motivo: es una decisión sobre una comunicación oficial recibida, y la
    -- unidad de correspondencia responde de ella (Ac. 060/2001 art. 3).
    descartado_por    UUID,
    descartado_at     TIMESTAMPTZ,
    motivo_descarte   TEXT,

    visto_at          TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT chk_email_mensaje_estado
        CHECK (estado IN ('pendiente', 'radicado', 'descartado')),

    -- Un mensaje radicado tiene número y autor; uno pendiente, ninguno de los
    -- dos. Escrito en ambas direcciones: un número sin estado 'radicado' sería
    -- un correo que se radicó y sigue ofreciéndose en la bandeja.
    CONSTRAINT chk_email_mensaje_radicado_forma
        CHECK (
            (estado = 'radicado' AND tracking_number IS NOT NULL AND radicado_por IS NOT NULL)
            OR (estado <> 'radicado' AND tracking_number IS NULL AND radicado_at IS NULL)
        ),

    CONSTRAINT chk_email_mensaje_descartado_forma
        CHECK (
            (estado = 'descartado' AND motivo_descarte IS NOT NULL AND descartado_por IS NOT NULL)
            OR (estado <> 'descartado' AND motivo_descarte IS NULL)
        ),

    -- Reservado por alguien y hasta cuándo van juntos: media pareja sería una
    -- reserva sin dueño o sin caducidad, y las dos se comportan mal.
    CONSTRAINT chk_email_mensaje_reserva_par
        CHECK ((reservado_por IS NULL) = (reservado_hasta IS NULL)),

    CONSTRAINT chk_email_mensaje_uid_positivo
        CHECK (uid > 0 AND uidvalidity > 0)
);

-- **La defensa contra la doble radicación, y va en la base de datos.**
-- Un mismo correo no puede entrar dos veces en la bandeja de una cuenta. Es el
-- equivalente del `uniqueid UNIQUE` del Orfeo legacy, pero sobre el
-- `Message-ID`, que sobrevive a que cambie el `UIDVALIDITY`.
CREATE UNIQUE INDEX IF NOT EXISTS ux_email_mensaje_identidad
    ON email_mensaje (cuenta_id, message_id);

-- La bandeja: pendientes de una cuenta, el más antiguo primero (FIFO, como la
-- cola de anulaciones — una ventanilla atiende por orden de llegada).
CREATE INDEX IF NOT EXISTS ix_email_mensaje_bandeja
    ON email_mensaje (cuenta_id, fecha_recibo)
    WHERE estado = 'pendiente';

-- Para localizar el mensaje en el buzón al moverlo tras radicar.
CREATE INDEX IF NOT EXISTS ix_email_mensaje_localizador
    ON email_mensaje (cuenta_id, carpeta, uidvalidity, uid);

