-- Migración de tenant (E23, RF-PRO-02): el borrador sabe a qué responde.
--
-- La combinación de campos necesita un contexto, y la mitad de ese contexto
-- —quién escribió, sobre qué asunto, con qué número y en qué fecha— vive en el
-- radicado que se está respondiendo. Sin este vínculo, `*NOM_R*` y `*RAD_E*` no
-- tienen de dónde salir y la plantilla vuelve a ser el texto muerto que era.
--
-- `ON DELETE SET NULL` y no CASCADE: lo que cuelga aquí es un borrador propio,
-- no una copia del radicado padre. Si el padre desapareciera, el texto que un
-- funcionario escribió sigue siendo suyo y no debe evaporarse con él. (La FK en
-- cascada ya se llevó un acta por delante en este proyecto; la dirección de la
-- dependencia hay que mirarla cada vez.)

ALTER TABLE borrador
    ADD COLUMN IF NOT EXISTS radicado_padre_id UUID REFERENCES radicados(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS ix_borrador_radicado_padre
    ON borrador (radicado_padre_id) WHERE radicado_padre_id IS NOT NULL;

COMMENT ON COLUMN borrador.radicado_padre_id IS
    'Radicado de Entrada que este borrador responde (E23, RF-PRO-02). Fuente del '
    'contexto de combinación: remitente, asunto, número y fecha del padre. Se '
    'lee SIEMPRE con el clearance del llamante: combinar sin gate exfiltraría el '
    'asunto de un radicado reservado al cuerpo de un documento legible.';

-- >>> document-service/tenant/029_borrador_documento.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E23, RF-PRO-03): el borrador produce un DOCUMENTO.
--
-- Hasta aquí el cuerpo del borrador acababa en una columna de texto del
-- radicado (`observations`). Un documento de archivo no es un campo de texto:
-- tiene formato de conservación, huella y existencia propia como fichero.

ALTER TABLE borrador
    -- El fichero generado, cuando ya se produjo. NULL mientras el borrador es
    -- solo texto. NO se borra al radicar: es la prueba de qué se generó.
    ADD COLUMN IF NOT EXISTS documento_file_id UUID,
    ADD COLUMN IF NOT EXISTS documento_sha256  CHAR(64),
    ADD COLUMN IF NOT EXISTS documento_formato TEXT,

    -- ── EL CONTEXTO CONGELADO, y esto es lo que impide falsificar el pasado ──
    --
    -- Los valores con que se combinó, tal como eran en el momento de producir.
    -- Sin esta copia, cambiar mañana la ficha de un tercero o el nombre de una
    -- dependencia haría que la explicación de un documento ya radicado dijera
    -- otra cosa: información errónea sobre un acto hecho con datos que eran
    -- verdad entonces.
    --
    -- Es exactamente el mismo razonamiento que la dirección de un envío
    -- (`radicado_actor`): el dato usado pertenece AL ACTO, no al sujeto. Y por
    -- el mismo motivo va SIN clave foránea a ningún catálogo — una FK lo ataría
    -- al valor vigente, que es justo lo que no debe pasar.
    ADD COLUMN IF NOT EXISTS combinacion       JSONB NOT NULL DEFAULT '{}'::jsonb;

COMMENT ON COLUMN borrador.documento_file_id IS
    'UUID en storage-service del PDF/A producido (E23, RF-PRO-03). FK lógica: no '
    'hay integridad referencial entre servicios.';

COMMENT ON COLUMN borrador.documento_sha256 IS
    'Huella del documento producido. Es lo que un visto bueno afirma haber leído '
    'y lo que una firma compromete (E23, RF-PRO-09).';

COMMENT ON COLUMN borrador.combinacion IS
    'Contexto CONGELADO con el que se combinó la plantilla. Cambiar la plantilla '
    'o la ficha de un tercero después NO reescribe lo ya producido: el dato usado '
    'pertenece al acto, no al sujeto (mismo criterio que radicado_actor).';

-- >>> document-service/tenant/030_borrador_version_hash.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E23, RF-PRO-09/11): versión y huella del cuerpo.
--
-- ── Por qué el hash lo calcula la BASE y no el servicio ─────────────────────
--
-- El hash del cuerpo es la BISAGRA del circuito de aprobación: es lo que un
-- visto bueno afirma haber leído y lo que una firma compromete. Si lo calculara
-- la capa de servicio, sería una convención — se respeta hasta que alguien
-- añade otro camino de escritura y se le olvida. Con un trigger, NINGÚN camino
-- —presente o futuro, ni siquiera un UPDATE a mano en una consola— puede
-- guardar texto nuevo conservando la huella vieja.
--
-- ── Y por qué el trigger BORRA el documento producido ───────────────────────
--
-- Si el cuerpo cambia, el PDF/A que se generó antes ya no corresponde a este
-- borrador. Dejarlo colgando sería peor que no tenerlo: alguien lo firmaría
-- creyendo que es el documento del texto que está leyendo. La invalidación del
-- circuito es DERIVADA de este hecho, no un acto que alguien deba recordar
-- ejecutar — si dependiera de que alguien pulse «revocar», el caso en que se
-- olvida sería exactamente el caso de fraude.
--
-- `sha256()` es nativo de PostgreSQL (11+): no se depende de pgcrypto, que en
-- un tenant nuevo podría no estar instalada y dejaría el trigger fallando en un
-- sitio donde el fallo es difícil de atribuir.

ALTER TABLE borrador
    ADD COLUMN IF NOT EXISTS version       INTEGER NOT NULL DEFAULT 1,
    ADD COLUMN IF NOT EXISTS cuerpo_sha256 CHAR(64);

CREATE OR REPLACE FUNCTION borrador_sellar_version() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.cuerpo_sha256 := CASE
            WHEN NEW.cuerpo IS NULL THEN NULL
            ELSE encode(sha256(convert_to(NEW.cuerpo, 'UTF8')), 'hex')
        END;
        RETURN NEW;
    END IF;

    IF NEW.cuerpo IS DISTINCT FROM OLD.cuerpo THEN
        NEW.version       := OLD.version + 1;
        NEW.cuerpo_sha256 := CASE
            WHEN NEW.cuerpo IS NULL THEN NULL
            ELSE encode(sha256(convert_to(NEW.cuerpo, 'UTF8')), 'hex')
        END;
        -- El documento producido deja de corresponder al texto: se retira.
        -- No se conserva «por si acaso» — esos son justo los bytes que nadie
        -- debe firmar creyendo que son los del texto que tiene delante.
        NEW.documento_file_id := NULL;
        NEW.documento_sha256  := NULL;
        NEW.documento_formato := NULL;
    END IF;
    RETURN NEW;
END $$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_borrador_sellar_version ON borrador;
CREATE TRIGGER trg_borrador_sellar_version
    BEFORE INSERT OR UPDATE ON borrador
    FOR EACH ROW EXECUTE FUNCTION borrador_sellar_version();

-- Backfill: los borradores que ya existen se quedarían sin huella, y un
-- circuito abierto sobre ellos no tendría contra qué comparar.
UPDATE borrador
   SET cuerpo_sha256 = encode(sha256(convert_to(cuerpo, 'UTF8')), 'hex')
 WHERE cuerpo IS NOT NULL AND cuerpo_sha256 IS NULL;

COMMENT ON COLUMN borrador.cuerpo_sha256 IS
    'Huella del cuerpo, calculada por TRIGGER (E23, RF-PRO-09/11). Ningún camino '
    'de escritura puede guardar texto nuevo conservando la huella vieja.';

COMMENT ON COLUMN borrador.version IS
    'Sube en cada edición del cuerpo. Cambiar el texto invalida el circuito de '
    'aprobación: la invalidación es DERIVADA del hash, no un acto que recordar.';

-- >>> document-service/tenant/031_plantilla_alcance.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E23 Inc.5, RF-PRO-06): alcance de plantillas por dependencia.
--
-- Paridad con `sgd_plan_plantillas.depe_codi` + `plan_global` del Orfeo legado.
-- Aquí una plantilla era global y punto, así que la lista que veía un
-- funcionario de Jurídica incluía las de Contratación, las de Talento Humano y
-- las de todas las demás. No es un problema de seguridad —una plantilla no
-- contiene datos de nadie— sino de USO: con cuarenta plantillas en la lista, la
-- que hace falta no se encuentra, y el camino corto es no usar ninguna.
--
-- **`es_global` por defecto TRUE, y es deliberado.** Las plantillas que ya existen
-- las ve hoy todo el mundo; ponerlas en FALSE las haría desaparecer de todas las
-- pantallas a la vez, y el fallo se leería como «se borraron las plantillas».
-- Restringir es un acto que la entidad decide plantilla por plantilla.
--
-- Se llama `es_global` y no `global` —como en el legado y como decía el plan—
-- porque `global` es palabra reservada de Python: un schema Pydantic no puede
-- declarar ese atributo, y salir del paso con un alias dejaría dos nombres para
-- lo mismo en la frontera más leída del servicio.

ALTER TABLE plantilla
    ADD COLUMN IF NOT EXISTS es_global  BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN IF NOT EXISTS creado_por UUID;

CREATE TABLE IF NOT EXISTS plantilla_dependencia (
    plantilla_id UUID    NOT NULL REFERENCES plantilla(id) ON DELETE CASCADE,
    depe_codigo  INTEGER NOT NULL,
    PRIMARY KEY (plantilla_id, depe_codigo)
);

CREATE INDEX IF NOT EXISTS ix_plantilla_dependencia_depe
    ON plantilla_dependencia (depe_codigo);

-- `ON DELETE CASCADE` es correcto aquí, y hay que decir por qué porque en este
-- proyecto una FK en cascada ya se llevó un acta por delante: lo que cuelga es
-- una ASIGNACIÓN —«esta plantilla la usa esta dependencia»—, no un documento de
-- archivo. Borrar la plantilla debe borrar a quién estaba asignada; no queda
-- nada que conservar. La dirección importa y hay que mirarla cada vez: aquí
-- apunta de la asignación a la plantilla, no al revés.

COMMENT ON COLUMN plantilla.es_global IS
    'TRUE = la ve cualquier dependencia (E23, RF-PRO-06). FALSE = solo las '
    'listadas en plantilla_dependencia. Por defecto TRUE para no hacer '
    'desaparecer las plantillas existentes de todas las pantallas a la vez.';

COMMENT ON TABLE plantilla_dependencia IS
    'Dependencias que alcanzan una plantilla NO global (paridad legado: '
    'sgd_plan_plantillas.depe_codi). Vacía sobre una plantilla no global = no la '
    've nadie, que es un estado valido: una plantilla retirada de circulacion '
    'sin borrar su historial.';

-- >>> document-service/tenant/032_borrador_faltantes.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 032: campos que quedaron sin datos al combinar la plantilla
-- (E23, RF-PRO-01). search_path = tenant_{slug} (ADR-012).
--
-- El defecto que esto cierra. La lista de campos sin resolver se calculaba al
-- combinar, viajaba en UNA respuesta HTTP y se perdía. El cuerpo se guarda YA
-- combinado —los marcadores sustituidos, los que no tenían dato por cadena
-- vacía—, así que volver a combinarlo no encuentra ningún marcador que
-- reportar: al reabrir el borrador no había aviso, y `X-Faltantes` llegaba
-- vacío en la previsualización.
--
-- Es decir: el aviso existía exactamente en el instante en que el hueco todavía
-- no importaba, y desaparecía para siempre justo antes de importar. Quien
-- abriera el borrador al día siguiente —o quien no fuera la persona que lo
-- creó— vería un espacio en blanco en mitad del oficio sin nada que le dijera
-- que ahí faltaba un dato. El docstring de `previsualizar` ya decía lo que
-- tenía que pasar: «sin esa lista, la persona vería un hueco en el documento
-- sin saber que es un hueco — y el oficio saldría así al ciudadano».
--
-- Se guarda como HECHO HISTÓRICO de la combinación, no como estado a mantener:
-- dice qué campos no tenían dato cuando la plantilla se combinó. Eso sigue
-- siendo cierto por mucho que después se edite el texto a mano, y por eso no se
-- limpia al editar: borrarlo a la primera pulsación quitaría el aviso
-- precisamente cuando alguien empieza a tocar el documento sin haber rellenado
-- necesariamente los huecos.
ALTER TABLE borrador
    ADD COLUMN IF NOT EXISTS faltantes TEXT[] NOT NULL DEFAULT '{}';

COMMENT ON COLUMN borrador.faltantes IS
    'Campos del vocabulario que no tenían dato al combinar la plantilla (E23, '
    'RF-PRO-01). Hecho histórico de la combinación: no se recalcula al editar.';

-- >>> document-service/tenant/033_tercero_fusion.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Fusión de terceros duplicados (RF-RAD-05).
--
-- El Orfeo del que deriva este sistema acabó con el mismo señor treinta veces en
-- el catálogo. Aquí la primera defensa es la búsqueda sin tildes al radicar
-- —encontrar lo que ya está—, pero los duplicados que YA existen necesitan una
-- salida, y hasta ahora no había ninguna: ni pantalla de directorio, ni forma de
-- consolidar dos fichas de la misma persona.
--
-- ── La fusión NO reescribe nada ───────────────────────────────────────────
--
-- Fusionar marca al absorbido con `fusionado_en` y **no toca `radicado_actor`.
-- Ni una fila.** El primer diseño repuntaba el `tercero_id` de los vínculos, y
-- el trigger de la migración 026 lo impidió: incluye `tercero_id` entre las
-- columnas inmutables, con el mensaje «los datos de un actor son los USADOS en
-- el envío y no se editan: cambiarlos daría información errónea sobre un acto
-- ya ocurrido». Y tiene razón — a QUÉ ficha del catálogo se atendió a alguien
-- también es parte de lo que pasó: ese día existían dos fichas y se usó una.
--
-- Así que la fusión solo añade lo que se supo DESPUÉS: estas dos son la misma
-- persona. Quien lee resuelve a través de `fusionado_en`; el pasado sigue
-- diciendo la verdad de su momento. Por eso tampoco se borra la fila: el
-- vínculo antiguo la sigue nombrando y tiene que poder resolverse.

ALTER TABLE tercero
    ADD COLUMN IF NOT EXISTS fusionado_en uuid REFERENCES tercero (id),
    ADD COLUMN IF NOT EXISTS fusionado_at timestamptz,
    ADD COLUMN IF NOT EXISTS fusionado_por uuid;

COMMENT ON COLUMN tercero.fusionado_en IS
    'Si no es NULL, esta ficha se fusionó en la que apunta: es un duplicado ya '
    'consolidado. No se borra para no perder el rastro de los radicado_actor '
    'que se repuntaron. Las fichas fusionadas se excluyen de la búsqueda.';

-- Una ficha fusionada no puede a su vez absorber: encadenar fusiones haría que
-- el destino de un vínculo dependiera de recorrer una cadena, y una cadena con
-- un ciclo colgaría al lector. Se fusiona SIEMPRE contra una ficha viva.
ALTER TABLE tercero
    DROP CONSTRAINT IF EXISTS chk_tercero_fusion_no_a_si_mismo;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_fusion_no_a_si_mismo
    CHECK (fusionado_en IS NULL OR fusionado_en <> id);

-- Los tres campos van juntos o no van: una fusión sin fecha ni responsable es
-- un acto sin autor sobre el catálogo de una entidad.
ALTER TABLE tercero
    DROP CONSTRAINT IF EXISTS chk_tercero_fusion_completa;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_fusion_completa
    CHECK (
        (fusionado_en IS NULL AND fusionado_at IS NULL)
        OR (fusionado_en IS NOT NULL AND fusionado_at IS NOT NULL)
    );

-- Índice para el listado de duplicados: agrupa por nombre NORMALIZADO (sin
-- tildes ni mayúsculas), que es como se reconocen «José Pérez» y «Jose Perez».
-- `immutable_unaccent` no existe: `unaccent()` es STABLE, así que no vale para
-- un índice de expresión — se usa la misma configuración de texto que ya emplea
-- la búsqueda (`spanish_unaccent`), que sí es indexable.
CREATE INDEX IF NOT EXISTS ix_tercero_activo_nombre
    ON tercero (lower(nombre))
    WHERE fusionado_en IS NULL;

-- Y para el eje que de verdad identifica: dos fichas con el mismo documento son
-- la misma persona, sin discusión posible.
CREATE INDEX IF NOT EXISTS ix_tercero_documento
    ON tercero (tipo_documento, numero_documento)
    WHERE numero_documento IS NOT NULL AND fusionado_en IS NULL;

-- >>> document-service/tenant/034_radicado_status_check.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- ADR-028 (remediación de auditoría): el estado del radicado es de un conjunto
-- CERRADO. Hasta ahora `radicados.status` era un VARCHAR(20) libre: cualquier
-- valor cabía, incluido uno que ninguna máquina de estados conoce (un paquete
-- importado, un UPDATE a mano). Los guardas del flujo (`closed`/`anulado` son
-- terminales) solo valen si el dominio de valores está cerrado.
--
-- Valores admitidos: los que el código escribe — `registered` (alta),
-- `distributed`/`in_progress` (los mueve el workflow-service), `closed` (acción
-- «Finalizar trámite») y `anulado` (la anulación aprobada). Verificado contra el
-- código y los seeds: ningún otro literal se escribe en `radicados.status`.
--
-- Se añade NOT VALID (rige para lo que se escriba desde ya) y se intenta VALIDAR lo
-- existente: si alguna fila trae un valor fuera del conjunto (datos heredados), la
-- migración NO falla —tumbaría el arranque de la entidad— y deja el aviso con el
-- recuento; la restricción sigue protegiendo toda escritura nueva y se valida a
-- mano (`ALTER TABLE radicados VALIDATE CONSTRAINT radicados_status_check`) tras
-- corregir esas filas.
--
-- Idempotente. Rollback:
--   ALTER TABLE radicados DROP CONSTRAINT IF EXISTS radicados_status_check;

DO $$
DECLARE
    v_fuera INTEGER;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'radicados_status_check'
           AND conrelid = format('%I.radicados', current_schema())::regclass
    ) THEN
        ALTER TABLE radicados
            ADD CONSTRAINT radicados_status_check
            CHECK (status IN ('registered', 'distributed', 'in_progress', 'closed', 'anulado'))
            NOT VALID;
    END IF;

    SELECT count(*) INTO v_fuera FROM radicados
     WHERE status NOT IN ('registered', 'distributed', 'in_progress', 'closed', 'anulado');
    IF v_fuera = 0 THEN
        ALTER TABLE radicados VALIDATE CONSTRAINT radicados_status_check;
    ELSE
        RAISE WARNING 'radicados_status_check (%): % filas con un status fuera del conjunto; '
                      'la restricción queda SIN VALIDAR (rige solo para escrituras nuevas)',
                      current_schema(), v_fuera;
    END IF;
END $$;

