-- AREA-05-03-S: las firmas declarativas anteriores llevan una huella que ELIGIÓ
-- EL CLIENTE; `verify` no puede seguir dándolas por válidas.
--
-- Las filas que ya existen quedan marcadas `cliente_no_verificado` (el DEFAULT
-- con que se añade la columna las cubre todas) y `verify` las excluye. Después
-- el DEFAULT pasa a `servidor`: las nuevas las inserta el servicio con la huella
-- resuelta en storage. Idempotente: repetir la migración no toca lo ya marcado.

ALTER TABLE signatures
    ADD COLUMN IF NOT EXISTS origen VARCHAR(30) NOT NULL DEFAULT 'cliente_no_verificado';

ALTER TABLE signatures ALTER COLUMN origen SET DEFAULT 'servidor';

ALTER TABLE signatures DROP CONSTRAINT IF EXISTS ck_signatures_origen;
ALTER TABLE signatures
    ADD CONSTRAINT ck_signatures_origen CHECK (origen IN ('servidor', 'cliente_no_verificado'));

COMMENT ON COLUMN signatures.origen IS
    'servidor = huella resuelta por el servidor desde storage; '
    'cliente_no_verificado = huella declarada por el cliente (heredada), '
    'excluida de verify.';

-- >>> document-service/tenant/037_radicado_ubicacion.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Ubicación actual del radicado (ADR-029; equivalente a `radi_depe_actu` /
-- `radi_usua_actu` de Orfeo).
--
-- `dest_dept`/`dest_dept_code` son la dependencia DE RADICACIÓN: una instantánea
-- legal inmutable de a quién iba dirigido el documento. Tras repartir o devolver,
-- el radicado está en OTRA dependencia y ninguna columna lo decía.
--
--   flujo_dept_code / flujo_dept / flujo_usuario
--       las escribe el workflow-service (`sincronizar_estado_radicado`) en la MISMA
--       transacción que `status`, y su backfill (workflow 016) para lo existente.
--       document-service NUNCA las escribe: un solo escritor.
--       `flujo_dept` es el NOMBRE del paso (`flow_steps.to_dept`, sin FK);
--       `flujo_dept_code` solo se resuelve si el nombre casa con UNA dependencia
--       activa, si no queda NULL y el nombre es la instantánea. `flujo_usuario` es
--       `auth_users.id` del poseedor del paso (nunca el `sub` de Keycloak).
--
--   ubicacion_dept_code / ubicacion_dept   (columnas GENERADAS, STORED)
--       dónde está AHORA: la del flujo si el flujo la ha movido; si no, la de
--       radicación (destino y, a falta de él, origen). Se calcula por PAR
--       (nombre + código del mismo origen): con un `COALESCE` columna a columna,
--       un nombre de flujo sin código único mostraría el código de OTRA
--       dependencia. Al ser generadas no tienen segundo escritor que desincronice.
--
-- Idempotente (`IF NOT EXISTS`). Los radicados existentes quedan con `flujo_*`
-- NULL —ubicación = radicación— hasta que corra el backfill de workflow-service.

ALTER TABLE radicados
    ADD COLUMN IF NOT EXISTS flujo_dept_code INTEGER,
    ADD COLUMN IF NOT EXISTS flujo_dept      VARCHAR(100),
    ADD COLUMN IF NOT EXISTS flujo_usuario   UUID;

ALTER TABLE radicados
    ADD COLUMN IF NOT EXISTS ubicacion_dept_code INTEGER GENERATED ALWAYS AS (
        CASE
            WHEN flujo_dept IS NOT NULL THEN flujo_dept_code
            WHEN dest_dept IS NOT NULL OR dest_dept_code IS NOT NULL THEN dest_dept_code
            ELSE origin_dept_code
        END
    ) STORED;

ALTER TABLE radicados
    ADD COLUMN IF NOT EXISTS ubicacion_dept VARCHAR(100) GENERATED ALWAYS AS (
        CASE
            WHEN flujo_dept IS NOT NULL THEN flujo_dept
            WHEN dest_dept IS NOT NULL OR dest_dept_code IS NOT NULL THEN dest_dept
            ELSE origin_dept
        END
    ) STORED;

CREATE INDEX IF NOT EXISTS ix_radicados_ubicacion_dept_code ON radicados (ubicacion_dept_code);

COMMENT ON COLUMN radicados.flujo_dept IS
    'Nombre de la dependencia del paso de flujo vigente (o del último cerrado). La escribe SOLO workflow-service (ADR-029).';
COMMENT ON COLUMN radicados.ubicacion_dept IS
    'Dónde está el radicado AHORA (generada): flujo_* si el flujo lo movió, si no la dependencia de radicación (ADR-029).';

-- >>> document-service/tenant/038_import_binario_huerfano.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 038 (AREA-09-14): binarios que una importación fallida subió a
-- storage y que NINGÚN radicado referencia.
--
-- Antes solo se ASENTABAN (document.import_binarios_sin_radicado) y se quedaban en
-- el almacén para siempre. Ahora se PURGAN, pero storage deduplica por SHA-256: el
-- objeto puede sostener anexos de otros radicados, así que el borrado lo decide
-- storage-service comprobando referencias en su propia transacción
-- (POST /internal/purgar-huerfanos). Esta tabla es la cola DURABLE de ese borrado:
-- si storage no responde, la fila queda 'pendiente' y el barrido la reintenta; el
-- asiento de «sin radicado» ya está escrito y no se pierde.
--
-- Estados: pendiente (por intentar/reintentar) | purgado (borrado, o ya no estaba) |
-- conservado (lo referencia un anexo, o es anterior a la importación: se queda) |
-- protegido (bajo WORM) | agotado (se superó el máximo de reintentos: revisar a mano).
-- Idempotente; search_path = tenant_{slug} (ADR-012).

CREATE TABLE IF NOT EXISTS import_binario_huerfano (
    id            UUID        NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    import_uuid   UUID        NOT NULL,
    file_id       UUID        NOT NULL,
    sha256        VARCHAR(64),
    actor         UUID,
    -- Instante a partir del cual un objeto cuenta como CREADO por esta importación;
    -- storage no borra nada anterior (una coincidencia de hash no es suyo).
    subido_desde  TIMESTAMPTZ NOT NULL,
    estado        VARCHAR(20) NOT NULL DEFAULT 'pendiente',
    intentos      INTEGER     NOT NULL DEFAULT 0,
    ultimo_error  TEXT,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    resuelto_at   TIMESTAMPTZ,
    CONSTRAINT ck_import_binario_huerfano_estado
        CHECK (estado IN ('pendiente', 'purgado', 'conservado', 'protegido', 'agotado')),
    CONSTRAINT ux_import_binario_huerfano UNIQUE (import_uuid, file_id)
);

CREATE INDEX IF NOT EXISTS ix_import_binario_huerfano_pendiente
    ON import_binario_huerfano (created_at) WHERE estado = 'pendiente';

