-- Tenant migration 039 (AREA-09-15): lotes de radicados reanudables y reprocesables.
--
-- Los lotes se procesaban con asyncio.create_task: si el servicio se reiniciaba, el
-- lote quedaba en pending/processing para siempre, y un ítem fallido no se podía
-- reintentar. Ahora el barrido reanuda los interrumpidos y el lote termina en
-- 'completado_con_errores' con el detalle por ítem.
--
-- `batch_jobs`/`batch_job_items` son COMPARTIDAS por nombre con archive-service
-- (job_type 'documents' | 'expedientes'): solo se AÑADEN columnas, sin CHECK sobre
-- status, para no tocar los estados del otro servicio. Idempotente.

ALTER TABLE batch_job_items ADD COLUMN IF NOT EXISTS intentos   INTEGER NOT NULL DEFAULT 0;
ALTER TABLE batch_job_items ADD COLUMN IF NOT EXISTS error_tipo VARCHAR(100);

ALTER TABLE batch_jobs ADD COLUMN IF NOT EXISTS reanudaciones   INTEGER NOT NULL DEFAULT 0;
-- Quien pidió el último reproceso: los radicados que cree ese reproceso son suyos
-- (registered_by y asiento), no de quien encoló el lote original.
ALTER TABLE batch_jobs ADD COLUMN IF NOT EXISTS reprocesado_por UUID;
ALTER TABLE batch_jobs ADD COLUMN IF NOT EXISTS reprocesado_at  TIMESTAMPTZ;

COMMENT ON COLUMN batch_job_items.intentos IS
    'Veces que se intentó procesar el ítem (el primer intento cuenta 1).';
COMMENT ON COLUMN batch_job_items.error_tipo IS
    'Clase de la excepción del último fallo (el motivo legible va en error_message).';

-- El estado nuevo `completado_con_errores` (22 caracteres) no cabe en VARCHAR(20).
-- Ensanchar es seguro y compatible con archive-service (que sigue usando los suyos).
ALTER TABLE batch_jobs ALTER COLUMN status TYPE VARCHAR(40);

-- >>> document-service/tenant/040_anexo_publicable.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 040 (AREA-07-12): control de publicación POR ANEXO.
--
-- Publicar un radicado de oficio (Ley 1712/2014 art. 12) hacía que CMIS sirviera el
-- PRIMER anexo, sin que nadie hubiera decidido difundir ese soporte (puede traer
-- datos personales de terceros, Ley 1581). `anexos.publicable` es el acto positivo
-- por soporte, con DEFAULT FALSE: un anexo nuevo no se difunde por no haber dicho nada.
--
-- Backfill: los anexos de radicados que YA están publicados conservan su difusión
-- (la entidad los publicó a sabiendas con el esquema anterior); sin esto, la migración
-- retiraría en silencio contenido que hoy se sirve. Lo no publicado queda en FALSE.
--
-- Idempotente. Rollback: ALTER TABLE anexos DROP COLUMN IF EXISTS publicable;

DO $$
DECLARE
    v_existia BOOLEAN;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM information_schema.columns
         WHERE table_schema = current_schema()
           AND table_name = 'anexos' AND column_name = 'publicable'
    ) INTO v_existia;

    IF NOT v_existia THEN
        ALTER TABLE anexos ADD COLUMN publicable BOOLEAN NOT NULL DEFAULT FALSE;
        UPDATE anexos a SET publicable = TRUE
          FROM radicados r
         WHERE r.id = a.radicado_id AND r.publicable AND r.nivel_seguridad = 1;
    END IF;
END $$;

COMMENT ON COLUMN anexos.publicable IS
    'Acto positivo de difusión POR ANEXO (Ley 1712/2014 art. 12). FALSE por defecto. '
    'CMIS solo sirve anexos con publicable = TRUE de radicados publicados.';

-- >>> document-service/tenant/041_clasificado_con_fundamento.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.


-- Tenant migration 041 (AREA-09-04): «nunca NULL» en el índice de clasificados.
--
-- El índice de información clasificada y reservada (Ley 1712/2014 art. 20) promete un
-- fundamento por cada fila. Los caminos de escritura del API lo exigen (schemas de
-- radicación y reclasificación), pero la importación INT-05 admitía `nivel >= 2` con
-- `clasificacion.fundamento` nulo, y la base no lo impedía: bastaba un INSERT directo.
--
-- 1) Backfill: las filas ya clasificadas sin fundamento reciben un texto EXPLÍCITO
--    de pendiente (no inventa una causal jurídica: dice que falta, y aparece tal cual
--    en el índice para que la entidad lo motive). El histórico inmutable no se toca.
-- 2) CHECK (nivel_seguridad < 2 OR fundamento no vacío), NOT VALID + VALIDATE: rige
--    desde ya para toda escritura y se valida lo existente tras el backfill.
--
-- Idempotente. Rollback:
--   ALTER TABLE radicados DROP CONSTRAINT IF EXISTS radicados_clasificado_con_fundamento;

UPDATE radicados
   SET clasificacion_fundamento =
       'PENDIENTE DE MOTIVAR: clasificado sin fundamento registrado (anterior a la exigencia de la Ley 1712/2014 art. 19/28)'
 WHERE nivel_seguridad >= 2
   AND (clasificacion_fundamento IS NULL OR btrim(clasificacion_fundamento) = '');

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'radicados_clasificado_con_fundamento'
           AND conrelid = format('%I.radicados', current_schema())::regclass
    ) THEN
        ALTER TABLE radicados
            ADD CONSTRAINT radicados_clasificado_con_fundamento
            CHECK (nivel_seguridad < 2
                   OR (clasificacion_fundamento IS NOT NULL
                       AND btrim(clasificacion_fundamento) <> '')) NOT VALID;
    END IF;
    ALTER TABLE radicados VALIDATE CONSTRAINT radicados_clasificado_con_fundamento;
END $$;

-- >>> document-service/tenant/042_eventos_salientes.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.


-- Tenant migration 042 (AREA-09-05): OUTBOX de eventos de dominio.
--
-- La reclasificación (y el alta y la anulación) publicaba su evento DESPUÉS del
-- commit, best-effort: si Redis caía justo ahí, el UPDATE del nivel quedaba
-- confirmado y el evento se perdía. knowledge-service deriva el nivel de sus
-- fragmentos SOLO del evento, así que un 1→3 perdido dejaba el fragmento en nivel
-- 1 y la búsqueda/RAG lo servía a quien tiene clearance 1 (y lo hacía embebible
-- por un proveedor externo).
--
-- Ahora el evento se inserta AQUÍ, en la MISMA transacción que el UPDATE y el
-- asiento de auditoría: o existen los tres o ninguno. Un relé (camino rápido tras
-- el commit + barrido de respaldo) lo publica y marca `enviado_at`. Entrega
-- at-least-once: el consumidor ya es idempotente por `event_id`/`dedup_key`.
--
-- `event_id` y `occurred_at` se fijan al ENCOLAR, no al publicar: el reintento
-- reenvía el MISMO sobre. Contiene el payload del evento (puede traer asunto del
-- radicado): vive en el schema del tenant, igual que `radicados`, y las filas ya
-- enviadas se retiran pasada la retención.
--
-- Idempotente. Rollback: DROP TABLE IF EXISTS eventos_salientes;

CREATE TABLE IF NOT EXISTS eventos_salientes (
    id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    event_id      TEXT        NOT NULL UNIQUE,
    stream        TEXT        NOT NULL,
    tipo          TEXT        NOT NULL,
    tenant_slug   TEXT        NOT NULL,
    actor         TEXT,
    dedup_key     TEXT,
    payload       JSONB       NOT NULL DEFAULT '{}'::jsonb,
    occurred_at   TIMESTAMPTZ NOT NULL,
    creado_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    enviado_at    TIMESTAMPTZ,
    intentos      INTEGER     NOT NULL DEFAULT 0,
    ultimo_error  TEXT
);

-- La cola de pendientes es la fracción pequeña que el relé recorre.
CREATE INDEX IF NOT EXISTS ix_eventos_salientes_pendientes
    ON eventos_salientes (id) WHERE enviado_at IS NULL;

COMMENT ON TABLE eventos_salientes IS
    'Outbox transaccional (AREA-09-05): el evento nace en la misma tx que el cambio.';

-- >>> document-service/tenant/043_public_submission_keys.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.


-- Tenant migration 043 (AREA-02-07): idempotencia de la radicación pública.
--
-- Un reintento de red del ciudadano (o un doble clic) producía DOS radicados: dos
-- consecutivos oficiales, irrecuperables. El cliente genera una `Idempotency-Key`
-- por formulario; este registro la ata al radicado y se inserta con
-- `ON CONFLICT DO NOTHING` en la MISMA transacción que el radicado: dos peticiones
-- simultáneas con la misma clave se serializan en el índice único (la segunda espera
-- el commit de la primera y devuelve el radicado existente, sin gastar número).
--
-- `huella` es el SHA-256 del contenido validado: la misma clave con OTRO contenido no
-- es un reintento, es un mal uso, y se rechaza (409) en vez de devolver un radicado
-- que no corresponde a lo que se envió.
--
-- Idempotente. Rollback: DROP TABLE IF EXISTS public_submission_keys;

CREATE TABLE IF NOT EXISTS public_submission_keys (
    key          TEXT        PRIMARY KEY,
    radicado_id  UUID        REFERENCES radicados(id) ON DELETE CASCADE,
    huella       TEXT        NOT NULL,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE public_submission_keys IS
    'Idempotency-Key de la ventanilla pública (AREA-02-07): clave del cliente -> radicado.';

