-- Tenant migration 044 (AREA-09-10): secreto HMAC del operador postal con rotación,
-- y acuse de recibo del envío.
--
-- 1) `postal_operator_credential.webhook_secret` era TEXT en claro, una sola fila por
--    operador y NINGÚN endpoint lo escribía (se sembraba a mano). Ahora hay dos
--    ranuras —la vigente y la anterior, con `anterior_caduca_at`— para rotar sin corte:
--    el operador cambia de secreto cuando puede y, mientras tanto, se aceptan ambas.
--    Las ranuras nuevas se guardan CIFRADAS (AESGCM, AAD = tenant + operador); la
--    columna en claro queda solo para lo heredado y se vacía al primer rotado.
-- 2) `postal_shipment.acuse_*`: la prueba de entrega. Un envío no puede pasar a
--    `entregado` a mano sin ella (el callback firmado del operador es su propia prueba).
--
-- Idempotente. Rollback: DROP de las columnas añadidas; restaurar NOT NULL si todas las
-- filas tienen `webhook_secret`.

ALTER TABLE postal_operator_credential ALTER COLUMN webhook_secret DROP NOT NULL;

ALTER TABLE postal_operator_credential
    ADD COLUMN IF NOT EXISTS secreto_cifrado    BYTEA,
    ADD COLUMN IF NOT EXISTS secreto_nonce      BYTEA,
    ADD COLUMN IF NOT EXISTS anterior_cifrado   BYTEA,
    ADD COLUMN IF NOT EXISTS anterior_nonce     BYTEA,
    ADD COLUMN IF NOT EXISTS anterior_caduca_at TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS rotado_por         UUID;

ALTER TABLE postal_shipment
    ADD COLUMN IF NOT EXISTS acuse_file_id UUID,
    ADD COLUMN IF NOT EXISTS acuse_sha256  CHAR(64);

COMMENT ON COLUMN postal_shipment.acuse_file_id IS
    'file_id (storage) del acuse de recibo: constancia de entrega que aporta quien registra la entrega a mano.';

-- >>> document-service/tenant/045_acuse_unico.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 045 (B2, ADR-031): un acuse de recibo es de UN solo envío.
-- search_path = tenant_{slug} (ADR-012).
--
-- El servicio ya rechaza (409 acuse_ya_referenciado) un `acuse_file_id` que otro
-- envío, un anexo o un borrador usan; esta es la guarda de MOTOR para la carrera
-- entre dos registros simultáneos que pasan el cotejo a la vez.
--
-- Si ya hay un mismo acuse en dos envíos (datos previos a esta guarda) NO se
-- escoge cuál conservar —eso es juzgar una prueba—: la migración aborta y dice
-- cuáles son. Se corrigen a mano y se vuelve a aplicar.
--
-- Idempotente. Rollback: DROP INDEX postal_shipment_acuse_file_id_uq.
DO $$
DECLARE
    duplicados TEXT;
BEGIN
    SELECT string_agg(acuse_file_id::text || ' (' || n || ' envíos)', ', ')
      INTO duplicados
      FROM (
          SELECT acuse_file_id, count(*) AS n
            FROM postal_shipment
           WHERE acuse_file_id IS NOT NULL
           GROUP BY acuse_file_id
          HAVING count(*) > 1
      ) d;
    IF duplicados IS NOT NULL THEN
        RAISE EXCEPTION
            'No se puede crear el índice único de acuse: el mismo archivo es acuse de varios envíos: %',
            duplicados;
    END IF;
END
$$;

CREATE UNIQUE INDEX IF NOT EXISTS postal_shipment_acuse_file_id_uq
    ON postal_shipment (acuse_file_id)
    WHERE acuse_file_id IS NOT NULL;

-- >>> document-service/tenant/046_dependencia_por_codigo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (B5, ADR-032): la dependencia se correlaciona por CÓDIGO.
--
--   1. `borrador.dest_dept_code`: hasta ahora el borrador solo guardaba el NOMBRE
--      del destino y, al radicar un Interno, `borrador_service` lo traducía con
--      `WHERE nombre = $1 ... ORDER BY codigo LIMIT 1`: con dos dependencias
--      homónimas radicaba hacia la de menor código, EN SILENCIO.
--   2. Backfill de `radicados.dest_dept_code`, `radicados.origin_dept_code` y
--      `borrador.dest_dept_code` donde el código es NULL y el nombre no, con
--      `resolver_codigo_dependencia(nombre, true)` (migración 013 de
--      tenant-service: UNA definición del criterio, incluye nombres anteriores y
--      mapeos manuales). Solo se escribe con EXACTAMENTE un candidato; con 0
--      (huérfano) o >=2 (ambiguo) la fila queda NULL y se deja evidencia.
--
-- Qué NO hace, a propósito:
--   * No hace RAISE por ambiguos/huérfanos: las columnas son INSTANTÁNEAS de
--     radicación (dato probatorio de un acto pasado) y un radicado no se bloquea
--     por un nombre viejo. La columna no pasa a NOT NULL.
--   * No toca `updated_at`: recalcular un derivado no es editar el documento.
--   * No toca `flujo_dept_code` (lo escribe SOLO workflow-service, ADR-029).
--
-- La evidencia es de SOLO INSERCIÓN (trigger). El asiento-ANCLA en `audit_log`
-- (conteo + SHA-256 del contenido ordenado) lo escribe el RUNNER (`_ANCLAS`), en
-- la misma transacción: nunca el SQL, que rompería la cadena de hashes.
--
-- Guarda de ORDEN: la función viene de tenant-service 013. Si falta y HAY filas
-- por rellenar -> RAISE (el runner no marca la migración aplicada y se reintenta
-- tras migrar tenant-service); sin filas pendientes no hay nada que perder.
--
-- Idempotente: la 2.ª ejecución no inserta evidencia (NOT EXISTS) ni cambia filas
-- (IS NULL). Rollback: DROP COLUMN borrador.dest_dept_code; los nombres nunca se tocaron.

ALTER TABLE borrador ADD COLUMN IF NOT EXISTS dest_dept_code INTEGER;

CREATE TABLE IF NOT EXISTS dependencia_codigo_backfill_doc (
    id         BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tabla      VARCHAR(40) NOT NULL,
    fila_id    UUID        NOT NULL,
    columna    VARCHAR(40) NOT NULL,
    nombre     TEXT        NOT NULL,
    codigo     INTEGER,
    candidatos INTEGER     NOT NULL,
    resultado  VARCHAR(10) NOT NULL CHECK (resultado IN ('resuelto', 'ambiguo', 'huerfano')),
    at         TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION reject_dependencia_codigo_backfill_doc_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'dependencia_codigo_backfill_doc is append-only (evidencia de la migración 046)';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_dependencia_codigo_backfill_doc_immutable ON dependencia_codigo_backfill_doc;
CREATE TRIGGER trg_dependencia_codigo_backfill_doc_immutable
    BEFORE UPDATE OR DELETE ON dependencia_codigo_backfill_doc
    FOR EACH ROW EXECUTE FUNCTION reject_dependencia_codigo_backfill_doc_mutation();

CREATE INDEX IF NOT EXISTS ix_dependencia_codigo_backfill_doc_fila
    ON dependencia_codigo_backfill_doc (tabla, fila_id, columna);

DO $$
DECLARE
    v_pendientes INTEGER;
    v_resueltas  INTEGER;
    v_sin_codigo INTEGER;
BEGIN
    SELECT (SELECT count(*) FROM radicados WHERE dest_dept_code IS NULL AND dest_dept IS NOT NULL)
         + (SELECT count(*) FROM radicados WHERE origin_dept_code IS NULL AND origin_dept IS NOT NULL)
         + (SELECT count(*) FROM borrador  WHERE dest_dept_code IS NULL AND dest_dept IS NOT NULL)
      INTO v_pendientes;

    IF v_pendientes = 0 THEN
        RETURN;
    END IF;

    IF to_regprocedure(format('%I.resolver_codigo_dependencia(text,boolean)', current_schema())) IS NULL THEN
        RAISE EXCEPTION
            '% tiene % fila(s) con nombre de dependencia sin código y no existe '
            'resolver_codigo_dependencia (migración 013 de tenant-service): migre '
            'tenant-service antes que document-service', current_schema(), v_pendientes;
    END IF;

    -- 1) Evidencia de TODO lo pendiente aún no evidenciado (resuelto/ambiguo/huérfano).
    INSERT INTO dependencia_codigo_backfill_doc
           (tabla, fila_id, columna, nombre, codigo, candidatos, resultado)
    SELECT p.tabla, p.fila_id, p.columna, p.nombre, x.codigo, x.candidatos,
           CASE WHEN x.candidatos = 1 THEN 'resuelto'
                WHEN x.candidatos = 0 THEN 'huerfano'
                ELSE 'ambiguo' END
      FROM (
            SELECT 'radicados'::text AS tabla, id AS fila_id, 'dest_dept'::text AS columna,
                   dest_dept::text AS nombre
              FROM radicados WHERE dest_dept_code IS NULL AND dest_dept IS NOT NULL
            UNION ALL
            SELECT 'radicados', id, 'origin_dept', origin_dept::text
              FROM radicados WHERE origin_dept_code IS NULL AND origin_dept IS NOT NULL
            UNION ALL
            SELECT 'borrador', id, 'dest_dept', dest_dept::text
              FROM borrador WHERE dest_dept_code IS NULL AND dest_dept IS NOT NULL
           ) p
     CROSS JOIN LATERAL resolver_codigo_dependencia(p.nombre, true) x
     WHERE NOT EXISTS (
            SELECT 1 FROM dependencia_codigo_backfill_doc e
             WHERE e.tabla = p.tabla AND e.fila_id = p.fila_id AND e.columna = p.columna)
     ORDER BY p.tabla, p.fila_id, p.columna;

    -- 2) Se escribe SOLO lo resuelto con un único candidato. Sin `updated_at`.
    UPDATE radicados r SET dest_dept_code = e.codigo
      FROM dependencia_codigo_backfill_doc e
     WHERE e.tabla = 'radicados' AND e.columna = 'dest_dept' AND e.resultado = 'resuelto'
       AND e.fila_id = r.id AND r.dest_dept_code IS NULL AND r.dest_dept = e.nombre;
    GET DIAGNOSTICS v_resueltas = ROW_COUNT;

    UPDATE radicados r SET origin_dept_code = e.codigo
      FROM dependencia_codigo_backfill_doc e
     WHERE e.tabla = 'radicados' AND e.columna = 'origin_dept' AND e.resultado = 'resuelto'
       AND e.fila_id = r.id AND r.origin_dept_code IS NULL AND r.origin_dept = e.nombre;

    UPDATE borrador b SET dest_dept_code = e.codigo
      FROM dependencia_codigo_backfill_doc e
     WHERE e.tabla = 'borrador' AND e.columna = 'dest_dept' AND e.resultado = 'resuelto'
       AND e.fila_id = b.id AND b.dest_dept_code IS NULL AND b.dest_dept = e.nombre;

    SELECT count(*) INTO v_sin_codigo
      FROM dependencia_codigo_backfill_doc WHERE resultado <> 'resuelto';

    RAISE NOTICE 'backfill dependencia por código (%): % pendientes, % radicados.dest_dept_code escritos, % ambiguos/huérfanos con evidencia',
        current_schema(), v_pendientes, v_resueltas, v_sin_codigo;
END $$;

COMMENT ON COLUMN borrador.dest_dept_code IS
    'Código de la dependencia destino (ADR-032). Llave de correlación; dest_dept es la instantánea del nombre.';

-- >>> document-service/tenant/047_backfill_doc_mapeado.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant 047 (B5, ronda de corrección, ADR-032). search_path = tenant_{slug}.
--
-- Enlaza la evidencia del backfill de la 046 con la decisión humana que la resolvió:
-- `historico_id` apunta a la fila de `dependencia_nombre_historico` (origen
-- 'mapeo_manual') cuyo (nombre, código) coincide. «Mapeado» NO es un valor de
-- `resultado`: se DERIVA de `historico_id IS NOT NULL`. `resultado` y el resto de
-- columnas que ancla la 046 en `audit_log` (payload.columnas: tabla, fila_id, columna,
-- nombre, codigo, candidatos, resultado) NO se tocan, para que el SHA-256 del ancla
-- siga reproduciéndose; `historico_id` es una columna NUEVA y queda fuera de ese hash.
--
-- La evidencia es de solo inserción: el trigger se aparta DENTRO de la transacción
-- solo para completar la columna nueva (NULL -> valor) y se verifica que quedó
-- habilitado. Idempotente (IS NULL): la 2.ª ejecución no cambia filas.
-- Rollback: DROP COLUMN historico_id.

ALTER TABLE dependencia_codigo_backfill_doc ADD COLUMN IF NOT EXISTS historico_id BIGINT;

DO $$
BEGIN
    IF to_regclass(format('%I.dependencia_nombre_historico', current_schema())) IS NULL THEN
        RETURN;  -- tenant-service 013 aún no corrió: no hay mapeos que enlazar
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM dependencia_codigo_backfill_doc e
          JOIN dependencia_nombre_historico h
            ON h.origen = 'mapeo_manual' AND h.nombre = e.nombre AND h.codigo = e.codigo
         WHERE e.resultado = 'resuelto' AND e.historico_id IS NULL) THEN
        RETURN;
    END IF;
    ALTER TABLE dependencia_codigo_backfill_doc DISABLE TRIGGER trg_dependencia_codigo_backfill_doc_immutable;
    UPDATE dependencia_codigo_backfill_doc e
       SET historico_id = h.id
      FROM (SELECT DISTINCT ON (nombre, codigo) id, nombre, codigo
              FROM dependencia_nombre_historico WHERE origen = 'mapeo_manual'
             ORDER BY nombre, codigo, id DESC) h
     WHERE e.resultado = 'resuelto' AND e.historico_id IS NULL
       AND h.nombre = e.nombre AND h.codigo = e.codigo;
    ALTER TABLE dependencia_codigo_backfill_doc ENABLE TRIGGER trg_dependencia_codigo_backfill_doc_immutable;
    IF NOT EXISTS (SELECT 1 FROM pg_trigger
                    WHERE tgrelid = 'dependencia_codigo_backfill_doc'::regclass
                      AND tgname = 'trg_dependencia_codigo_backfill_doc_immutable' AND tgenabled = 'O') THEN
        RAISE EXCEPTION 'trg_dependencia_codigo_backfill_doc_immutable no quedó habilitado';
    END IF;
END $$;

-- >>> document-service/tenant/048_postal_callback_diferido.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 048 (B10, ADR-035 §7): cola de callbacks postales recibidos con la
-- entidad SUSPENDIDA. search_path = tenant_{slug} (ADR-012).
--
-- El operador postal manda UNA vez cada estado de entrega y reintenta por un tiempo
-- acotado. Contestarle 503 a una firma válida hacía que el evento (p. ej. la devolución
-- que abre un plazo) se perdiera si la suspensión duraba más que sus reintentos. Ahora
-- se guarda el cuerpo tal como llegó (la firma ya se verificó) y se aplica cuando la
-- entidad se reactiva: el barrido (fase 5) solo recorre tenants activos.
--
-- `cuerpo` se conserva en bytes crudos porque es la evidencia firmada; `recibido_at` es
-- el instante de la RECEPCIÓN del aviso del operador y es el que se asienta como `ts` del
-- evento del envío (no puede fecharse en el drenaje). NO es la fecha del hecho postal: si el
-- operador la manda (`ocurrido_at`, dentro del cuerpo firmado), se guarda aparte en
-- `postal_shipment_event.ocurrido_operador_at` y es esa la que sirve de referencia de entrega.
--
-- `intentos` acota el reintento de una fila que no se puede aplicar (error no HTTP que se
-- repite): al llegar al tope del servicio la fila se descarta con asiento y no bloquea la cola.
--
-- Idempotente. Rollback: DROP TABLE postal_callback_diferido;
--   ALTER TABLE postal_shipment_event DROP COLUMN ocurrido_operador_at.
ALTER TABLE postal_shipment_event ADD COLUMN IF NOT EXISTS ocurrido_operador_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS postal_callback_diferido (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    operador       VARCHAR(20)  NOT NULL,
    event_id       VARCHAR(120) NOT NULL,
    guia           VARCHAR(60)  NOT NULL,
    cuerpo         BYTEA        NOT NULL CHECK (octet_length(cuerpo) <= 65536),
    cuerpo_sha256  CHAR(64)     NOT NULL,
    firma_hmac     TEXT         NOT NULL,
    estado_interno VARCHAR(16)  NOT NULL,
    recibido_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    estado         VARCHAR(12)  NOT NULL DEFAULT 'pendiente'
                   CHECK (estado IN ('pendiente', 'procesado', 'descartado')),
    intentos       INTEGER      NOT NULL DEFAULT 0,
    ultimo_error   TEXT,
    resultado      VARCHAR(24),
    procesado_at   TIMESTAMPTZ,
    UNIQUE (operador, event_id),
    CONSTRAINT postal_diferido_cierre CHECK ((estado = 'pendiente') = (procesado_at IS NULL))
);

CREATE INDEX IF NOT EXISTS ix_postal_diferido_pendiente
    ON postal_callback_diferido (recibido_at, id) WHERE estado = 'pendiente';

-- >>> document-service/tenant/049_tercero_provisional.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (C17, ADR-038, 2026-10): FICHA PROVISIONAL del remitente
-- anónimo y su CONCILIACIÓN interna.
--
-- ── Qué había y por qué no bastaba ──────────────────────────────────────────
--
-- La ventanilla pública asociaba al remitente POR NÚMERO DE DOCUMENTO
-- (`crear_o_recuperar` → `get_por_documento`): quien escribía la cédula de otra
-- persona quedaba atado a SU ficha —con su dirección y teléfono vigentes— sin que
-- nadie verificara que era ella. Eso es a la vez un oráculo de enumeración (la
-- respuesta o el tiempo delatan que el documento existe) y una suplantación
-- gratuita (la ficha ajena entra a un radicado que el suplantador redactó).
--
-- ── Qué hace esta migración ─────────────────────────────────────────────────
--
-- Una ficha PROVISIONAL guarda lo que el anónimo DECLARÓ, pero NO ocupa el
-- documento: el número declarado vive en `documento_declarado_*` y
-- `tipo_documento/numero_documento` quedan en NULL, así que no choca con
-- `ux_tercero_documento` (UNIQUE sobre tipo+número, fusionadas incluidas). Un
-- funcionario la CONCILIA después: la vincula a la ficha existente (reutiliza
-- `fusionado_en`), la confirma como ficha nueva o la descarta. El radicado y su
-- número no se tocan (`radicado_actor.tercero_id` es inmutable por trigger y no
-- hace falta).
--
-- Las filas existentes quedan `identidad='confirmada'` por DEFAULT: no hay
-- backfill ni rama «legado».

ALTER TABLE tercero
    ADD COLUMN IF NOT EXISTS identidad                  text NOT NULL DEFAULT 'confirmada',
    ADD COLUMN IF NOT EXISTS documento_declarado_tipo   text,
    ADD COLUMN IF NOT EXISTS documento_declarado_numero text,
    ADD COLUMN IF NOT EXISTS conciliacion               text,
    ADD COLUMN IF NOT EXISTS conciliada_at              timestamptz,
    -- `auth_users.id` (el X-User-Id interno que firma el gateway), NUNCA el `sub`
    -- de Keycloak. Sin FK, igual que `creado_por` y `fusionado_por`.
    ADD COLUMN IF NOT EXISTS conciliada_por             uuid,
    ADD COLUMN IF NOT EXISTS conciliacion_motivo        text,
    -- Con qué se verificó la identidad al vincular o confirmar (evidencia archivística:
    -- sin ella el acto dice QUIÉN decidió, no en qué se basó).
    ADD COLUMN IF NOT EXISTS conciliacion_medio         text;

COMMENT ON COLUMN tercero.identidad IS
    'confirmada: la identidad (tipo+número de documento) fue verificada o es del catálogo. provisional: la declaró un anónimo en la ventanilla pública y NO ocupa el documento.';
COMMENT ON COLUMN tercero.documento_declarado_numero IS
    'Documento que el anónimo DECLARÓ. Evidencia: inmutable (trigger). No identifica a nadie hasta que un funcionario concilia.';
COMMENT ON COLUMN tercero.conciliacion IS
    'pendiente | vinculada (fusionada en una ficha existente) | confirmada (pasó a ficha definitiva) | descartada. NULL en fichas que nunca fueron provisionales.';
COMMENT ON COLUMN tercero.conciliacion_medio IS
    'presencial_documento | respuesta_canal_registrado | llamada_telefono_registrado | otro. Obligatorio al vincular o confirmar; con `otro`, el motivo es obligatorio.';
COMMENT ON COLUMN tercero.conciliada_por IS
    'auth_users.id de quien concilió; nunca el sub de Keycloak.';

ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_identidad_valores;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_identidad_valores
    CHECK (identidad IN ('confirmada', 'provisional'));

ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_conciliacion_valores;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_conciliacion_valores
    CHECK (conciliacion IS NULL
           OR conciliacion IN ('pendiente', 'vinculada', 'confirmada', 'descartada'));

-- Una provisional NO tiene identidad: ningún PATCH de ficha puede dársela por la
-- puerta de atrás, y por eso no choca con `ux_tercero_documento`.
ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_provisional_sin_identidad;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_provisional_sin_identidad
    CHECK (identidad <> 'provisional'
           OR (tipo_documento IS NULL
               AND numero_documento IS NULL
               AND documento_declarado_numero IS NOT NULL
               AND conciliacion IN ('pendiente', 'vinculada', 'descartada')));

ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_confirmada_conciliacion;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_confirmada_conciliacion
    CHECK (identidad <> 'confirmada'
           OR conciliacion IS NULL OR conciliacion = 'confirmada');

-- `pendiente` ⇔ nadie la ha conciliado todavía. Lo conciliado SIEMPRE tiene autor
-- y fecha: un acto sobre el directorio sin responsable no se puede registrar.
ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_conciliacion_autor;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_conciliacion_autor
    CHECK (conciliacion IS NULL
           OR ((conciliacion = 'pendiente')
               = (conciliada_at IS NULL AND conciliada_por IS NULL)));

ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_conciliacion_vinculada;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_conciliacion_vinculada
    CHECK (conciliacion IS DISTINCT FROM 'vinculada' OR fusionado_en IS NOT NULL);

ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_conciliacion_motivo;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_conciliacion_motivo
    CHECK ((conciliacion_motivo IS NULL OR length(btrim(conciliacion_motivo)) >= 10)
           AND (conciliacion IS DISTINCT FROM 'descartada' OR conciliacion_motivo IS NOT NULL));

-- El medio de verificación es obligatorio al vincular o confirmar (no al descartar), y
-- `otro` no se explica solo: exige motivo.
ALTER TABLE tercero DROP CONSTRAINT IF EXISTS chk_tercero_conciliacion_medio;
ALTER TABLE tercero
    ADD CONSTRAINT chk_tercero_conciliacion_medio
    CHECK ((conciliacion_medio IS NULL
            OR conciliacion_medio IN ('presencial_documento', 'respuesta_canal_registrado',
                                      'llamada_telefono_registrado', 'otro'))
           AND (conciliacion NOT IN ('vinculada', 'confirmada') OR conciliacion_medio IS NOT NULL)
           AND (conciliacion_medio IS DISTINCT FROM 'otro' OR conciliacion_motivo IS NOT NULL));

-- Lo declarado es evidencia: no se reescribe. Y un estado terminal no vuelve a
-- `pendiente` ni salta a otro terminal (una conciliación no se «deshace»; si fue
-- un error, se corrige con una ficha nueva y un asiento nuevo).
CREATE OR REPLACE FUNCTION reject_tercero_conciliacion_rewrite() RETURNS trigger AS $$
BEGIN
    IF NEW.documento_declarado_tipo IS DISTINCT FROM OLD.documento_declarado_tipo
       OR NEW.documento_declarado_numero IS DISTINCT FROM OLD.documento_declarado_numero
    THEN
        RAISE EXCEPTION
            'el documento declarado por el remitente es evidencia y no se edita (C17, ADR-038)';
    END IF;
    IF OLD.conciliacion IN ('vinculada', 'confirmada', 'descartada')
       AND NEW.conciliacion IS DISTINCT FROM OLD.conciliacion
    THEN
        RAISE EXCEPTION
            'una conciliación terminada no se rehace (C17, ADR-038)';
    END IF;
    IF OLD.identidad = 'confirmada' AND NEW.identidad = 'provisional' THEN
        RAISE EXCEPTION
            'una ficha confirmada no vuelve a provisional (C17, ADR-038)';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_tercero_conciliacion ON tercero;
CREATE TRIGGER trg_tercero_conciliacion
    BEFORE UPDATE ON tercero
    FOR EACH ROW EXECUTE FUNCTION reject_tercero_conciliacion_rewrite();

-- La cola de conciliación: lo pendiente, lo más antiguo primero.
CREATE INDEX IF NOT EXISTS ix_tercero_por_conciliar
    ON tercero (creado_at)
    WHERE conciliacion = 'pendiente';

-- Rollback (manual, no automatizado por el runner):
-- DROP TRIGGER IF EXISTS trg_tercero_conciliacion ON tercero;
-- DROP FUNCTION IF EXISTS reject_tercero_conciliacion_rewrite();
-- DROP INDEX IF EXISTS ix_tercero_por_conciliar;
-- ALTER TABLE tercero DROP COLUMN identidad, DROP COLUMN documento_declarado_tipo, ...;

-- >>> document-service/tenant/050_reserva_catalogo_y_desclasificacion.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.


-- Tenant migration 050 (C-2, ADR-039): catálogo cerrado de causales de reserva (C12) y
-- desclasificación desde nivel 3 con solicitud y aprobación por OTRA persona (C4).
--
-- 1) Las filas ya clasificadas cuya causal no cumple el catálogo pasan a `por_clasificar`
--    (valor explícito: no se inventa una causal; el índice público las muestra como
--    «pendiente de motivar» hasta que se re-motiven). No hay causal que deducir de un
--    texto libre, así que no hay backfill de datos.
-- 2) CHECK `radicados_causal_catalogo` (NOT VALID + VALIDATE, patrón 041): misma regla que
--    `app/core/causales_reserva.validar_clasificacion`; el guardián de tests compara los
--    códigos de este fichero con la constante de Python y con el `enum` de la tool MCP.
-- 3) Tabla `reclasificacion_solicitudes`: bajar de nivel 3 exige solicitud + aprobación de
--    una segunda persona con clearance suficiente. Aprobar EJECUTA, en la misma tx.
-- 4) Trigger de frontera en `radicados`: ninguna ruta (import, borrador, SQL, una ruta
--    futura) baja el nivel desde 3 sin una solicitud aprobada EN ESTA TRANSACCIÓN.
--
-- Idempotente. Rollback (en este orden):
--   DROP TRIGGER IF EXISTS trg_radicados_desclasificacion ON radicados;
--   DROP FUNCTION IF EXISTS radicados_desclasificacion_guard();
--   DROP TABLE IF EXISTS reclasificacion_solicitudes;
--   DROP FUNCTION IF EXISTS reclasificacion_solicitud_guard();
--   ALTER TABLE radicados DROP CONSTRAINT IF EXISTS radicados_causal_catalogo;
--   (las filas `por_clasificar` no se restauran: el texto libre original no se guardó.)

-- 1) lo clasificado que no cumple el catálogo --------------------------------------------
UPDATE radicados
   SET clasificacion_causal = 'por_clasificar'
 WHERE nivel_seguridad >= 2
   AND (   clasificacion_causal = 'por_clasificar'
        OR (nivel_seguridad = 3
            AND clasificacion_causal IN ('art18_a_intimidad', 'art18_b_vida_salud_seguridad', 'art18_c_secretos')
            AND clasificacion_plazo_meses IS NULL)
        OR (nivel_seguridad = 2
            AND clasificacion_causal IN ('art19_a_defensa_seguridad_nacional', 'art19_b_seguridad_publica',
                'art19_c_relaciones_internacionales', 'art19_d_prevencion_investigacion_delitos',
                'art19_e_debido_proceso', 'art19_f_administracion_justicia',
                'art19_g_infancia_adolescencia', 'art19_h_estabilidad_macroeconomica',
                'art19_i_salud_publica', 'art19_par_deliberativo')
            AND clasificacion_plazo_meses BETWEEN 1 AND 180)
       ) IS NOT TRUE;

UPDATE radicados
   SET clasificacion_causal = NULL, clasificacion_plazo_meses = NULL
 WHERE nivel_seguridad = 1
   AND (clasificacion_causal IS NOT NULL OR clasificacion_plazo_meses IS NOT NULL);

-- 2) CHECK del catálogo --------------------------------------------------------------------
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'radicados_causal_catalogo'
           AND conrelid = format('%I.radicados', current_schema())::regclass
    ) THEN
        ALTER TABLE radicados
            ADD CONSTRAINT radicados_causal_catalogo
            -- COALESCE: un CHECK con NULL (causal o plazo ausentes) PASA; aquí NULL es rechazo.
            CHECK (COALESCE(
                (nivel_seguridad = 1 AND clasificacion_causal IS NULL
                                     AND clasificacion_plazo_meses IS NULL)
                OR (nivel_seguridad >= 2 AND clasificacion_causal = 'por_clasificar')
                OR (nivel_seguridad = 3
                    AND clasificacion_causal IN ('art18_a_intimidad', 'art18_b_vida_salud_seguridad', 'art18_c_secretos')
                    AND clasificacion_plazo_meses IS NULL)
                OR (nivel_seguridad = 2
                    AND clasificacion_causal IN ('art19_a_defensa_seguridad_nacional', 'art19_b_seguridad_publica',
                        'art19_c_relaciones_internacionales', 'art19_d_prevencion_investigacion_delitos',
                        'art19_e_debido_proceso', 'art19_f_administracion_justicia',
                        'art19_g_infancia_adolescencia', 'art19_h_estabilidad_macroeconomica',
                        'art19_i_salud_publica', 'art19_par_deliberativo')
                    AND clasificacion_plazo_meses BETWEEN 1 AND 180),
                FALSE)
            ) NOT VALID;
    END IF;
    ALTER TABLE radicados VALIDATE CONSTRAINT radicados_causal_catalogo;
END $$;

-- 3) solicitudes de desclasificación ------------------------------------------------------
CREATE TABLE IF NOT EXISTS reclasificacion_solicitudes (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- CASCADE: la solicitud es parte del expediente del radicado; el único DELETE de
    -- radicados es la purga por disposición final (acta firmada) y el audit_log conserva
    -- la traza. El trigger de abajo prohíbe cualquier otro borrado.
    radicado_id         UUID NOT NULL REFERENCES radicados(id) ON DELETE CASCADE,
    -- Instantánea del nivel al pedir. = NIVEL_DOBLE_FIRMA (core/causales_reserva.py).
    nivel_anterior      SMALLINT NOT NULL CHECK (nivel_anterior = 3),
    nivel_nuevo         SMALLINT NOT NULL CHECK (nivel_nuevo IN (1, 2) AND nivel_nuevo < nivel_anterior),
    motivo              TEXT NOT NULL CHECK (length(btrim(motivo)) >= 10),
    causal_codigo       TEXT,
    fundamento_juridico TEXT,
    plazo_meses         INTEGER,
    estado              TEXT NOT NULL DEFAULT 'pendiente'
                        CHECK (estado IN ('pendiente', 'aprobada', 'rechazada', 'retirada', 'caducada')),
    solicitado_por      UUID NOT NULL,
    solicitado_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    vence_at            TIMESTAMPTZ NOT NULL DEFAULT now() + interval '15 days',
    resuelto_por        UUID,
    resuelto_at         TIMESTAMPTZ,
    resolucion_motivo   TEXT,
    -- La destinación lleva la misma regla que el CHECK de radicados.
    CONSTRAINT rs_causal_destino CHECK (COALESCE(
           (nivel_nuevo = 1 AND causal_codigo IS NULL AND plazo_meses IS NULL)
        OR (nivel_nuevo = 2
            AND causal_codigo IN ('art19_a_defensa_seguridad_nacional', 'art19_b_seguridad_publica',
                'art19_c_relaciones_internacionales', 'art19_d_prevencion_investigacion_delitos',
                'art19_e_debido_proceso', 'art19_f_administracion_justicia',
                'art19_g_infancia_adolescencia', 'art19_h_estabilidad_macroeconomica',
                'art19_i_salud_publica', 'art19_par_deliberativo')
            AND fundamento_juridico IS NOT NULL AND btrim(fundamento_juridico) <> ''
            AND plazo_meses BETWEEN 1 AND 180),
        FALSE)
    ),
    CONSTRAINT rs_resuelta_forma CHECK (
        estado IN ('pendiente', 'caducada')
        OR (resuelto_por IS NOT NULL AND resuelto_at IS NOT NULL)
    ),
    -- Separación de funciones en la base: quien pide no decide (ni con un UPDATE directo).
    CONSTRAINT rs_separacion_funciones CHECK (
        estado NOT IN ('aprobada', 'rechazada') OR resuelto_por <> solicitado_por
    ),
    CONSTRAINT rs_retirada_por_solicitante CHECK (
        estado <> 'retirada' OR resuelto_por = solicitado_por
    ),
    CONSTRAINT rs_rechazo_motivado CHECK (
        estado <> 'rechazada' OR length(btrim(coalesce(resolucion_motivo, ''))) >= 10
    )
);

-- A lo sumo UNA solicitud viva por radicado.
CREATE UNIQUE INDEX IF NOT EXISTS ux_rs_pendiente
    ON reclasificacion_solicitudes (radicado_id) WHERE estado = 'pendiente';
CREATE INDEX IF NOT EXISTS ix_rs_cola
    ON reclasificacion_solicitudes (solicitado_at) WHERE estado = 'pendiente';
CREATE INDEX IF NOT EXISTS ix_rs_radicado
    ON reclasificacion_solicitudes (radicado_id, solicitado_at DESC);

-- Una solicitud se resuelve UNA vez y su pedido no se reescribe; no se borra (salvo en
-- cascada desde la purga del radicado: ahí el trigger corre anidado, depth >= 2).
CREATE OR REPLACE FUNCTION reclasificacion_solicitud_guard() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF pg_trigger_depth() < 2 THEN
            RAISE EXCEPTION 'reclasificacion_solicitudes no se borra (traza de la desclasificación)'
                USING ERRCODE = 'P0001';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.estado <> 'pendiente' THEN
        RAISE EXCEPTION 'la solicitud de desclasificación ya está resuelta (%)', OLD.estado
            USING ERRCODE = 'P0001';
    END IF;
    IF NEW.estado = 'pendiente' THEN
        RAISE EXCEPTION 'una solicitud pendiente solo cambia a un estado final'
            USING ERRCODE = 'P0001';
    END IF;
    IF (NEW.id, NEW.radicado_id, NEW.nivel_anterior, NEW.nivel_nuevo, NEW.motivo,
        NEW.causal_codigo, NEW.fundamento_juridico, NEW.plazo_meses,
        NEW.solicitado_por, NEW.solicitado_at, NEW.vence_at)
       IS DISTINCT FROM
       (OLD.id, OLD.radicado_id, OLD.nivel_anterior, OLD.nivel_nuevo, OLD.motivo,
        OLD.causal_codigo, OLD.fundamento_juridico, OLD.plazo_meses,
        OLD.solicitado_por, OLD.solicitado_at, OLD.vence_at) THEN
        RAISE EXCEPTION 'el pedido de una solicitud de desclasificación no se reescribe'
            USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_reclasificacion_solicitud_guard ON reclasificacion_solicitudes;
CREATE TRIGGER trg_reclasificacion_solicitud_guard
    BEFORE UPDATE OR DELETE ON reclasificacion_solicitudes
    FOR EACH ROW EXECUTE FUNCTION reclasificacion_solicitud_guard();

-- 4) frontera: bajar desde nivel 3 solo con una solicitud aprobada en ESTA transacción ----
-- `resuelto_at = now()` (now() = inicio de la tx) ata la aprobación a este acto: una
-- aprobación vieja no sirve de pase para una desclasificación posterior.
CREATE OR REPLACE FUNCTION radicados_desclasificacion_guard() RETURNS trigger AS $$
BEGIN
    IF OLD.nivel_seguridad >= 3 AND NEW.nivel_seguridad < OLD.nivel_seguridad THEN
        IF NOT EXISTS (
            SELECT 1 FROM reclasificacion_solicitudes s
             WHERE s.radicado_id = NEW.id
               AND s.estado = 'aprobada'
               AND s.nivel_anterior = OLD.nivel_seguridad
               AND s.nivel_nuevo = NEW.nivel_seguridad
               AND s.resuelto_at = now()
        ) THEN
            RAISE EXCEPTION
                'bajar el nivel de un radicado clasificado exige una solicitud de desclasificación aprobada por otra persona'
                USING ERRCODE = 'P0001', HINT = 'desclasificacion_requiere_aprobacion';
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_radicados_desclasificacion ON radicados;
CREATE TRIGGER trg_radicados_desclasificacion
    BEFORE UPDATE OF nivel_seguridad ON radicados
    FOR EACH ROW EXECUTE FUNCTION radicados_desclasificacion_guard();

-- >>> document-service/tenant/051_reserva_tope_y_norma.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 051 (C-2, ADR-039, auditoría de cierre del lote C):
--
-- 1) TOPE DE 15 AÑOS DESDE LA GENERACIÓN (Ley 1712/2014 art. 22; Decreto 103/2015
--    art. 29, hoy DUR 1081/2015). La reserva del art. 19 no puede durar más de 15 años
--    contados desde que se GENERÓ la información (`registered_at`: la fecha de
--    radicación o, en un paquete importado, la del documento), no desde que se
--    clasificó. El plazo se mide SIEMPRE contra la generación: reiniciar
--    `clasificado_at` (2 -> 3 -> 2) no alarga la reserva, porque el plazo permitido es
--    `180 - meses transcurridos hasta la clasificación`.
--    `reserva_meses_entre(a, b)` = meses completos entre dos instantes (UTC), la misma
--    cuenta que usa el servicio al validar (la lee de la base: una sola definición).
-- 2) `clasificacion_norma`: cita normativa PUBLICABLE y controlada por formato (Decreto
--    103/2015 art. 40: «fundamento constitucional o legal»), separada del
--    `clasificacion_fundamento` libre, que es interno y puede transportar contenido.
--
-- Lo que no cumple el tope pasa a `por_clasificar` (valor explícito, patrón de la 050).
-- Idempotente. Rollback (en este orden):
--   ALTER TABLE radicados DROP CONSTRAINT IF EXISTS radicados_reserva_tope_15_anios;
--   ALTER TABLE radicados DROP CONSTRAINT IF EXISTS radicados_norma_controlada;
--   ALTER TABLE radicados DROP COLUMN IF EXISTS clasificacion_norma;
--   ALTER TABLE reclasificacion_solicitudes DROP CONSTRAINT IF EXISTS rs_norma_controlada;
--   ALTER TABLE reclasificacion_solicitudes DROP COLUMN IF EXISTS fundamento_norma;
--   DROP FUNCTION IF EXISTS reserva_meses_entre(timestamptz, timestamptz);

CREATE OR REPLACE FUNCTION reserva_meses_entre(desde timestamptz, hasta timestamptz)
RETURNS integer AS $$
    SELECT GREATEST(0, (
        EXTRACT(YEAR  FROM age(hasta AT TIME ZONE 'UTC', desde AT TIME ZONE 'UTC'))::int * 12
      + EXTRACT(MONTH FROM age(hasta AT TIME ZONE 'UTC', desde AT TIME ZONE 'UTC'))::int
    ))
$$ LANGUAGE sql IMMUTABLE;

-- 1) tope -------------------------------------------------------------------------------
UPDATE radicados
   SET clasificacion_causal = 'por_clasificar'
 WHERE nivel_seguridad = 2
   AND clasificacion_causal <> 'por_clasificar'
   AND clasificacion_plazo_meses > 180 - reserva_meses_entre(
           registered_at, COALESCE(clasificado_at, registered_at));

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'radicados_reserva_tope_15_anios'
           AND conrelid = format('%I.radicados', current_schema())::regclass
    ) THEN
        ALTER TABLE radicados
            ADD CONSTRAINT radicados_reserva_tope_15_anios
            CHECK (COALESCE(
                nivel_seguridad <> 2
                OR clasificacion_causal = 'por_clasificar'
                OR clasificacion_plazo_meses IS NULL
                OR clasificacion_plazo_meses
                   <= 180 - reserva_meses_entre(registered_at, COALESCE(clasificado_at, registered_at)),
                FALSE)
            ) NOT VALID;
    END IF;
    ALTER TABLE radicados VALIDATE CONSTRAINT radicados_reserva_tope_15_anios;
END $$;

-- 2) cita normativa publicable ------------------------------------------------------------
ALTER TABLE radicados ADD COLUMN IF NOT EXISTS clasificacion_norma TEXT;
ALTER TABLE reclasificacion_solicitudes ADD COLUMN IF NOT EXISTS fundamento_norma TEXT;

-- Misma regla que `app/core/causales_reserva.CITA_NORMA_RE` (el guardián las compara):
-- una norma, no una frase. Tipo de norma + número/artículo, 160 caracteres como máximo.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'radicados_norma_controlada'
           AND conrelid = format('%I.radicados', current_schema())::regclass
    ) THEN
        ALTER TABLE radicados
            ADD CONSTRAINT radicados_norma_controlada
            CHECK (clasificacion_norma IS NULL OR (
                nivel_seguridad >= 2
                AND clasificacion_norma ~ '^(Constitución Política|Ley|Decreto-Ley|Decreto|Acuerdo|Resolución|Código)[ A-Za-z0-9ÁÉÍÓÚÑáéíóúñ.,°º/()-]{1,150}$'
                AND clasificacion_norma ~ '[0-9]'
            )) NOT VALID;
    END IF;
    ALTER TABLE radicados VALIDATE CONSTRAINT radicados_norma_controlada;
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'rs_norma_controlada'
           AND conrelid = format('%I.reclasificacion_solicitudes', current_schema())::regclass
    ) THEN
        ALTER TABLE reclasificacion_solicitudes
            ADD CONSTRAINT rs_norma_controlada
            CHECK (fundamento_norma IS NULL OR (
                nivel_nuevo = 2
                AND fundamento_norma ~ '^(Constitución Política|Ley|Decreto-Ley|Decreto|Acuerdo|Resolución|Código)[ A-Za-z0-9ÁÉÍÓÚÑáéíóúñ.,°º/()-]{1,150}$'
                AND fundamento_norma ~ '[0-9]'
            )) NOT VALID;
    END IF;
    ALTER TABLE reclasificacion_solicitudes VALIDATE CONSTRAINT rs_norma_controlada;
END $$;

-- El pedido de una solicitud no se reescribe: ahora incluye la cita normativa.
CREATE OR REPLACE FUNCTION reclasificacion_solicitud_guard() RETURNS trigger AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF pg_trigger_depth() < 2 THEN
            RAISE EXCEPTION 'reclasificacion_solicitudes no se borra (traza de la desclasificación)'
                USING ERRCODE = 'P0001';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.estado <> 'pendiente' THEN
        RAISE EXCEPTION 'la solicitud de desclasificación ya está resuelta (%)', OLD.estado
            USING ERRCODE = 'P0001';
    END IF;
    IF NEW.estado = 'pendiente' THEN
        RAISE EXCEPTION 'una solicitud pendiente solo cambia a un estado final'
            USING ERRCODE = 'P0001';
    END IF;
    IF (NEW.id, NEW.radicado_id, NEW.nivel_anterior, NEW.nivel_nuevo, NEW.motivo,
        NEW.causal_codigo, NEW.fundamento_juridico, NEW.fundamento_norma, NEW.plazo_meses,
        NEW.solicitado_por, NEW.solicitado_at, NEW.vence_at)
       IS DISTINCT FROM
       (OLD.id, OLD.radicado_id, OLD.nivel_anterior, OLD.nivel_nuevo, OLD.motivo,
        OLD.causal_codigo, OLD.fundamento_juridico, OLD.fundamento_norma, OLD.plazo_meses,
        OLD.solicitado_por, OLD.solicitado_at, OLD.vence_at) THEN
        RAISE EXCEPTION 'el pedido de una solicitud de desclasificación no se reescribe'
            USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- >>> document-service/tenant/052_termino_inicial.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
