-- Migración de tenant (E10 Increment A, RF-PRE-03, AGN 001/2024 Art. 4.3.2.6):
-- registro de objetos protegidos bajo WORM real (MinIO Object Lock).
--
-- Cada fila es la constancia de que una copia INMUTABLE de un artefacto (hoy: el
-- índice electrónico firmado — E15/E06; el AIP es un Increment B posterior) fue
-- subida a un bucket con Object Lock habilitado, con retención derivada de la TRD.
-- Sirve al gate de disposición final (`purge_for_disposition`): mientras exista
-- una fila con `retain_until` futuro o `legal_hold = true` para un expediente, la
-- purga física de sus archivos queda bloqueada.

CREATE TABLE IF NOT EXISTS preservacion_worm_objeto (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    expediente_id   TEXT NOT NULL,
    tipo            TEXT NOT NULL CHECK (tipo IN ('indice', 'aip')),
    bucket          TEXT NOT NULL,
    object_key      TEXT NOT NULL,
    version_id      TEXT,
    sha256          CHAR(64) NOT NULL,
    retain_until    TIMESTAMPTZ NOT NULL,
    retention_mode  TEXT NOT NULL,
    legal_hold      BOOLEAN NOT NULL DEFAULT false,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_preservacion_worm_expediente
    ON preservacion_worm_objeto (expediente_id);

-- >>> storage-service/tenant/007_aip_real.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E10 Increment B, RF-PRE-05/07, ISO 14721 OAIS):
-- convierte el AIP stub (Increment A: un string BagIt sintético, sin bytes
-- reales, guardado íntegro en la columna `bagit`) en el AIP real: un ZIP
-- BagIt+PREMIS v3 subido al bucket WORM del tenant (misma fundación Object
-- Lock del Increment A, `preservacion_worm_objeto` con tipo='aip', ya
-- admitido desde la migración 006).
--
-- Aditiva y NULLABLE: las filas `aip` insertadas en el Increment A (stub)
-- siguen siendo válidas — sus columnas nuevas quedan NULL. `bagit` deja de
-- ser NOT NULL porque el Bag real ya no se guarda como texto en esta tabla
-- (vive como ZIP en MinIO, referenciado por bucket/object_key); las filas
-- nuevas simplemente no la escriben.

ALTER TABLE aip ADD COLUMN IF NOT EXISTS bucket         TEXT;
ALTER TABLE aip ADD COLUMN IF NOT EXISTS object_key     TEXT;
ALTER TABLE aip ADD COLUMN IF NOT EXISTS aip_bytes      BIGINT;
ALTER TABLE aip ADD COLUMN IF NOT EXISTS formato        TEXT NOT NULL DEFAULT 'application/zip';
ALTER TABLE aip ADD COLUMN IF NOT EXISTS retain_until   TIMESTAMPTZ;
ALTER TABLE aip ADD COLUMN IF NOT EXISTS retention_mode TEXT;
ALTER TABLE aip ADD COLUMN IF NOT EXISTS legal_hold     BOOLEAN NOT NULL DEFAULT false;

-- `bagit` (columna del stub del Increment A) deja de escribirse desde el
-- código de aplicación a partir de este incremento; se afloja la restricción
-- para no romper los INSERT reales (loosening de una restricción es siempre
-- retrocompatible con las filas existentes).
ALTER TABLE aip ALTER COLUMN bagit DROP NOT NULL;

-- >>> storage-service/tenant/008_preservacion_evento_no_evaluado.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E10 Increment C2a, RF-PRE-02, RF-FIR-15): habilita un
-- TERCER estado honesto en `preservacion_evento.resultado` — 'no_evaluado' —
-- para el evento VALIDACION_PDFA cuando el validador PDF/A real no está
-- disponible en el despliegue (`StubPdfaValidator` por defecto). Antes el
-- CHECK solo admitía ('ok','fallo'): el resultado más frecuente en la
-- práctica (validación no realizada) NO cabía, obligando a mentir con 'ok'
-- o 'fallo' — ninguno de los dos es honesto cuando simplemente no se evaluó.
--
-- `resultado` se ensancha de VARCHAR(8) a VARCHAR(16): 'no_evaluado' tiene
-- 11 caracteres y no entraba en VARCHAR(8). Ensanchar una columna VARCHAR es
-- retrocompatible con las filas existentes (todas más cortas que el nuevo
-- límite). Sin columnas nuevas: el detalle JSONB + `agente` ya existentes
-- alcanzan para registrar perfil/versión/outcome del validador (ver
-- `app/schemas/preservacion.py::EventoCreate`, `app/services/pdfa`).
--
-- Idempotente: `ALTER COLUMN ... TYPE` no falla al reaplicarse (mismo tipo),
-- y el DROP/ADD CONSTRAINT usa el nombre por defecto de Postgres para un
-- CHECK inline de columna (`{tabla}_{columna}_check`) con `IF EXISTS`.

ALTER TABLE preservacion_evento ALTER COLUMN resultado TYPE VARCHAR(16);

ALTER TABLE preservacion_evento DROP CONSTRAINT IF EXISTS preservacion_evento_resultado_check;
ALTER TABLE preservacion_evento
    ADD CONSTRAINT preservacion_evento_resultado_check
    CHECK (resultado IN ('ok', 'fallo', 'no_evaluado'));

-- >>> storage-service/tenant/009_preservacion_worm_idempotencia.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E10 Increment A cierre — Inc.1, cableado WORM del
-- índice electrónico desde archive-service): cierra el hueco de idempotencia
-- de `POST /proteger-indice`.
--
-- Hoy la tabla no guarda `file_id` (solo el `object_key`/`bucket` YA
-- resueltos) ni tiene ninguna restricción que impida dos filas para el MISMO
-- expediente. Con el disparo automático (síncrono al cierre + barrida de
-- reconciliación), dos llamadas al mismo `expediente_id` — intento síncrono
-- que "cuelga" y luego reintenta, o carrera entre el intento síncrono y una
-- barrida concurrente — crearían DOS objetos WORM COMPLIANCE distintos para
-- el mismo índice: irreversibles, sin forma de deshacer el duplicado.
--
-- `file_id` se añade para que la fila registre TAMBIÉN la clave de negocio
-- (antes solo la resolución física bucket/object_key). El respaldo de
-- idempotencia en BD es un ÍNDICE ÚNICO PARCIAL, no un `UNIQUE(expediente_id,
-- tipo)` liso: ese constraint amplio también alcanzaría a `tipo='aip'`
-- (Increment B), donde SÍ es legítimo re-empaquetar el AIP de un expediente
-- más de una vez a lo largo del tiempo (nuevo documento incorporado, nueva
-- migración de formato) — nada en Increment B asume o prueba "un solo AIP
-- por expediente para siempre". El índice electrónico, en cambio, es un
-- SINGLETON por expediente (append-only, una sola versión llega a
-- `estado='firmado'`, ver `expediente_indice` en archive-service) — de ahí
-- que el respaldo se acote a `tipo='indice'`.
--
-- Aditiva/idempotente: `ADD COLUMN IF NOT EXISTS` + índice único parcial
-- creado solo si no existe ya.

ALTER TABLE preservacion_worm_objeto
    ADD COLUMN IF NOT EXISTS file_id UUID;

COMMENT ON COLUMN preservacion_worm_objeto.file_id IS
    'file_id de `files` cuyo contenido quedó protegido bajo WORM (Inc.1, cableado) — antes solo se registraba la resolución física bucket/object_key, sin la clave de negocio.';

CREATE UNIQUE INDEX IF NOT EXISTS ux_preservacion_worm_objeto_expediente_indice
    ON preservacion_worm_objeto (expediente_id)
    WHERE tipo = 'indice';

-- Rollback (manual, no automatizado por el runner):
-- DROP INDEX IF EXISTS ux_preservacion_worm_objeto_expediente_indice;
-- ALTER TABLE preservacion_worm_objeto DROP COLUMN IF EXISTS file_id;

-- >>> storage-service/tenant/010_preservacion_worm_acta.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E10 Inc.2 wiring — cableado WORM/Object-Lock del ACTA
-- de transferencia firmada, fast-follow declarado en el diseño de Inc.1: "Acta
-- = generalizar tipo CHECK a incluir acta_transferencia... comparte
-- fixity/retención/gate"): generaliza `preservacion_worm_objeto` (migración
-- 006) para admitir `tipo='acta_transferencia'`, SIN tocar el comportamiento
-- ya probado de `tipo='indice'`.
--
-- Unicidad por-expediente para `acta_transferencia` es SEGURA de mirar
-- (mismo criterio que la migración 009 para el índice): el ciclo de vida del
-- expediente (`open -> closed -> transferred`, TERMINAL) y el índice único
-- `ux_transferencias_activa_por_expediente` (migración 024, archive-service)
-- garantizan que un expediente alcanza `estado='recibida'` (y por tanto un
-- acta congelada) A LO SUMO UNA VEZ en toda su vida — `create()` exige
-- `closed`, que un expediente `transferred` nunca vuelve a ser. El acta de
-- transferencia es, en la práctica, tan SINGLETON por expediente como el
-- índice electrónico.
--
-- El nombre del constraint CHECK es el que Postgres asigna por defecto al
-- declararlo inline en la migración 006 (`<tabla>_<columna>_check`) —
-- verificado contra un Postgres real antes de integrar esta migración.
--
-- Aditiva/idempotente: `DROP CONSTRAINT IF EXISTS` + `ADD CONSTRAINT` (el
-- CHECK en sí no admite `IF NOT EXISTS`, de ahí el drop-then-add, seguro de
-- re-ejecutar) + `CREATE INDEX IF NOT EXISTS`. Segura de re-ejecutar sobre un
-- schema ya migrado.

ALTER TABLE preservacion_worm_objeto
    DROP CONSTRAINT IF EXISTS preservacion_worm_objeto_tipo_check;

ALTER TABLE preservacion_worm_objeto
    ADD CONSTRAINT preservacion_worm_objeto_tipo_check
    CHECK (tipo IN ('indice', 'aip', 'acta_transferencia'));

