-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (R-4, ADR-021 Fase 2): tabla durable de dead-letter de eventos.
--
-- Almacena los eventos que alcanzaron el umbral de reintentos sin poder procesarse.
-- El INSERT usa ON CONFLICT (event_id) DO NOTHING para garantizar idempotencia: un
-- reintento del mismo mensaje (XADD ok pero XACK falló, at-least-once) no produce
-- duplicados ni dobles trazas en audit_log.
--
-- El stream Redis orpycamcp.workflow.deadletter conserva su rol de buffer operativo
-- para inspección y replay; esta tabla es la copia autoritativa y durable (Postgres)
-- que satisface Ley 594/2000 art. 4 y art. 19 (trazabilidad, integridad, durabilidad).
--
-- Rollback:
--   DROP TABLE IF EXISTS evento_dead_letter;
--   DROP INDEX IF EXISTS ix_evento_dead_letter_at;

CREATE TABLE IF NOT EXISTS evento_dead_letter (
    event_id          TEXT        PRIMARY KEY,           -- ID único del sobre de evento (idempotencia)
    event_type        TEXT,
    correlation_id    TEXT,
    tenant_slug       TEXT        NOT NULL,
    payload           JSONB       NOT NULL,              -- sobre íntegro (incl. payload de negocio)
    failure           JSONB       NOT NULL,              -- failure_meta: reason, last_error, counts, etc.
    origin_stream     TEXT,
    origin_group      TEXT,
    dead_lettered_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE evento_dead_letter IS
    'Copia durable (Postgres) de los eventos aparcados en el dead-letter de Redis. '
    'event_id como PK garantiza idempotencia (ON CONFLICT DO NOTHING). '
    'El INSERT y el audit_log se escriben en la misma transacción (R-4, ADR-021): '
    'no hay dead-letter sin traza durable.';

COMMENT ON COLUMN evento_dead_letter.payload IS
    'Sobre íntegro del evento (event_id, event_type, tenant_slug, occurred_at, actor, '
    'payload de negocio). Autosuficiente para reconstrucción forense (Ley 594/2000 art. 19).';

COMMENT ON COLUMN evento_dead_letter.failure IS
    'failure_meta del helper reclaim_stale: dead_letter_reason, dead_letter_last_error, '
    'dead_letter_delivery_count, dead_lettered_at, origin stream/group/consumer.';

-- Índice por dead_lettered_at para consultas de inspección y TTL operativo.
CREATE INDEX IF NOT EXISTS ix_evento_dead_letter_at
    ON evento_dead_letter (dead_lettered_at);

-- >>> workflow-service/tenant/010_deadletter_status.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-021 Fase 5): ciclo de vida de evento_dead_letter.
--
-- Añade el estado del dead-letter para habilitar inspección y replay/discard:
--   pending   → recién aparcado, sin resolver (estado inicial por defecto)
--   resolved  → reprocesado con éxito por un admin (replay)
--   discarded → descartado deliberadamente por un admin (con motivo)
--
-- Idempotente: PG15 no soporta ADD COLUMN IF NOT EXISTS, por lo que se usa el
-- patrón DO $$ … information_schema.columns … $$ para no fallar en re-ejecución.
--
-- Rollback:
--   ALTER TABLE evento_dead_letter DROP COLUMN IF EXISTS status;
--   ALTER TABLE evento_dead_letter DROP COLUMN IF EXISTS resolved_at;
--   DROP INDEX IF EXISTS ix_edl_pending;
--   DROP INDEX IF EXISTS ix_edl_resolved;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'evento_dead_letter' AND column_name = 'status'
    ) THEN
        ALTER TABLE evento_dead_letter
            ADD COLUMN status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'resolved', 'discarded'));
    END IF;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'evento_dead_letter' AND column_name = 'resolved_at'
    ) THEN
        ALTER TABLE evento_dead_letter
            ADD COLUMN resolved_at TIMESTAMPTZ NULL;
    END IF;
END $$;

-- Índice parcial para la bandeja de pendientes (consulta más frecuente).
CREATE INDEX IF NOT EXISTS ix_edl_pending
    ON evento_dead_letter (dead_lettered_at)
    WHERE status = 'pending';

-- Índice parcial para auditoría/retención de cerrados (resolved/discarded).
CREATE INDEX IF NOT EXISTS ix_edl_resolved
    ON evento_dead_letter (resolved_at)
    WHERE status IN ('resolved', 'discarded');

COMMENT ON COLUMN evento_dead_letter.status IS
    'Ciclo de vida del dead-letter: pending (inicial) → resolved (replay OK) | '
    'discarded (descarte deliberado con motivo). ADR-021 Fase 5.';
COMMENT ON COLUMN evento_dead_letter.resolved_at IS
    'Momento de la transición a resolved/discarded (NULL mientras pending).';

-- >>> workflow-service/tenant/011_deadletter_origin_group_notnull.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-021, seguimiento no-bloqueante Fase 5):
--   origin_group NOT NULL + índice compuesto sobre la tabla COMPARTIDA evento_dead_letter.
-- SEGURA por diseño: origin_group nunca se inserta NULL (reclaim_stale en
--   orpycamcp_common.events siempre escribe dead_letter_group=GROUP y los 3 workers
--   pasan origin_group=failure_meta["dead_letter_group"]). Ver ADR-021 §D.
-- Guard defensivo: además, se sanea cualquier fila legada con origin_group NULL antes
--   del SET NOT NULL para no abortar la migración en un entorno ya desplegado (en dev es
--   no-op). El sentinel 'unknown' es invisible a TODAS las queries por-servicio
--   (ningún servicio consulta ese origin_group) → la fila queda fail-closed, sin
--   mis-atribución a signature/workflow/notification.
-- IDEMPOTENTE y sin pisarse entre los 3 servicios: actúan sobre la MISMA tabla física;
--   SET NOT NULL es no-op si ya es NOT NULL (PG15) y CREATE INDEX IF NOT EXISTS
--   lo crea el primero que corra, los demás no-op. El nombre del índice es ÚNICO y
--   compartido: ix_edl_tenant_group_status (NO usar nombres por-servicio).
--
-- Rollback:
--   DROP INDEX IF EXISTS ix_edl_tenant_group_status;
--   ALTER TABLE evento_dead_letter ALTER COLUMN origin_group DROP NOT NULL;

UPDATE evento_dead_letter SET origin_group = 'unknown' WHERE origin_group IS NULL;

ALTER TABLE evento_dead_letter
    ALTER COLUMN origin_group SET NOT NULL;

CREATE INDEX IF NOT EXISTS ix_edl_tenant_group_status
    ON evento_dead_letter (tenant_slug, origin_group, status);

-- Nota índice: orden (tenant_slug, origin_group, status) cubre el predicado de
-- list_pending/list_scoped_for_clearance (WHERE tenant_slug=$1 AND status=$2 AND
-- origin_group=$3, todas igualdades); el orden de columnas del índice es
-- independiente del orden en el WHERE.

-- >>> workflow-service/tenant/012_transaction_types_requires_holder.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
