-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-028): tenencia de las transacciones de trámite.
--
-- `requires_holder`: la transacción solo la puede ejecutar el POSEEDOR del paso
-- activo (assigned_to = actor, o paso de dependencia sin dueño y el actor
-- pertenece a ella). Cierra el hueco por el que cualquiera con PERM_TRAMITAR
-- podía marcar como leído —y así mover el estado del radicado— un trámite ajeno.
-- Hoy solo `marcar_leido` (el único que mueve el estado a `in_progress`).
--
-- Idempotente. Rollback:
--   ALTER TABLE transaction_types DROP COLUMN IF EXISTS requires_holder;

ALTER TABLE transaction_types
    ADD COLUMN IF NOT EXISTS requires_holder BOOLEAN NOT NULL DEFAULT false;

UPDATE transaction_types
   SET requires_holder = true
 WHERE code = 'marcar_leido'
   AND requires_holder IS DISTINCT FROM true;

-- >>> workflow-service/tenant/013_radicado_estado_desde_flujo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-028): el flujo mueve el estado del radicado.
--
-- Recalcula `radicados.status` de los radicados existentes desde `flow_steps`,
-- con el CASE gemelo LITERAL de la función pura
-- `app/services/estado_radicado.py::derivar_estado_radicado` (la prueba de
-- integración compara cada fila con la función Python):
--
--   terminal (closed|anulado)       -> no se toca
--   paso activo 'pending'           -> distributed
--   paso activo 'in_progress'       -> in_progress
--   registered con algún paso       -> distributed
--   cualquier otro                  -> se conserva
--
-- Cada cambio queda en `radicado_estado_recalculo`: tabla de SOLO INSERCIÓN
-- (trigger que rechaza UPDATE/DELETE, como `flow_events`) con el número de
-- radicado, el estado antes/después, el estado del paso activo que lo motivó y
-- `origen = 'migracion_013'`. Es la evidencia de una escritura masiva sobre un
-- campo con valor legal: debe poder leerse años después y no poder reescribirse.
--
-- El backfill NO toca `updated_at`: recalcular un estado derivado no es una edición
-- del radicado, y moverle la fecha de modificación a miles de documentos oficiales
-- falsea «cuándo se modificó por última vez» (la evidencia lleva su propio `at`).
--
-- NO se escribe `audit_log` desde SQL: la cadena de hash la firma la aplicación y
-- un asiento forjado desde aquí rompería su integridad. El asiento-ancla
-- (`workflow.estado_radicado.backfill`: conteo + SHA-256 del contenido ordenado de
-- esta tabla) lo escribe el RUNNER de migraciones (Python, `audit.append`) justo
-- después de aplicar este archivo, en la misma transacción — ver
-- `migrations/runner.py::anclar_backfill_013`.
--
-- Idempotente: la 2.ª ejecución no cambia ninguna fila (IS DISTINCT FROM) y no
-- añade evidencia. Si `radicados` aún no existe en este schema (tenant nuevo, el
-- document-service migra después) no hace nada: no hay datos que recalcular.
--
-- Rollback (la evidencia permite restaurar; el trigger se retira antes de borrar):
--   UPDATE radicados r SET status = e.antes FROM radicado_estado_recalculo e
--    WHERE e.radicado_id = r.id AND r.status = e.despues;
--   DROP TABLE radicado_estado_recalculo;

CREATE TABLE IF NOT EXISTS radicado_estado_recalculo (
    id              BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    radicado_id     UUID        NOT NULL,
    tracking_number VARCHAR(50) NOT NULL,
    antes           VARCHAR(20) NOT NULL,
    despues         VARCHAR(20) NOT NULL,
    paso_activo     VARCHAR(20),          -- estado del paso activo que motivó el cambio (NULL = sin paso activo)
    origen          VARCHAR(40) NOT NULL DEFAULT 'migracion_013',
    at              TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION reject_radicado_estado_recalculo_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'radicado_estado_recalculo is append-only (evidencia de la migración 013)';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_radicado_estado_recalculo_immutable ON radicado_estado_recalculo;
CREATE TRIGGER trg_radicado_estado_recalculo_immutable
    BEFORE UPDATE OR DELETE ON radicado_estado_recalculo
    FOR EACH ROW EXECUTE FUNCTION reject_radicado_estado_recalculo_mutation();

DO $$
DECLARE
    v_cambiados   INTEGER;
    v_terminales  INTEGER;
BEGIN
    IF to_regclass(format('%I.radicados', current_schema())) IS NULL THEN
        RAISE NOTICE 'radicados no existe en %: backfill de estado omitido', current_schema();
        RETURN;
    END IF;

    WITH activo AS (
        SELECT DISTINCT ON (radicado_id) radicado_id, status
          FROM flow_steps
         WHERE status IN ('pending', 'in_progress')
         ORDER BY radicado_id, step_number DESC
    ),
    con_pasos AS (
        SELECT DISTINCT radicado_id FROM flow_steps
    ),
    calc AS (
        SELECT r.id,
               r.tracking_number,
               r.status AS antes,
               a.status AS paso_activo,
               CASE
                   WHEN a.status = 'pending'     THEN 'distributed'
                   WHEN a.status = 'in_progress' THEN 'in_progress'
                   WHEN r.status = 'registered' AND cp.radicado_id IS NOT NULL
                                                 THEN 'distributed'
                   ELSE r.status
               END AS despues
          FROM radicados r
          LEFT JOIN activo    a  ON a.radicado_id  = r.id
          LEFT JOIN con_pasos cp ON cp.radicado_id = r.id
         WHERE r.status NOT IN ('closed', 'anulado')
    ),
    upd AS (
        UPDATE radicados r
           SET status = c.despues
          FROM calc c
         WHERE r.id = c.id
           AND r.status IS DISTINCT FROM c.despues
        RETURNING r.id, c.tracking_number, c.antes, c.despues, c.paso_activo
    )
    INSERT INTO radicado_estado_recalculo
           (radicado_id, tracking_number, antes, despues, paso_activo)
    SELECT id, tracking_number, antes, despues, paso_activo FROM upd;

    GET DIAGNOSTICS v_cambiados = ROW_COUNT;

    -- Terminales que aún tienen un paso activo (anulado/cerrado sin cancelar el
    -- paso). No se tocan aquí: los sanea la migración 015 con su propia evidencia.
    SELECT count(*) INTO v_terminales
      FROM radicados r
     WHERE r.status IN ('closed', 'anulado')
       AND EXISTS (SELECT 1 FROM flow_steps f
                    WHERE f.radicado_id = r.id
                      AND f.status IN ('pending', 'in_progress'));

    RAISE NOTICE 'backfill estado radicado (%): % recalculados, % terminales con paso activo',
        current_schema(), v_cambiados, v_terminales;
END $$;

-- >>> workflow-service/tenant/014_anular_exige_poseedor.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-028, remediación de auditoría): la transacción `anular`
-- exige tenencia.
--
-- `anular` cancela el paso activo (`target_step_status = 'cancelled'`) y, sin
-- `requires_holder`, cualquiera con PERM_ANULAR podía cancelar el paso de OTRA
-- persona —y, de paso, sondear radicados ajenos por el 409 `radicado_terminal`
-- (oráculo). El código ya exige tenencia a TODA transacción que mueve el paso;
-- esta fila deja el catálogo diciendo lo mismo que el código.
--
-- Nota de alcance: la anulación del RADICADO (acto con causal y aprobador) vive en
-- document-service y no pasa por aquí; esto es solo el motor genérico de trámite.
--
-- Idempotente. Rollback:
--   UPDATE transaction_types SET requires_holder = false WHERE code = 'anular';

UPDATE transaction_types
   SET requires_holder = true
 WHERE code = 'anular'
   AND requires_holder IS DISTINCT FROM true;

-- >>> workflow-service/tenant/015_sanear_pasos_zombi.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-028, remediación de auditoría): sanea los pasos «zombi».
--
-- Un paso zombi es un paso ACTIVO (pending/in_progress) de un radicado TERMINAL
-- (closed/anulado). Nace de dos caminos anteriores al ADR: la anulación no
-- cancelaba el paso, y el `PATCH status` manual cerraba el radicado sin cerrar el
-- paso. Un zombi aparece en bandeja, cuenta como vencido, entra en la cascada y
-- NO se puede cerrar (el radicado ya es terminal: todo acto responde 409).
--
-- Tratamiento, por radicado terminal con paso activo:
--   anulado -> el paso pasa a 'cancelled'  (el trámite se canceló con el radicado)
--   closed  -> el paso pasa a 'completed'  (el radicado se cerró: el paso concluyó)
-- y cada paso tratado deja (a) un evento operativo `saneamiento_terminal` en
-- `flow_events` (append-only) y (b) una fila de evidencia en
-- `flow_step_saneamiento` (solo inserción, con el estado antes/después del paso).
-- No toca `radicados`. El asiento-ancla en `audit_log` (conteo + SHA-256 del
-- contenido ordenado) lo escribe el runner (`anclar_saneamiento_015`), nunca SQL.
--
-- Idempotente: tras la 1.ª corrida no quedan zombis, la 2.ª no encuentra ninguno.
-- Si `radicados` no existe en este schema, no hace nada.
--
-- Rollback (la evidencia permite restaurar; los eventos append-only se conservan):
--   UPDATE flow_steps f SET status = e.paso_antes, completed_at = NULL
--     FROM flow_step_saneamiento e WHERE e.step_id = f.id AND f.status = e.paso_despues;
--   DROP TABLE flow_step_saneamiento;

CREATE TABLE IF NOT EXISTS flow_step_saneamiento (
    id               BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    step_id          UUID        NOT NULL,
    radicado_id      UUID        NOT NULL,
    tracking_number  VARCHAR(50) NOT NULL,
    estado_radicado  VARCHAR(20) NOT NULL,  -- closed | anulado
    paso_antes       VARCHAR(20) NOT NULL,
    paso_despues     VARCHAR(20) NOT NULL,
    flow_event_id    UUID        NOT NULL,
    origen           VARCHAR(40) NOT NULL DEFAULT 'migracion_015',
    at               TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION reject_flow_step_saneamiento_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'flow_step_saneamiento is append-only (evidencia de la migración 015)';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_flow_step_saneamiento_immutable ON flow_step_saneamiento;
CREATE TRIGGER trg_flow_step_saneamiento_immutable
    BEFORE UPDATE OR DELETE ON flow_step_saneamiento
    FOR EACH ROW EXECUTE FUNCTION reject_flow_step_saneamiento_mutation();

DO $$
DECLARE
    v_saneados INTEGER;
BEGIN
    IF to_regclass(format('%I.radicados', current_schema())) IS NULL THEN
        RAISE NOTICE 'radicados no existe en %: saneamiento de pasos omitido', current_schema();
        RETURN;
    END IF;

    WITH zombis AS (
        SELECT f.id AS step_id, f.radicado_id, f.tracking_number, f.to_dept,
               f.status AS paso_antes, r.status AS estado_radicado,
               gen_random_uuid() AS ev_id
          FROM flow_steps f
          JOIN radicados r ON r.id = f.radicado_id
         WHERE f.status IN ('pending', 'in_progress')
           AND r.status IN ('closed', 'anulado')
    ),
    upd AS (
        UPDATE flow_steps f
           SET status = CASE WHEN z.estado_radicado = 'anulado'
                             THEN 'cancelled' ELSE 'completed' END,
               completed_at = now()
          FROM zombis z
         WHERE f.id = z.step_id
        RETURNING z.step_id, z.radicado_id, z.tracking_number, z.to_dept,
                  z.paso_antes, f.status AS paso_despues, z.estado_radicado, z.ev_id
    ),
    ev AS (
        INSERT INTO flow_events
               (id, radicado_id, tracking_number, tipo_tx, from_dept, to_dept,
                actor, comentario, detalles)
        SELECT ev_id, radicado_id, tracking_number, 'saneamiento_terminal', to_dept, to_dept,
               NULL,
               'Paso activo de un radicado ' || estado_radicado || ' saneado por la migración 015',
               jsonb_build_object('step_id', step_id, 'paso_antes', paso_antes,
                                  'paso_despues', paso_despues,
                                  'estado_radicado', estado_radicado)
          FROM upd
        RETURNING id
    )
    INSERT INTO flow_step_saneamiento
           (step_id, radicado_id, tracking_number, estado_radicado,
            paso_antes, paso_despues, flow_event_id)
    SELECT step_id, radicado_id, tracking_number, estado_radicado,
           paso_antes, paso_despues, ev_id
      FROM upd;

    GET DIAGNOSTICS v_saneados = ROW_COUNT;
    RAISE NOTICE 'saneamiento de pasos zombi (%): % pasos', current_schema(), v_saneados;
END $$;

-- >>> workflow-service/tenant/016_radicado_ubicacion_desde_flujo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-029): ubicación actual del radicado desde el flujo.
--
-- Rellena `radicados.flujo_dept` / `flujo_dept_code` / `flujo_usuario` (columnas
-- que crea la migración 037 de document-service) para los radicados existentes,
-- con el gemelo LITERAL de `app/services/estado_radicado.py::derivar_ubicacion`
-- (la prueba de integración compara cada fila con la función Python):
--
--   paso activo (pending|in_progress)  -> el de mayor step_number
--   sin paso activo                    -> el que se cerró más reciente
--                                         (completed_at DESC, step_number DESC),
--                                         en CUALQUIER estado
--   sin pasos                          -> no se escribe (la lectura cae a la
--                                         dependencia de radicación)
--   código                             -> solo si el NOMBRE casa con exactamente
--                                         UNA dependencia activa; si no, NULL y
--                                         el nombre queda como instantánea
--   terminal (closed|anulado)          -> se rellena solo si NUNCA se escribió;
--                                         si ya tiene ubicación, no se toca
--
-- Cada cambio queda en `radicado_ubicacion_recalculo`: tabla de SOLO INSERCIÓN
-- (trigger que rechaza UPDATE/DELETE) con el antes/después y
-- `origen = 'migracion_016'`. NO se escribe `audit_log` desde SQL: el asiento-ancla
-- (`workflow.ubicacion_radicado.backfill`: conteo + SHA-256 del contenido ordenado)
-- lo escribe el RUNNER (`migrations/runner.py::_ANCLAS`), en la misma transacción.
-- El backfill NO toca `updated_at`: recalcular un dato derivado no es editar el
-- documento.
--
-- Guardas de ORDEN (la migración se marca aplicada al terminar, así que un `skip`
-- silencioso donde hay datos dejaría la entidad sin backfill para siempre):
--   * `radicados` no existe en este schema -> no hay datos que recalcular: omite.
--   * `radicados` existe pero SIN las columnas (el runner de document-service no
--     corrió) -> RAISE: falla ruidosa, se reintenta tras migrar document-service.
--
-- Idempotente: la 2.ª ejecución no cambia ninguna fila (IS DISTINCT FROM).
--
-- Rollback (la evidencia permite restaurar; se retira el trigger antes de borrar):
--   UPDATE radicados r SET flujo_dept = e.antes_dept, flujo_dept_code = e.antes_dept_code,
--          flujo_usuario = e.antes_usuario
--     FROM radicado_ubicacion_recalculo e WHERE e.radicado_id = r.id;
--   DROP TABLE radicado_ubicacion_recalculo;

CREATE TABLE IF NOT EXISTS radicado_ubicacion_recalculo (
    id                BIGINT      GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    radicado_id       UUID        NOT NULL,
    tracking_number   VARCHAR(50) NOT NULL,
    estado_radicado   VARCHAR(20) NOT NULL,
    antes_dept        VARCHAR(100),
    antes_dept_code   INTEGER,
    antes_usuario     UUID,
    despues_dept      VARCHAR(100),
    despues_dept_code INTEGER,
    despues_usuario   UUID,
    paso_id           UUID,                -- paso que motivó la ubicación (NULL = ninguno)
    origen            VARCHAR(40) NOT NULL DEFAULT 'migracion_016',
    at                TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION reject_radicado_ubicacion_recalculo_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'radicado_ubicacion_recalculo is append-only (evidencia de la migración 016)';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_radicado_ubicacion_recalculo_immutable ON radicado_ubicacion_recalculo;
CREATE TRIGGER trg_radicado_ubicacion_recalculo_immutable
    BEFORE UPDATE OR DELETE ON radicado_ubicacion_recalculo
    FOR EACH ROW EXECUTE FUNCTION reject_radicado_ubicacion_recalculo_mutation();

DO $$
DECLARE
    v_cambiados  INTEGER;
    v_sin_codigo INTEGER;
BEGIN
    IF to_regclass(format('%I.radicados', current_schema())) IS NULL THEN
        RAISE NOTICE 'radicados no existe en %: backfill de ubicación omitido', current_schema();
        RETURN;
    END IF;

    IF (SELECT count(*) FROM information_schema.columns
         WHERE table_schema = current_schema() AND table_name = 'radicados'
           AND column_name IN ('flujo_dept', 'flujo_dept_code', 'flujo_usuario')) < 3 THEN
        RAISE EXCEPTION
            'radicados de % no tiene las columnas flujo_* (migración 037 de document-service): '
            'migre document-service antes que workflow-service', current_schema();
    END IF;

    WITH elegido AS (
        SELECT DISTINCT ON (s.radicado_id)
               s.radicado_id, s.id AS paso_id, s.to_dept, s.assigned_to
          FROM flow_steps s
         ORDER BY s.radicado_id,
                  (s.status IN ('pending', 'in_progress')) DESC,
                  CASE WHEN s.status IN ('pending', 'in_progress') THEN NULL
                       ELSE s.completed_at END DESC NULLS LAST,
                  s.step_number DESC
    ),
    calc AS (
        SELECT r.id, r.tracking_number, r.status,
               r.flujo_dept AS antes_dept, r.flujo_dept_code AS antes_dept_code,
               r.flujo_usuario AS antes_usuario,
               e.to_dept AS despues_dept,
               (SELECT CASE WHEN count(*) = 1 THEN min(d.codigo::integer) END
                  FROM dependencias d
                 WHERE d.nombre = e.to_dept AND d.activo = TRUE) AS despues_dept_code,
               e.assigned_to AS despues_usuario,
               e.paso_id
          FROM radicados r
          LEFT JOIN elegido e ON e.radicado_id = r.id
         WHERE r.status NOT IN ('closed', 'anulado') OR r.flujo_dept IS NULL
    ),
    upd AS (
        UPDATE radicados r
           SET flujo_dept = c.despues_dept,
               flujo_dept_code = c.despues_dept_code,
               flujo_usuario = c.despues_usuario
          FROM calc c
         WHERE r.id = c.id
           AND (r.flujo_dept IS DISTINCT FROM c.despues_dept
                OR r.flujo_dept_code IS DISTINCT FROM c.despues_dept_code
                OR r.flujo_usuario IS DISTINCT FROM c.despues_usuario)
        RETURNING r.id, c.tracking_number, c.status,
                  c.antes_dept, c.antes_dept_code, c.antes_usuario,
                  c.despues_dept, c.despues_dept_code, c.despues_usuario, c.paso_id
    )
    INSERT INTO radicado_ubicacion_recalculo
           (radicado_id, tracking_number, estado_radicado,
            antes_dept, antes_dept_code, antes_usuario,
            despues_dept, despues_dept_code, despues_usuario, paso_id)
    SELECT id, tracking_number, status,
           antes_dept, antes_dept_code, antes_usuario,
           despues_dept, despues_dept_code, despues_usuario, paso_id
      FROM upd;

    GET DIAGNOSTICS v_cambiados = ROW_COUNT;

    SELECT count(*) INTO v_sin_codigo
      FROM radicados WHERE flujo_dept IS NOT NULL AND flujo_dept_code IS NULL;

    RAISE NOTICE 'backfill ubicación radicado (%): % recalculados, % con nombre sin código único',
        current_schema(), v_cambiados, v_sin_codigo;
END $$;

-- >>> workflow-service/tenant/017_dead_letter_pk_por_grupo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (AREA-10-07, ADR-021): la PK de la tabla COMPARTIDA
-- evento_dead_letter pasa de (event_id) a (origin_group, event_id).
--
-- workflow, signature, notification y knowledge escriben en la MISMA tabla física
-- (misma base y mismo schema de tenant) y los cuatro leen `orpycamcp.document.events`
-- (o el stream de su dominio). Con PK solo por event_id, cuando un mismo evento
-- agotaba los reintentos en DOS grupos, el segundo INSERT ... ON CONFLICT DO NOTHING
-- era un no-op: ese grupo no dejaba fila ni asiento `evento.dead_letter`, su admin no
-- lo veía (el listado filtra por origin_group) y el XACK ya lo había sacado de la PEL.
-- Perdía en silencio la trazabilidad (Ley 594/2000 arts. 4 y 19).
--
-- IDEMPOTENTE y compartida entre los 4 servicios: corre primero el que llegue antes;
-- los demás ven la PK ya compuesta y no hacen nada. El LOCK evita que dos runners
-- simultáneos se pisen al soltar/crear la restricción.
--
-- Rollback (solo si no hay filas con el mismo event_id en dos grupos):
--   ALTER TABLE evento_dead_letter DROP CONSTRAINT evento_dead_letter_pkey,
--       ADD PRIMARY KEY (event_id);

DO $$
DECLARE
    cols text[];
BEGIN
    LOCK TABLE evento_dead_letter IN ACCESS EXCLUSIVE MODE;

    SELECT array_agg(a.attname::text ORDER BY k.ord)
      INTO cols
      FROM pg_constraint c
      CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord)
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
     WHERE c.conrelid = to_regclass('evento_dead_letter')
       AND c.contype = 'p';

    IF cols IS DISTINCT FROM ARRAY['origin_group', 'event_id'] THEN
        -- Una fila legada sin grupo quedaría fuera de la PK; el centinela 'unknown'
        -- es invisible a todas las consultas por servicio (fail-closed).
        UPDATE evento_dead_letter SET origin_group = 'unknown' WHERE origin_group IS NULL;
        ALTER TABLE evento_dead_letter ALTER COLUMN origin_group SET NOT NULL;
        ALTER TABLE evento_dead_letter DROP CONSTRAINT IF EXISTS evento_dead_letter_pkey;
        ALTER TABLE evento_dead_letter ADD PRIMARY KEY (origin_group, event_id);
    END IF;
END $$;

COMMENT ON TABLE evento_dead_letter IS
    'Copia durable (Postgres) de los eventos aparcados en el dead-letter de Redis. '
    'Tabla COMPARTIDA por los consumidores del tenant: la PK (origin_group, event_id) '
    'deja que cada grupo aparque el mismo evento una vez; repetir el mismo par es '
    'idempotente (ON CONFLICT (origin_group, event_id) DO NOTHING). El INSERT y el '
    'audit_log se escriben en la misma transacción (R-4, ADR-021).';

-- >>> workflow-service/tenant/018_dead_letter_indice_keyset.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
