-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E02 §9, RF-EXP-01/08/09/10): hoja de ruta del expediente
-- APPEND-ONLY (Canal B / hoja de ruta operativa, E08 §9).
--
-- Traza lógica del expediente exigida por RF-EXP-01 ("historial de eventos" entre los
-- metadatos mínimos), RF-EXP-08 (reapertura justificada en historial) y RF-EXP-09 ("toda
-- operación queda en el historial append-only"). Distinta de `movimiento_fisico` (E17,
-- movimientos físicos de unidades) y de `public.audit_log` (E08, auditoría forense). Se
-- escribe en la misma transacción que cada operación del expediente y NUNCA acepta
-- UPDATE/DELETE (trigger). Visible a quien pueda LEER el expediente (acotado por clearance).

CREATE TABLE IF NOT EXISTS expediente_eventos (
    id                 UUID         NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    expediente_id      UUID         NOT NULL,
    numero_expediente  TEXT,
    accion             TEXT         NOT NULL,   -- abierto | radicado_vinculado | radicado_excluido
                                                -- | responsable_cambiado | reabierto | cerrado
                                                -- | transferido | reclasificado | disposicion_aplicada
    actor              UUID,                    -- quién ejecuta la operación
    comentario         TEXT,
    detalles           JSONB        NOT NULL DEFAULT '{}'::jsonb,
    ts                 TIMESTAMPTZ  NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS ix_expediente_eventos_exp ON expediente_eventos (expediente_id, ts);

-- Inmutabilidad: rechaza UPDATE y DELETE (append-only, Ley 594/2000).
CREATE OR REPLACE FUNCTION reject_expediente_eventos_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'expediente_eventos is append-only (Ley 594/2000)';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_expediente_eventos_immutable ON expediente_eventos;
CREATE TRIGGER trg_expediente_eventos_immutable
    BEFORE UPDATE OR DELETE ON expediente_eventos
    FOR EACH ROW EXECUTE FUNCTION reject_expediente_eventos_mutation();

-- >>> archive-service/tenant/015_expediente_indice_pendiente_firma.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06 Inc.1, XAdES-B + ADR-016 / RT-16): nuevo estado
-- 'pendiente_firma' del índice electrónico.
--
-- Decisión del usuario: si el sellado XAdES-B del índice falla al cierre del
-- expediente (sello del tenant no aprovisionado, signature-service
-- inalcanzable, etc.), el cierre del expediente NO se bloquea — el índice
-- queda en 'pendiente_firma' (en vez de 'vigente' silencioso, que ocultaba el
-- fallo) y puede reintentarse vía POST /expedientes/{id}/indice/firmar
-- (idempotente). Ensancha el CHECK de `expediente_indice.estado` definido en
-- 008_expediente_indice.sql ('vigente','firmado') sin tocar filas existentes.

DO $$
DECLARE
    old_name text;
BEGIN
    -- Localiza el nombre real del CHECK sobre `estado` (auto-generado por
    -- Postgres en 008 como `expediente_indice_estado_check`, pero se busca por
    -- definición en vez de asumir el nombre para que la migración sea robusta
    -- ante una ejecución previa de sí misma).
    SELECT con.conname INTO old_name
    FROM pg_constraint con
    JOIN pg_class rel ON rel.oid = con.conrelid
    WHERE rel.relname = 'expediente_indice'
      AND con.contype = 'c'
      AND pg_get_constraintdef(con.oid) ILIKE '%estado%'
    LIMIT 1;

    IF old_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE expediente_indice DROP CONSTRAINT %I', old_name);
    END IF;

    ALTER TABLE expediente_indice
        ADD CONSTRAINT expediente_indice_estado_check
        CHECK (estado IN ('vigente', 'pendiente_firma', 'firmado'));
END $$;

-- >>> archive-service/tenant/016_radicado_index_metadata.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E15 Inc.3, Acuerdo AGN 001/2024 art. 4.3.2.3): metadatos
-- RT-15 del índice electrónico — formato (MIME), tamaño en bytes y foliación.
--
-- Decisión del usuario (Q1): los tres campos se APORTAN al vincular el radicado
-- al expediente (Opción A) — igual que `content_hash` en 009 — sin que
-- archive-service consulte a document-service/storage-service. Todos son
-- NULLABLE y opcionales: un cliente que no los envía sigue funcionando igual
-- (retrocompatibilidad total del contrato de vínculo).
--
-- `expediente_indice_item.formato`/`tamano_bytes` ya existen desde
-- 008_expediente_indice.sql (declarados pero nunca poblados); aquí solo se
-- añade `folios` a esa tabla. `expediente_radicados` no tenía ninguno de los
-- tres — se añaden aquí.

ALTER TABLE expediente_radicados
    ADD COLUMN IF NOT EXISTS formato TEXT;

ALTER TABLE expediente_radicados
    ADD COLUMN IF NOT EXISTS tamano_bytes BIGINT;

ALTER TABLE expediente_radicados
    ADD COLUMN IF NOT EXISTS folios INTEGER;

ALTER TABLE expediente_indice_item
    ADD COLUMN IF NOT EXISTS folios INTEGER;

COMMENT ON COLUMN expediente_radicados.formato IS
    'Tipo MIME del documento aportado al vincular (E15 RT-15, Opción A); NULL = no declarado.';
COMMENT ON COLUMN expediente_radicados.tamano_bytes IS
    'Tamaño en bytes del documento aportado al vincular (E15 RT-15, Opción A); NULL = no declarado.';
COMMENT ON COLUMN expediente_radicados.folios IS
    'Número de folios del documento aportado al vincular (E15 RT-15, Opción A); NULL = no declarado.';
COMMENT ON COLUMN expediente_indice_item.folios IS
    'Snapshot inmutable de folios en la versión del índice (E15 RT-15); NULL = no declarado.';

-- ADD CONSTRAINT no es idempotente en PG15 (no admite IF NOT EXISTS) — se
-- localiza por definición antes de crear, igual que el patrón de 015.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM pg_constraint con
        JOIN pg_class rel ON rel.oid = con.conrelid
        JOIN pg_namespace nsp ON nsp.oid = rel.relnamespace
