-- >>> archive-service/tenant/040_trd_serie_id_fk_validate.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-025, Increment 2 -- cierre del pendiente declarado
-- en el comentario de la 037: "la validacion completa (VALIDATE CONSTRAINT)
-- va en el Increment 2, tras depurar huerfanos"). `expedientes_trd_serie_id_fkey`
-- quedó NOT VALID desde la 037 -- protege escrituras nuevas pero NO garantiza
-- que el historial sea consistente; sin `VALIDATE CONSTRAINT` el motor no
-- puede afirmar la integridad referencial completa que el FK promete.
--
-- Decisión sobre huérfanos (expedientes.trd_serie_id que no resuelve a
-- ninguna fila de trd_series): esta migración NO los depura -- ni a NULL ni
-- por DELETE. Un `trd_serie_id` huérfano es, en un sistema de archivo, un
-- vínculo con la posición de un expediente en la TRD que gobernó (o debió
-- gobernar) su retención/disposición; poner el campo a NULL destruiría esa
-- evidencia posicional sin dejar rastro de que existió, y borrar el
-- expediente sería borrar un documento público (Ley 594/2000). Ninguna de
-- las dos es una operación de migración legítima -- ambas son decisiones
-- archivísticas que le corresponden a un archivista/administrador con el
-- expediente concreto delante, no a un script.
--
-- En cambio: la propia 037 YA detecta y marca este caso. Su backfill de
-- `trd_serie_code` (líneas 186-190 de esa migración) hace un JOIN contra
-- `trd_series`; si `trd_serie_id` no resuelve, `trd_serie_code` queda NULL
-- -- y la 037 marca esas filas con `trd_revision_requerida = true,
-- trd_revision_motivo = 'serie_no_resoluble'` (líneas 217-222). Esta
-- migración reutiliza esa misma señal (no reinventa el criterio: audita
-- directamente contra `trd_series` para no depender de que `trd_serie_code`
-- se haya mantenido en sincronía) y, si encuentra huérfanos pendientes,
-- FALLA RUIDOSAMENTE listándolos -- no valida el FK, no toca los datos. Un
-- operador resuelve cada caso (motivo real por el que ese `trd_serie_id` no
-- resuelve: dato de prueba, migración de un tenant anterior a ADR-025,
-- corrupción puntual) y vuelve a correr esta misma migración -- es
-- re-ejecutable hasta que el historial quede limpio.
--
-- Idempotente + guard por `current_schema()` (no por el nombre desnudo de la
-- constraint -- lección de `documentos/specDrive` sobre guards que repiten
-- `conname`/columna entre esquemas y dejan al tenant #2 sin el objeto):
-- primero resuelve el `pg_constraint` de ESTE schema; si ya está validada,
-- no hace nada (es exactamente lo que hace `ALTER ... VALIDATE CONSTRAINT`
-- al re-ejecutarse, pero el guard evita incluso reintentar el escaneo).
DO $$
DECLARE
    v_validated  boolean;
    v_orphans    int;
    v_detail     text;
BEGIN
    SELECT c.convalidated
      INTO v_validated
      FROM pg_constraint c
      JOIN pg_class t ON t.oid = c.conrelid
      JOIN pg_namespace n ON n.oid = t.relnamespace
     WHERE n.nspname = current_schema()
       AND t.relname = 'expedientes'
       AND c.conname = 'expedientes_trd_serie_id_fkey';

    IF v_validated IS NULL THEN
        RAISE EXCEPTION
            'expedientes_trd_serie_id_fkey no existe en el schema % -- aplicar la migracion 037 antes que esta (ADR-025)',
            current_schema();
    END IF;

    IF v_validated THEN
        RAISE NOTICE 'expedientes_trd_serie_id_fkey ya esta VALIDATED en % -- nada que hacer', current_schema();
        RETURN;
    END IF;

    SELECT count(*),
           string_agg(
               format(
                   'expediente %s (status=%s, trd_serie_id=%s, trd_serie_code=%s, trd_revision_motivo=%s)',
                   e.id, e.status, e.trd_serie_id,
                   coalesce(e.trd_serie_code, 'NULL'),
                   coalesce(e.trd_revision_motivo, 'NULL')
               ),
               '; '
               ORDER BY e.id
           )
      INTO v_orphans, v_detail
      FROM expedientes e
     WHERE e.trd_serie_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM trd_series s WHERE s.id = e.trd_serie_id);

    IF v_orphans > 0 THEN
        RAISE EXCEPTION
            'No se valida expedientes_trd_serie_id_fkey en %: % expediente(s) con trd_serie_id huerfano (sin fila en trd_series). No se depuran automaticamente -- requiere decision archivistica caso por caso (ver comentario de esta migracion). Huerfanos: %',
            current_schema(), v_orphans, v_detail;
    END IF;

    ALTER TABLE expedientes VALIDATE CONSTRAINT expedientes_trd_serie_id_fkey;
    RAISE NOTICE 'expedientes_trd_serie_id_fkey validada en % (sin huerfanos)', current_schema();
END $$;

-- Rollback (referencia manual, no ejecutado por el runner):
--   ALTER TABLE expedientes ALTER CONSTRAINT expedientes_trd_serie_id_fkey NOT VALID;
--   (Postgres no soporta "invalidar" un FK ya validado; para revertir de
--   verdad hay que DROP + volver a ADD ... NOT VALID, como en la 037.)

-- >>> archive-service/tenant/041_fondo_acumulado_amarre.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-026, Increment 2): amarre de expedientes de
-- FONDO ACUMULADO a una TVD (ADR-026 D3) + relajación de la Capa 4
-- (`trg_expedientes_pin_tipo`, instalada ESTRICTA por la 039) a la regla
-- `origen <-> tipo_instrumento`.
--
-- Guards acotados a `current_schema()` (ADR-002/012, lección de las
-- migraciones 016/017/019/035, reparadas por la 036).

-- ---------------------------------------------------------------------------
-- 1. `expedientes.origen` + fechas extremas del fondo acumulado
-- ---------------------------------------------------------------------------
-- DEFAULT 'corriente' describe un HECHO VERIFICABLE (todo expediente
-- anterior a esta migración se abrió y cerró bajo el circuito TRD ordinario
-- -- el trigger ESTRICTO de la 039 lo garantiza: hasta hoy, NINGÚN
-- expediente pudo amarrarse a una TVD) -- mismo criterio que el
-- `tipo_instrumento` DEFAULT 'TRD' de la 039, no el de `estado` de la 037.
ALTER TABLE expedientes
    ADD COLUMN IF NOT EXISTS origen                 VARCHAR(20) NOT NULL DEFAULT 'corriente',
    ADD COLUMN IF NOT EXISTS fecha_extrema_inicial   DATE,
    ADD COLUMN IF NOT EXISTS fecha_extrema_final     DATE;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint c
        JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace n ON n.oid = t.relnamespace
        WHERE n.nspname = current_schema() AND t.relname = 'expedientes'
          AND c.conname = 'expedientes_origen_check') THEN
        ALTER TABLE expedientes ADD CONSTRAINT expedientes_origen_check
            CHECK (origen IN ('corriente', 'fondo_acumulado'));
    END IF;

    -- ADR-026 D4: la fecha base del calendario de un fondo acumulado es la
    -- EXTREMA FINAL, nunca `closed_at` -- por eso, a diferencia de
    -- `trd_series_tvd_forma_check` (que exige TAMBIÉN `fondo_nombre` y
    -- `justificacion_valoracion`, propios del INSTRUMENTO, no del
    -- expediente), aquí solo `fecha_extrema_final` es NOT NULL bajo CHECK:
    -- es la única columna que este `compute_retention` va a leer. `>= inicial`
    -- solo se exige cuando ambas están presentes -- `fecha_extrema_inicial`
    -- es informativa (documenta el rango del fondo) y puede desconocerse.
    IF NOT EXISTS (SELECT 1 FROM pg_constraint c
        JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace n ON n.oid = t.relnamespace
        WHERE n.nspname = current_schema() AND t.relname = 'expedientes'
          AND c.conname = 'expedientes_fondo_acumulado_forma_check') THEN
        ALTER TABLE expedientes ADD CONSTRAINT expedientes_fondo_acumulado_forma_check
            CHECK (origen <> 'fondo_acumulado' OR (
                fecha_extrema_final IS NOT NULL AND (
                    fecha_extrema_inicial IS NULL
                    OR fecha_extrema_inicial <= fecha_extrema_final
                )));
    END IF;

    -- Reverso (negación declarada, mismo criterio que
    -- `trd_series_trd_forma_check` de la 039): un expediente `corriente` no
    -- puede cargar fechas extremas de un fondo que no es. Sin esto, un
    -- expediente `corriente` con `fecha_extrema_final` residual (p. ej. tras
    -- un `PATCH` mal formado, si algún día `origen` se hiciera editable)
    -- quedaría en una forma ambigua que ningún lector podría distinguir de
    -- un fondo acumulado sin marcar.
    IF NOT EXISTS (SELECT 1 FROM pg_constraint c
        JOIN pg_class t ON t.oid = c.conrelid JOIN pg_namespace n ON n.oid = t.relnamespace
        WHERE n.nspname = current_schema() AND t.relname = 'expedientes'
          AND c.conname = 'expedientes_corriente_forma_check') THEN
        ALTER TABLE expedientes ADD CONSTRAINT expedientes_corriente_forma_check
            CHECK (origen <> 'corriente' OR (
                fecha_extrema_inicial IS NULL AND fecha_extrema_final IS NULL
            ));
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS ix_expedientes_origen ON expedientes (origen);

-- ---------------------------------------------------------------------------
-- 2. Capa 4 relajada: `origen <-> tipo_instrumento`, no ya el bloqueo total
--    de la 039. El trigger SIGUE existiendo -- ninguna combinación cruzada
--    (corriente/TVD, fondo_acumulado/TRD) puede colarse -- solo cambia la
--    regla que aplica. `CREATE OR REPLACE FUNCTION` basta: el trigger
--    `trg_expedientes_pin_tipo` (039) ya apunta a esta función.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION assert_expediente_pin_tipo_instrumento() RETURNS trigger AS $$
DECLARE
    pin_tipo VARCHAR(3);
BEGIN
    IF NEW.trd_serie_id IS NOT NULL
       AND (TG_OP = 'INSERT' OR NEW.trd_serie_id IS DISTINCT FROM OLD.trd_serie_id) THEN
        SELECT tipo_instrumento INTO pin_tipo FROM trd_series WHERE id = NEW.trd_serie_id;

        IF NEW.origen = 'corriente' AND pin_tipo = 'TVD' THEN
            RAISE EXCEPTION 'expedientes: un expediente origen=corriente no puede amarrarse a la TVD % -- el fondo acumulado se registra con origen=fondo_acumulado (ADR-026 D3)',
                NEW.trd_serie_id;
        ELSIF NEW.origen = 'fondo_acumulado' AND pin_tipo = 'TRD' THEN
            RAISE EXCEPTION 'expedientes: un expediente origen=fondo_acumulado no puede amarrarse a la TRD % -- el fondo acumulado se valora con una TVD (ADR-026 D3)',
                NEW.trd_serie_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Rollback (referencia manual, no ejecutado por el runner):
--   ALTER TABLE expedientes DROP CONSTRAINT IF EXISTS expedientes_corriente_forma_check;
--   ALTER TABLE expedientes DROP CONSTRAINT IF EXISTS expedientes_fondo_acumulado_forma_check;
--   ALTER TABLE expedientes DROP CONSTRAINT IF EXISTS expedientes_origen_check;
--   DROP INDEX IF EXISTS ix_expedientes_origen;
--   (el rollback de `assert_expediente_pin_tipo_instrumento` a su forma
--    ESTRICTA -- 039 -- NO puede ejecutarse si ya existe algún expediente
--    origen='fondo_acumulado')

-- >>> archive-service/tenant/042_expediente_publicable.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Esquema de publicación para EXPEDIENTES — Ley 1712/2014 art. 12.
-- Espejo de `document-service tenant/019_radicado_publicable.sql`.
--
-- ── Por qué esta migración existe ────────────────────────────────────────────
-- La 019 corrigió la premisa para radicados: «público» dejaba de deducirse de la
-- ausencia de reserva y pasaba a exigir un acto de la entidad. Pero el acto se
-- aplicó a UN canal de tres. Este servicio conservó
-- `oai_repository._PUBLIC = "nivel_seguridad = 1"`, de modo que el OAI EAD
-- multinivel seguía difundiendo de oficio el código, el nombre, la descripción,
-- las fechas extremas y el conteo de radicados de **todo expediente no
-- clasificado** — que es exactamente el valor por defecto de la columna.
--
-- Lo señalaron por separado los dos auditores (seguridad y conformidad) de la
-- revisión de 2026-08-13. La asimetría era además el peor tipo de fallo de esta
-- familia: implícita. Quien leyera el `_PUBLIC` de document-service supondría,
-- con toda razón, que archive-service hace lo mismo.
--
-- ── El diseño, y qué NO se copia ─────────────────────────────────────────────
-- `DEFAULT FALSE`: ningún expediente existente ni futuro se difunde por no
-- haberse dicho nada. El quién y el cuándo se guardan aquí para poder responder
-- «desde cuándo es público este expediente»; el porqué vive en `audit_log`.
--
-- A diferencia de los radicados, el recorte NO incluye una condición de estado.
-- Un radicado anulado se retira de la circulación y por eso `status <> 'anulado'`
-- entra en su recorte; un expediente `closed` o `transferred` no está retirado —
-- está cerrado o transferido, que son estados normales de su ciclo de vida y en
-- los que la difusión sigue siendo legítima. Copiar la condición por simetría
-- habría despublicado en silencio todo expediente cerrado.

ALTER TABLE expedientes
    ADD COLUMN IF NOT EXISTS publicable    BOOLEAN NOT NULL DEFAULT FALSE,
    ADD COLUMN IF NOT EXISTS publicado_at  TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS publicado_por UUID;

COMMENT ON COLUMN expedientes.publicable IS
    'Esquema de publicación (Ley 1712/2014 art. 12): acto EXPLÍCITO por el que la '
    'entidad difunde el expediente de oficio (OAI-PMH EAD multinivel). FALSE por '
    'defecto — la ausencia de reserva no equivale a una decisión de publicar. '
    'Condición NECESARIA pero no suficiente: el recorte exige además '
    'nivel_seguridad = 1.';

-- Índice parcial alineado con el recorte público, como el de radicados: las
-- consultas de cosecha filtran siempre por este conjunto, que es una fracción
-- pequeña del total.
CREATE INDEX IF NOT EXISTS ix_expedientes_publicables
    ON expedientes (opened_at)
    WHERE publicable AND nivel_seguridad = 1;

-- >>> archive-service/tenant/043_expediente_search_unaccent.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- La búsqueda de expedientes deja de distinguir acentos (ADR-014).
--
-- `005_expediente_search.sql` decía «sin pg_trgm/unaccent para no depender de
-- extensiones». La razón no se sostiene: `document-service` instala las dos en
-- `public` (`global/001_extensions.sql`) sobre esta misma base de datos, así que
-- la dependencia ya existía y lo único que producía la decisión era que buscar
-- un expediente se comportara distinto que buscar un radicado — el mismo texto,
-- dos resultados diferentes según la pantalla. Eso es peor que depender de una
-- extensión: es que el sistema se contradiga a sí mismo.
--
-- La configuración `public.spanish_unaccent` la crea
-- `document-service/migrations/global/002_spanish_unaccent.sql`. El orden entre
-- servicios lo garantiza el runner de provisión (`scripts/init_tenant.py`), que
-- aplica las globales de document antes que las de tenant de archive; si aun así
-- faltara, esta migración falla en voz alta en vez de dejar el índice a medias.

DO $$
DECLARE
    v_expr text;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_ts_config c
          JOIN pg_namespace n ON n.oid = c.cfgnamespace
         WHERE c.cfgname = 'spanish_unaccent' AND n.nspname = 'public'
    ) THEN
        RAISE EXCEPTION
            'Falta la configuración public.spanish_unaccent (document-service/migrations/global/002)';
    END IF;

    SELECT pg_get_expr(d.adbin, d.adrelid)
      INTO v_expr
      FROM pg_attrdef d
      JOIN pg_attribute a ON a.attrelid = d.adrelid AND a.attnum = d.adnum
      JOIN pg_class c ON c.oid = d.adrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
     WHERE c.relname = 'expedientes'
       AND a.attname = 'search_vector'
       AND n.nspname = current_schema();

    IF v_expr IS NULL OR v_expr NOT LIKE '%spanish_unaccent%' THEN
        ALTER TABLE expedientes DROP COLUMN IF EXISTS search_vector;

        ALTER TABLE expedientes
            ADD COLUMN search_vector tsvector
            GENERATED ALWAYS AS (
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(code, '')), 'A') ||
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(name, '')), 'B') ||
                setweight(to_tsvector('public.spanish_unaccent'::regconfig, coalesce(description, '')), 'C')
            ) STORED;

        CREATE INDEX IF NOT EXISTS ix_expedientes_search
            ON expedientes USING GIN (search_vector);
    END IF;
END
$$;

-- >>> archive-service/tenant/044_tipo_documental_ventanilla_publica.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant: qué tipos documentales admite la VENTANILLA ÚNICA pública.
--
-- La radicación pública estaba cableada a la taxonomía de PQRS
-- (petición/queja/reclamo/sugerencia/denuncia) en un `Literal` de Python. Pero
-- una ventanilla única recibe TODA la correspondencia externa: tutelas, oficios
-- de otras entidades, facturas, invitaciones, hojas de vida. Fijar en código lo
-- que cada entidad recibe es decidir por ella.
--
-- El vocabulario sale del catálogo que la entidad ya mantiene y que **gobierna
-- la TRD**: así lo que entra por la ventanilla queda clasificado desde el minuto
-- uno y hereda su retención y su disposición final, en vez de entrar sin serie y
-- esperar a que alguien lo clasifique después (Ley 594/2000 arts. 21-24).
--
-- **Opt-in, no opt-out**: el default es FALSE. Un tipo documental interno
-- —«Acta de comité», «Memorando de sanción»— no debe aparecer en un formulario
-- público solo porque exista en el catálogo. Que la entidad declare qué recibe
-- del exterior es un acto suyo, y el silencio no puede significar «todo».

ALTER TABLE tipos_documentales
    ADD COLUMN IF NOT EXISTS admite_ventanilla_publica BOOLEAN NOT NULL DEFAULT false;

COMMENT ON COLUMN tipos_documentales.admite_ventanilla_publica IS
    'Si TRUE, este tipo se ofrece en la ventanilla única pública (radicación sin '
    'autenticar). Opt-in deliberado: el silencio no significa «todo».';

-- Índice parcial: la consulta pública pide siempre el mismo subconjunto y suele
-- ser una fracción pequeña del catálogo.
CREATE INDEX IF NOT EXISTS ix_tipos_documentales_ventanilla
    ON tipos_documentales (admite_ventanilla_publica)
    WHERE admite_ventanilla_publica;

-- >>> archive-service/tenant/045_marca_cierre_sin_calendario.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E04, RF-TRD-09, 2026-08-28): recoge los expedientes que
-- se cerraron SIN calendario de retención entre la migración 037 y hoy.
--
-- La 037 hizo exactamente este mismo UPDATE, y funcionó. Lo que no había era
-- nada que escribiera `cierre_sin_snapshot_de_retencion` en el camino normal
-- de cierre: el motivo existía en el modelo, la tercera pestaña de
-- `/admin/trd` sabía presentarlo y explicaba que no tiene resolución
-- automática, y **nunca le llegaba ninguno**. Así que cada expediente cerrado
-- sin serie desde entonces volvió a caer en el mismo agujero: `disposition`
-- NULL, sin marca, y por tanto fuera de toda cola — ni la de revisión, ni la
-- de vencimientos que vendrá después.
--
-- El código ya está corregido (`ArchiveService.close_expediente` marca, y
-- `transition_expediente` escribe las marcas al CERRAR en vez de solo cuando
-- fija el pin de la serie, que era justo el caso contrario). Esta migración
-- solo barre lo que se coló mientras tanto: **reparar el pasado y proteger el
-- futuro son dos actos distintos, y hacer solo uno de los dos ya salió caro**
-- una vez aquí.
--
-- Idempotente por el `AND NOT trd_revision_requerida`: reejecutarla no pisa
-- ninguna marca existente ni inventa ningún calendario (la 037 tampoco lo
-- hacía, y por el mismo motivo — un calendario no se deduce a posteriori: hay
-- que decidirlo clasificando el expediente).

UPDATE expedientes
   SET trd_revision_requerida = true,
       trd_revision_motivo    = 'cierre_sin_snapshot_de_retencion'
 WHERE status IN ('closed', 'transferred')
   AND disposition IS NULL
   AND NOT trd_revision_requerida;

-- >>> archive-service/tenant/046_disposicion_decisiones.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E04, RF-TRD-06/08, 2026-08-28): la DECISIÓN sobre un
-- vencimiento de disposición, APPEND-ONLY.
--
-- «Ninguna destrucción es automática sin confirmación de usuario autorizado»
-- (RF-TRD-08, regla de negocio 4 del RT 04). Esa confirmación es un ACTO, no
-- un estado que se pueda editar después: quien la firma responde de que la
-- disposición de la TRD procede sobre ESE expediente. Por eso la tabla es
-- append-only con el mismo trigger que `expediente_eventos`, y por eso la
-- decisión se guarda con el vencimiento CONGELADO sobre el que se decidió
-- (`fecha_vencimiento` + `disposition_code`): decidir «sobre el vencimiento
-- vigente» sería decidir sobre un blanco móvil, y una confirmación de 2026 no
-- puede autorizar la eliminación que una TRD reformulada ordene en 2030.
--
-- Dos decisiones posibles, las dos NO destructivas:
--   * `confirmada`: el usuario autorizado declara que procede la acción de la
--     TRD. NO elimina nada -- el brazo ejecutor (RF-TRD-07: borrado seguro con
--     acta, aval del Comité y publicidad previa del inventario) no existe
--     todavía. Es su precondición, no su disparo.
--   * `aplazada`: R.4.9 del Modelo SGDEA, «cancelar transferencia o
--     destrucción vencida». Exige motivo y una fecha para volver a mirarlo --
--     un aplazamiento sin fecha es un olvido con mejor nombre.

CREATE TABLE IF NOT EXISTS disposicion_decisiones (
    id                 UUID         NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
    expediente_id      UUID         NOT NULL REFERENCES expedientes(id),
    fase               TEXT         NOT NULL,
    decision           TEXT         NOT NULL,
    -- El vencimiento sobre el que se decidió, congelado (ver cabecera).
    fecha_vencimiento  DATE         NOT NULL,
    disposition_code   TEXT,
    -- Obligatorio al aplazar; opcional al confirmar (una confirmación puede
    -- remitir al acta del Comité que la respalda).
    motivo             TEXT,
    revisar_de_nuevo_el DATE,
    decidido_por       UUID         NOT NULL,
    decidido_at        TIMESTAMPTZ  NOT NULL DEFAULT now(),

    CONSTRAINT disposicion_decisiones_fase_check
        CHECK (fase IN ('gestion', 'central')),
    CONSTRAINT disposicion_decisiones_decision_check
        CHECK (decision IN ('confirmada', 'aplazada')),
    -- Un aplazamiento sin motivo y sin fecha de revisión no es una decisión,
    -- es dejar el expediente donde estaba y quitarlo de la vista.
    CONSTRAINT disposicion_decisiones_aplazada_forma_check
        CHECK (
            decision <> 'aplazada'
            OR (motivo IS NOT NULL AND length(btrim(motivo)) >= 10
                AND revisar_de_nuevo_el IS NOT NULL)
        )
);

CREATE INDEX IF NOT EXISTS ix_disposicion_decisiones_exp
    ON disposicion_decisiones (expediente_id, fase, fecha_vencimiento, decidido_at DESC);

-- Inmutabilidad: rechaza UPDATE y DELETE (append-only, Ley 594/2000) — mismo
-- criterio y misma forma que `expediente_eventos` (migración 014).
CREATE OR REPLACE FUNCTION reject_disposicion_decisiones_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'disposicion_decisiones is append-only (Ley 594/2000)';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_disposicion_decisiones_immutable ON disposicion_decisiones;
CREATE TRIGGER trg_disposicion_decisiones_immutable
    BEFORE UPDATE OR DELETE ON disposicion_decisiones
    FOR EACH ROW EXECUTE FUNCTION reject_disposicion_decisiones_mutation();

