-- DROP TRIGGER IF EXISTS trg_eliminacion_acta_append_only ON eliminacion_acta;
-- DROP FUNCTION IF EXISTS reject_eliminacion_acta_mutation();
-- DROP TABLE IF EXISTS eliminacion_acta;

