-- Tenant migration 053 (E12, AREA-07-04): el acta de recepción ata la FIRMA del índice.
-- search_path = tenant_{slug} (ADR-012).
--
-- `transferencia_acta.indice_version` (migración 022) pinneaba solo el NÚMERO de versión
-- del índice transferido. Una versión admite una sola firma hoy, pero un número no
-- identifica una firma: sin `indice_firma_id` el acta no dice CUÁL sello ampara el
-- índice que entregó, y un acta firmada que atestigua «versión 3» sin poder señalar
-- el sello es una referencia a medias. Se añaden el id de la firma y la huella del XML
-- que ese sello cubre (`expediente_indice.xml_sha256`).
--
-- Nullable A PROPÓSITO: las actas anteriores no lo tienen, y rellenarlas inventaría un
-- vínculo en un acta ya sellada (inmutable: trigger de la migración 023). Solo las
-- actas nuevas lo llevan; la respuesta de `GET /transferencias/{id}/acta` lo muestra
-- como `null` para las anteriores, sin ocultarlo.
--
-- Aditiva/idempotente: ADD COLUMN IF NOT EXISTS (un ADD COLUMN no dispara el trigger
-- de fila de la 023).

ALTER TABLE transferencia_acta
    ADD COLUMN IF NOT EXISTS indice_firma_id UUID;

ALTER TABLE transferencia_acta
    ADD COLUMN IF NOT EXISTS indice_sha256 TEXT;

COMMENT ON COLUMN transferencia_acta.indice_firma_id IS
    'expediente_indice.firma_id de la versión indice_version, leído en la MISMA tx de recepción que la fixity: el sello XAdES que ampara el índice entregado. NULL en las actas anteriores a la migración 053.';
COMMENT ON COLUMN transferencia_acta.indice_sha256 IS
    'expediente_indice.xml_sha256 de esa versión (huella C14N del XML que la firma cubre). NULL en las actas anteriores a la migración 053.';

-- Rollback manual (no automatizado):
-- ALTER TABLE transferencia_acta DROP COLUMN IF EXISTS indice_sha256;
-- ALTER TABLE transferencia_acta DROP COLUMN IF EXISTS indice_firma_id;

-- >>> archive-service/tenant/054_transferencia_acta_revoke.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 054 (E12, AREA-07-08): capa de PRIVILEGIOS sobre el acta de entrega.
-- search_path = tenant_{slug} (ADR-012).
--
-- La inmutabilidad de `transferencia_acta` (migración 023) descansaba SOLO en un trigger
-- (UPDATE/DELETE/TRUNCATE). Desde que el rol de la aplicación dejó de ser superusuario y
-- dueño (auth-service 008_rol_app_privilegios) no puede desactivar ese trigger, pero la
-- 008 le concede UPDATE y DELETE sobre TODAS las tablas del tenant, el acta incluida: la
-- única barrera era el trigger. Defensa en profundidad, la misma que ya tiene `audit_log`:
-- el rol de la app NO recibe UPDATE ni DELETE sobre el acta ni sobre las firmas
-- personales del acta (append-only, migración 027), de modo que la mutación falla por
-- privilegios ANTES de llegar al trigger.
--
-- Mismo guard de existencia de rol que la 008: sin `orpycamcp_app` (entornos donde la
-- aplicación se conecta como propietario, como la pila de desarrollo) no hay a quién
-- revocar y la migración no hace nada. Los privilegios por omisión de la 008 conceden
-- sobre las tablas NUEVAS; esto retira lo concedido sobre estas dos YA existentes.
--
-- Idempotente: REVOKE sobre un privilegio ausente no falla.

DO $$
DECLARE
    esquema TEXT := current_schema();
    tabla   TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'orpycamcp_app') THEN
        RAISE NOTICE 'orpycamcp_app no existe; nada que revocar sobre el acta.';
        RETURN;
    END IF;

    FOREACH tabla IN ARRAY ARRAY['transferencia_acta', 'transferencia_acta_firma_personal']
    LOOP
        IF to_regclass(format('%I.%I', esquema, tabla)) IS NOT NULL THEN
            EXECUTE format('REVOKE UPDATE, DELETE ON TABLE %I.%I FROM orpycamcp_app', esquema, tabla);
        END IF;
    END LOOP;
END;
$$;

-- Rollback manual (no automatizado):
-- GRANT UPDATE, DELETE ON TABLE transferencia_acta, transferencia_acta_firma_personal TO orpycamcp_app;

-- >>> archive-service/tenant/055_transferencia_objeto_check.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Tenant migration 055 (E12, AREA-07-09): `transferencias.objeto` obligatorio EN LA BASE.
-- search_path = tenant_{slug} (ADR-012).
--
-- La migración 052 dejó `objeto` sin NOT NULL porque las transferencias anteriores no lo
-- tienen y no hay valor honesto con el que rellenarlas; la obligatoriedad se aplicaba solo
-- en la ENTRADA (`TransferenciaCreate`). Cualquier INSERT que no pase por esa clase (un
-- script, otra ruta futura) podía crear una transferencia sin objeto, y el acta del Anexo
-- FUID saldría con la cabecera en blanco.
--
-- Un CHECK ... NOT VALID obliga a las filas NUEVAS sin tocar el histórico. Pero NOT VALID
-- también se evalúa en cada UPDATE de una fila existente, y `enviar`/`recibir`/`rechazar`
-- actualizan la fila: un `CHECK (objeto IS NOT NULL ...)` a secas dejaría SIN poder
-- avanzar a toda transferencia en curso anterior a la 052. Por eso la condición exime las
-- filas creadas antes de esta migración: el histórico queda intacto Y operable, y toda
-- fila posterior exige objeto.
--
-- Idempotente (guard acotado a `current_schema()`).

DO $$
BEGIN
    IF to_regclass(format('%I.transferencias', current_schema())) IS NULL THEN
        RETURN;
    END IF;
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint
         WHERE conname = 'ck_transferencias_objeto'
           AND conrelid = to_regclass(format('%I.transferencias', current_schema()))
    ) THEN
        ALTER TABLE transferencias
            ADD CONSTRAINT ck_transferencias_objeto
            CHECK (
                created_at < TIMESTAMPTZ '2026-10-03 00:00:00+00'
                OR (objeto IS NOT NULL AND length(btrim(objeto)) >= 3)
            ) NOT VALID;
    END IF;
END;
$$;

-- Rollback manual (no automatizado):
-- ALTER TABLE transferencias DROP CONSTRAINT IF EXISTS ck_transferencias_objeto;

