-- Migración de tenant 077 (D2). search_path = tenant_{slug}.
--
-- Plazo por defecto del tipo, en días hábiles. Lo pone la entidad: no es un
-- término legal escrito en el código. NULL significa que una Entrada de este
-- tipo nace sin vencimiento si quien radica no indica días.

ALTER TABLE tipos_documentales
    ADD COLUMN IF NOT EXISTS default_response_days INT NULL
        CHECK (default_response_days BETWEEN 1 AND 3650);

COMMENT ON COLUMN tipos_documentales.default_response_days IS
    'Días hábiles de plazo cuando una Entrada de este tipo llega sin response_days. '
    'NULL: no hay plazo por defecto. Lo configura la entidad.';

-- >>> signature-service/tenant/001_firmas.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06, ADR-016): firmas electrónicas (signature-service).
--
-- Registro de firma por tenant. El proveedor de firma es PLUGGABLE: el stub nativo
-- por defecto produce una firma electrónica (hash SHA-256 + identidad + sello), no
-- una firma digital PKI. Un proveedor XAdES/PAdES/TSA real se conecta sin cambiar
-- el contrato ni este esquema (se añade firma_blob/refrendo del proveedor).

CREATE TABLE IF NOT EXISTS firma (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    objeto_tipo        VARCHAR(40) NOT NULL,        -- indice | radicado | anexo | ...
    objeto_id          TEXT,
    formato_solicitado VARCHAR(20),                 -- XAdES | PAdES | hash-256
    firmante_id        UUID,
    payload_sha256     CHAR(64) NOT NULL,
    firma_blob         TEXT NOT NULL,
    provider           VARCHAR(30) NOT NULL,        -- nativa | xades | ...
    created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_firma_objeto ON firma (objeto_tipo, objeto_id);

-- >>> signature-service/tenant/002_firma_add_sello_tiempo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06, ADR-016, RF-FIR-12, D-01): agrega sello_tiempo y tipo_firma.
--
-- sello_tiempo: timestamp del servidor utilizado en el HMAC de la firma_blob.
--   Necesario para verificar firmas creadas con el proveedor nativa-v2
--   (HMAC-SHA256 con secret del servicio). Las filas anteriores reciben
--   DEFAULT now() en migración — sus firma_blob (SHA-256 sin secret) ya no
--   verifican con el nuevo algoritmo, lo cual es aceptable dado que eran
--   reproducibles por cualquier tercero (D-01, insecuras).
--
-- tipo_firma: clasifica la firma ('electronica-nativa' por defecto).

ALTER TABLE firma
    ADD COLUMN IF NOT EXISTS sello_tiempo TIMESTAMPTZ NOT NULL DEFAULT now(),
    ADD COLUMN IF NOT EXISTS tipo_firma   VARCHAR(30)  NOT NULL DEFAULT 'electronica-nativa';

COMMENT ON COLUMN firma.sello_tiempo IS
    'Timestamp del servidor incorporado en el HMAC (firma_blob). '
    'Requerido para re-verificar la firma. No debe ser provisto por el cliente.';

COMMENT ON COLUMN firma.tipo_firma IS
    'Tipo de firma: electronica-nativa | xades | pades. '
    'electronica-nativa = HMAC-SHA256 con secreto de servicio (RF-FIR-12).';

-- >>> signature-service/tenant/003_firma_cadena.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06, ADR-016): cadena de firma secuencial.
--
-- Modelo:
--   firma_solicitud  — cabecera de la cadena (un objeto puede tener una sola cadena abierta)
--   firma_cadena     — turnos ordenados; cada turno apunta a una fila en `firma` al resolverse
--
-- Restricción de negocio: solo una cadena abierta por objeto (índice parcial WHERE estado='pendiente').
-- Un rechazo detiene la cadena completa (firma_solicitud.estado='rechazado').
--
-- Rollback:
--   DROP TABLE IF EXISTS firma_cadena;
--   DROP TABLE IF EXISTS firma_solicitud;

CREATE TABLE IF NOT EXISTS firma_solicitud (
    id             UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    objeto_tipo    VARCHAR(40)  NOT NULL,    -- radicado | indice | anexo | documento
    objeto_id      TEXT         NOT NULL,
    titulo         TEXT,                     -- etiqueta para la bandeja (asunto / nº radicado)
    payload_sha256 CHAR(64),                 -- huella del documento a firmar (vínculo firmante↔documento)
    estado         VARCHAR(20)  NOT NULL DEFAULT 'pendiente'
                   CHECK (estado IN ('pendiente', 'firmado', 'rechazado')),
    creado_por     UUID,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Solo puede existir una cadena abierta por objeto (idempotencia de solicitudes).
CREATE UNIQUE INDEX IF NOT EXISTS ux_firma_solicitud_objeto_abierta
    ON firma_solicitud (objeto_tipo, objeto_id)
    WHERE estado = 'pendiente';

COMMENT ON TABLE firma_solicitud IS
    'Cabecera de una cadena de firma sobre un objeto documental (E06, ADR-016). '
    'Un solo objeto puede tener una cadena abierta simultáneamente.';

COMMENT ON COLUMN firma_solicitud.payload_sha256 IS
    'SHA-256 del documento que se firma. Vincula cada turno al contenido exacto. '
    'Nunca es NULL para borrador/documento desde E23 (RF-PRO-09): sin huella la '
    'firma recaeria sobre el NOMBRE del objeto y sobreviviria al cambio del texto. '
    'De donde sale, que no es lo mismo en los dos casos: para objeto_tipo '
    'documento es OBLIGATORIO en el cuerpo de la peticion, porque no hay '
    'productor a quien preguntarle; para borrador la '
    'resuelve el SERVIDOR contra document-service y la del cuerpo se ignora '
    '(fuente autoritativa, ver CADENA_PAYLOAD_AUTORITATIVO) — una huella que el '
    'llamante elige no vincula a nadie. Los demas tipos aun admiten NULL.';

-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS firma_cadena (
    id            UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    solicitud_id  UUID         NOT NULL REFERENCES firma_solicitud(id) ON DELETE CASCADE,
    orden         INT          NOT NULL,
    firmante_id   UUID         NOT NULL,
    estado        VARCHAR(20)  NOT NULL DEFAULT 'pendiente'
                  CHECK (estado IN ('pendiente', 'firmado', 'rechazado')),
    firma_id      UUID,                     -- FK lógica a firma(id); se rellena al firmar
    comentario    TEXT,                     -- motivo de rechazo / nota del firmante
    decidido_at   TIMESTAMPTZ,
    UNIQUE (solicitud_id, orden)
);

-- Bandeja del firmante: turno activo por firmante.
CREATE INDEX IF NOT EXISTS ix_firma_cadena_pendiente
    ON firma_cadena (firmante_id, estado);

-- Consulta de turnos de una solicitud.
CREATE INDEX IF NOT EXISTS ix_firma_cadena_solicitud
    ON firma_cadena (solicitud_id);

COMMENT ON TABLE firma_cadena IS
    'Turno de firma dentro de una cadena (firma_solicitud). '
    'El turno activo es el de menor orden con estado=''pendiente''.';

COMMENT ON COLUMN firma_cadena.firma_id IS
    'UUID de la fila en firma(id) producida al resolver este turno. '
    'FK lógica (no enforced); queda NULL hasta que el firmante actúa.';

-- >>> signature-service/tenant/004_firma_solicitud_nivel.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (RF-SEG-08, D-15): snapshot de nivel de seguridad en cadena de firma.
--
-- Añade nivel_seguridad a firma_solicitud como snapshot capturado una única vez al
-- crear la cadena desde el objeto firmado (radicado u otro). Persistir el nivel evita
-- acoplar cada consulta de firma al servicio de documentos y permite gatear directamente
-- contra el clearance del actor (RF-SEG-08, no-read-up) sin join inter-servicio.
--
-- Niveles: 1=PUBLICA (default para filas existentes), 2=RESERVADA, 3=CLASIFICADA.
--
-- Rollback:
--   ALTER TABLE firma_solicitud DROP COLUMN IF EXISTS nivel_seguridad;

ALTER TABLE firma_solicitud
    ADD COLUMN IF NOT EXISTS nivel_seguridad SMALLINT NOT NULL DEFAULT 1
    CHECK (nivel_seguridad BETWEEN 1 AND 3);

COMMENT ON COLUMN firma_solicitud.nivel_seguridad IS
    'Snapshot del nivel de seguridad (1=PUBLICA, 2=RESERVADA, 3=CLASIFICADA) del objeto firmado. '
    'Se captura al crear la cadena desde radicados.nivel_seguridad (o declarado para otros tipos). '
    'Todas las lecturas se gatean contra el clearance del actor (RF-SEG-08, D-15, no-read-up).';

-- >>> signature-service/tenant/005_evento_dead_letter.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (R-4, ADR-021): tabla durable de dead-letter de eventos.
--
-- Almacena los eventos que alcanzaron el umbral de reintentos sin poder procesarse.
-- El INSERT usa ON CONFLICT (event_id) DO NOTHING para garantizar idempotencia: un
-- reintento del mismo mensaje (XADD ok pero XACK falló, at-least-once) no produce
-- duplicados ni dobles trazas en audit_log.
--
-- El stream Redis orpycamcp.signature.deadletter conserva su rol de buffer operativo
-- para inspección y replay; esta tabla es la copia autoritativa y durable (Postgres)
-- que satisface Ley 594/2000 art. 4 y art. 19 (trazabilidad, integridad, durabilidad).
--
-- Rollback:
--   DROP TABLE IF EXISTS evento_dead_letter;
--   DROP INDEX IF EXISTS ix_evento_dead_letter_at;

CREATE TABLE IF NOT EXISTS evento_dead_letter (
    event_id          TEXT        PRIMARY KEY,           -- ID único del sobre de evento (idempotencia)
    event_type        TEXT,
    correlation_id    TEXT,
    tenant_slug       TEXT        NOT NULL,
    payload           JSONB       NOT NULL,              -- sobre íntegro (incl. payload de negocio)
    failure           JSONB       NOT NULL,              -- failure_meta: reason, last_error, counts, etc.
    origin_stream     TEXT,
    origin_group      TEXT,
    dead_lettered_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE evento_dead_letter IS
    'Copia durable (Postgres) de los eventos aparcados en el dead-letter de Redis. '
    'event_id como PK garantiza idempotencia (ON CONFLICT DO NOTHING). '
    'El INSERT y el audit_log se escriben en la misma transacción (R-4, ADR-021): '
    'no hay dead-letter sin traza durable.';

COMMENT ON COLUMN evento_dead_letter.payload IS
    'Sobre íntegro del evento (event_id, event_type, tenant_slug, occurred_at, actor, '
    'payload de negocio). Autosuficiente para reconstrucción forense (Ley 594/2000 art. 19).';

COMMENT ON COLUMN evento_dead_letter.failure IS
    'failure_meta del helper reclaim_stale: dead_letter_reason, dead_letter_last_error, '
    'dead_letter_delivery_count, dead_lettered_at, origin stream/group/consumer.';

-- Índice por dead_lettered_at para consultas de inspección y TTL operativo.
CREATE INDEX IF NOT EXISTS ix_evento_dead_letter_at
    ON evento_dead_letter (dead_lettered_at);

-- >>> signature-service/tenant/006_deadletter_status.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-021 Fase 5): ciclo de vida de evento_dead_letter.
--
-- Añade el estado del dead-letter para habilitar inspección y replay/discard:
--   pending   → recién aparcado, sin resolver (estado inicial por defecto)
--   resolved  → reprocesado con éxito por un admin (replay)
--   discarded → descartado deliberadamente por un admin (con motivo)
--
-- Idempotente: PG15 no soporta ADD COLUMN IF NOT EXISTS, por lo que se usa el
-- patrón DO $$ … information_schema.columns … $$ para no fallar en re-ejecución.
--
-- Rollback:
--   ALTER TABLE evento_dead_letter DROP COLUMN IF EXISTS status;
--   ALTER TABLE evento_dead_letter DROP COLUMN IF EXISTS resolved_at;
--   DROP INDEX IF EXISTS ix_edl_pending;
--   DROP INDEX IF EXISTS ix_edl_resolved;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'evento_dead_letter' AND column_name = 'status'
    ) THEN
        ALTER TABLE evento_dead_letter
            ADD COLUMN status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'resolved', 'discarded'));
    END IF;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'evento_dead_letter' AND column_name = 'resolved_at'
    ) THEN
        ALTER TABLE evento_dead_letter
            ADD COLUMN resolved_at TIMESTAMPTZ NULL;
    END IF;
END $$;

-- Índice parcial para la bandeja de pendientes (consulta más frecuente).
CREATE INDEX IF NOT EXISTS ix_edl_pending
    ON evento_dead_letter (dead_lettered_at)
    WHERE status = 'pending';

-- Índice parcial para auditoría/retención de cerrados (resolved/discarded).
CREATE INDEX IF NOT EXISTS ix_edl_resolved
    ON evento_dead_letter (resolved_at)
    WHERE status IN ('resolved', 'discarded');

COMMENT ON COLUMN evento_dead_letter.status IS
    'Ciclo de vida del dead-letter: pending (inicial) → resolved (replay OK) | '
    'discarded (descarte deliberado con motivo). ADR-021 Fase 5.';
COMMENT ON COLUMN evento_dead_letter.resolved_at IS
    'Momento de la transición a resolved/discarded (NULL mientras pending).';

-- >>> signature-service/tenant/007_deadletter_origin_group_notnull_index.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (ADR-021, seguimiento no-bloqueante Fase 5):
--   origin_group NOT NULL + índice compuesto sobre la tabla COMPARTIDA evento_dead_letter.
-- SEGURA por diseño: origin_group nunca se inserta NULL (reclaim_stale en
--   orpycamcp_common.events siempre escribe dead_letter_group=GROUP y los 3 workers
--   pasan origin_group=failure_meta["dead_letter_group"]). Ver ADR-021 §D.
-- Guard defensivo: además, se sanea cualquier fila legada con origin_group NULL antes
--   del SET NOT NULL para no abortar la migración en un entorno ya desplegado (en dev es
--   no-op). El sentinel 'unknown' es invisible a TODAS las queries por-servicio
--   (ningún servicio consulta ese origin_group) → la fila queda fail-closed, sin
--   mis-atribución a signature/workflow/notification.
-- IDEMPOTENTE y sin pisarse entre los 3 servicios: actúan sobre la MISMA tabla física;
--   SET NOT NULL es no-op si ya es NOT NULL (PG15) y CREATE INDEX IF NOT EXISTS
--   lo crea el primero que corra, los demás no-op. El nombre del índice es ÚNICO y
--   compartido: ix_edl_tenant_group_status (NO usar nombres por-servicio).
--
-- Rollback:
--   DROP INDEX IF EXISTS ix_edl_tenant_group_status;
--   ALTER TABLE evento_dead_letter ALTER COLUMN origin_group DROP NOT NULL;

UPDATE evento_dead_letter SET origin_group = 'unknown' WHERE origin_group IS NULL;

ALTER TABLE evento_dead_letter
    ALTER COLUMN origin_group SET NOT NULL;

CREATE INDEX IF NOT EXISTS ix_edl_tenant_group_status
    ON evento_dead_letter (tenant_slug, origin_group, status);

-- Nota índice: orden (tenant_slug, origin_group, status) cubre el predicado de
-- list_pending/list_scoped_for_clearance (WHERE tenant_slug=$1 AND status=$2 AND
-- origin_group=$3, todas igualdades); el orden de columnas del índice es
-- independiente del orden en el WHERE.

-- >>> signature-service/tenant/008_firma_xades.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06, ADR-016, Inc.1): columnas XAdES-B en `firma`.
--
-- Aditiva e idempotente (ADD COLUMN IF NOT EXISTS): las firmas 'nativa' ya
-- persistidas quedan intactas, con estas columnas nuevas en NULL. `tipo_firma`
-- ya existía desde la migración 002 (VARCHAR(30) DEFAULT 'electronica-nativa')
-- — IF NOT EXISTS la deja sin tocar; el Incremento 1 fija explícitamente
-- 'nativa'/'sello_sistema' en cada INSERT nuevo (ver FirmaRepository.insert),
-- así que el DEFAULT histórico de columna deja de ser relevante hacia adelante.
--
-- Rollback:
--   ALTER TABLE firma
--       DROP COLUMN IF EXISTS certificado_pem,
--       DROP COLUMN IF EXISTS minio_key_firmado,
--       DROP COLUMN IF EXISTS nivel_conformidad,
--       DROP COLUMN IF EXISTS xades_level,
--       DROP COLUMN IF EXISTS certificado_fingerprint;
--   ALTER TABLE firma DROP CONSTRAINT IF EXISTS firma_nivel_conformidad_check;
--   ALTER TABLE firma DROP CONSTRAINT IF EXISTS firma_xades_level_check;

ALTER TABLE firma
    ADD COLUMN IF NOT EXISTS certificado_pem         TEXT,
    ADD COLUMN IF NOT EXISTS minio_key_firmado        TEXT,
    ADD COLUMN IF NOT EXISTS nivel_conformidad         TEXT,
    ADD COLUMN IF NOT EXISTS xades_level               TEXT,
    ADD COLUMN IF NOT EXISTS tipo_firma                TEXT DEFAULT 'nativa',
    ADD COLUMN IF NOT EXISTS certificado_fingerprint    TEXT;

-- CHECK laxo (admite NULL — filas históricas y firmas 'nativa' sin estos
-- campos). No hay "ADD CONSTRAINT IF NOT EXISTS" en Postgres para CHECK, así
-- que se envuelve en un DO block idempotente (re-ejecutar el archivo no falla
-- con "constraint already exists").
-- Los guards DEBEN acotarse al schema activo (`n.nspname = current_schema()`): en
-- el modelo multi-tenant-por-schema `pg_constraint.conname` se REPITE entre tenants
-- (cada `tenant_<slug>.firma` tiene sus propias constraints). Un guard por `conname`
-- global vería la constraint de OTRO tenant y la omitiría en éste ⇒ los tenants #2+
-- quedaban sin el CHECK. Reparación de tenants ya provisionados: 015_*_backfill.sql.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint c
          JOIN pg_class t ON t.oid = c.conrelid
          JOIN pg_namespace n ON n.oid = t.relnamespace
         WHERE c.conname = 'firma_nivel_conformidad_check'
           AND n.nspname = current_schema()
    ) THEN
        ALTER TABLE firma
            ADD CONSTRAINT firma_nivel_conformidad_check
            CHECK (nivel_conformidad IS NULL OR nivel_conformidad IN (
                'firma_electronica_nativa',
                'xades_b_no_acreditado',
                'xades_b_acreditado'  -- reservado: sin CA acreditada ONAC integrada (Inc.1)
            ));
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint c
          JOIN pg_class t ON t.oid = c.conrelid
          JOIN pg_namespace n ON n.oid = t.relnamespace
         WHERE c.conname = 'firma_xades_level_check'
           AND n.nspname = current_schema()
    ) THEN
        ALTER TABLE firma
            ADD CONSTRAINT firma_xades_level_check
            CHECK (xades_level IS NULL OR xades_level IN (
                'XAdES-B',
                'XAdES-T',    -- reservado: TSA/RFC 3161, no implementado
                'XAdES-LT',   -- reservado: material de validación a largo plazo
                'XAdES-LTA'   -- reservado: archivado a largo plazo, requiere CRL/OCSP
            ));
    END IF;
END $$;

COMMENT ON COLUMN firma.certificado_pem IS
    'Certificado X.509 PÚBLICO (PEM) del sello institucional usado para firmar. '
    'NUNCA la clave privada — esa nunca se persiste ni se loguea (RT-16).';

COMMENT ON COLUMN firma.minio_key_firmado IS
    'object_key en MinIO (storage-service, bucket orpycamcp-{slug}-documents) '
    'del XML COMPLETO ya firmado (XAdES-B). NULL para firmas nativa (el HMAC '
    'no se incrusta en un documento separado).';

COMMENT ON COLUMN firma.nivel_conformidad IS
    'Grado de conformidad declarado del material de firma (RF-FIR-15: nunca '
    'sobre-declarar). Distinto de nivel_seguridad (clearance RF-SEG-08, '
    'migración 004) — NO reusar ese concepto. '
    '''xades_b_acreditado'' queda reservado sin productor en el Incremento 1: '
    'no hay integración con una CA acreditada ONAC.';

COMMENT ON COLUMN firma.xades_level IS
    'Nivel XAdES del formato de firma (''XAdES-B'' en el Incremento 1). NULL '
    'para firmas nativa (HMAC, sin XML-DSig). T/LT/LTA reservados — ver '
    'app.providers.base.SignatureFormat.';

COMMENT ON COLUMN firma.tipo_firma IS
    'Tipo de acto de firma: ''nativa'' (HMAC de servicio) | ''sello_sistema'' '
    '(XAdES-B con el sello institucional del tenant, atribuido a la persona '
    'que actúa vía firmante_id + audit_log, RF-FIR-11). No confundir con '
    'provider (columna existente, identifica la IMPLEMENTACIÓN pluggable).';

COMMENT ON COLUMN firma.certificado_fingerprint IS
    'Huella SHA-256 (hex) del certificado usado para firmar, capturada al '
    'momento de la firma. Fuente de verdad para /verify al cotejar el '
    'certificado embebido en una firma XAdES — no depende de releer el sello '
    'actual del tenant (que pudo rotar desde entonces).';

-- >>> signature-service/tenant/009_signer_provider_config.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06, ADR-016, Inc.1 — recomendada, no crítica):
-- bookkeeping del sello institucional activo por tenant.
--
-- NO guarda clave ni certificado privado/completo — solo metadatos de
-- observabilidad (qué huella de certificado está en uso, si se reporta como
-- acreditado). Se actualiza (upsert) cada vez que /sign-xml firma con
-- xades_local, a título informativo: NO es la fuente de verdad de qué
-- certificado firmó una firma concreta (eso vive en firma.certificado_fingerprint,
-- migración 008, inmutable por fila) — esta tabla solo refleja el sello
-- VIGENTE al momento de la última firma, útil para un panel de administración
-- futuro ("¿qué sello está activo en este tenant ahora mismo?").
--
-- Rollback:
--   DROP TABLE IF EXISTS signer_provider_config;

CREATE TABLE IF NOT EXISTS signer_provider_config (
    tenant_id       TEXT PRIMARY KEY,
    provider        TEXT NOT NULL DEFAULT 'xades_local',
    cert_fingerprint TEXT,
    acreditado      BOOLEAN NOT NULL DEFAULT false,
    actualizado_ts  TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE signer_provider_config IS
    'Bookkeeping informativo del sello institucional activo por tenant (Inc.1, '
    'recomendado). NO custodia clave ni certificado — solo su huella. Se '
    'actualiza en cada firma xades_local exitosa; no es la fuente de verdad '
    'histórica (esa es firma.certificado_fingerprint por fila, migración 008).';

COMMENT ON COLUMN signer_provider_config.tenant_id IS
    'Slug del tenant (mismo valor que X-Tenant-Slug). Fila única por tenant: '
    'aunque el schema ya aísla por tenant, se guarda explícito para que el '
    'valor sea auto-descriptivo si la fila se exporta o audita fuera de contexto.';

-- >>> signature-service/tenant/010_firma_signed_xml_sha256.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06, ADR-016, Inc.1 — hallazgo de auditoría Media):
-- ata `POST /signature/verify` a la firma_id concreta que se está verificando.
--
-- Antes de esta columna, /verify solo cotejaba la huella del certificado
-- embebido contra `certificado_fingerprint` (columna 008): un `signed_xml` de
-- OTRO índice firmado con el MISMO sello institucional del tenant devolvía
-- `valida=True` para cualquier `firma_id` de ese tenant (el endpoint es
-- público y no ata el documento verificado al acto de firma concreto).
--
-- `signed_xml_sha256` persiste la huella SHA-256 del XML YA FIRMADO
-- (`SignedDoc.signed_xml`, tal como se sube a MinIO) en el momento de
-- `/sign-xml`; `/verify` la recalcula sobre el `payload_xml` recibido ANTES
-- de parsear/verificar criptográficamente — un mismatch se rechaza sin
-- siquiera intentar la verificación XAdES (fail-closed, y de paso evita
-- gastar CPU parseando un documento que no corresponde a esta firma_id).
--
-- Aditiva e idempotente: NULL para filas 'nativa' (no aplica, el HMAC no
-- envuelve un XML firmado separado) y para firmas 'xades_local' anteriores a
-- esta migración (compatibilidad retro — /verify degrada a solo huella de
-- certificado para esas filas, igual que antes).
--
-- Rollback:
--   ALTER TABLE firma DROP COLUMN IF EXISTS signed_xml_sha256;

ALTER TABLE firma
    ADD COLUMN IF NOT EXISTS signed_xml_sha256 TEXT;

COMMENT ON COLUMN firma.signed_xml_sha256 IS
    'SHA-256 (hex) del XML YA FIRMADO (SignedDoc.signed_xml) persistido al '
    'momento de /sign-xml para provider=''xades_local''. /verify lo recalcula '
    'sobre el payload_xml recibido para atar la verificación a ESTA firma_id '
    'concreta (evita que el signed_xml de otro índice, firmado con el mismo '
    'sello del tenant, se reporte como válido para un firma_id ajeno). NULL '
    'para firmas ''nativa'' o filas anteriores a esta migración.';

-- >>> signature-service/tenant/011_firma_challenge.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06 Incremento 2, RF-FIR-13): 2FA por OTP-correo en la
-- firma personal de la cadena de firma secuencial.
--
-- `firma_challenge` es el análogo, para el segundo factor, de lo que
-- `firma_solicitud`/`firma_cadena` son para la cadena misma (003): una fila
-- por cada código de un solo uso emitido para un turno concreto de firma.
--
-- INVARIANTE RECTOR: el OTP en claro NUNCA se persiste — solo `otp_hash`
-- (HMAC-SHA256 con `settings.signature_secret`, el mismo secreto de servicio
-- que ya protege la firma nativa en `signer.py`, D-01).
--
-- `hash_documento` ata el challenge al `payload_sha256` de la solicitud en el
-- momento de emitirlo (RF-FIR-13, Q1): un challenge nunca es válido para un
-- documento distinto de aquel para el que se emitió, aunque comparta
-- `solicitud_id` (protección cross-documento).
--
-- Solo puede existir UN challenge activo (`pendiente`|`verificado`) por
-- combinación (`solicitud_id`, `firmante_id`, `hash_documento`) — el índice
-- único parcial `uq_firma_challenge_activo` es la misma técnica que
-- `ux_firma_solicitud_objeto_abierta` (003): reemplazo idempotente, nunca dos
-- challenges vivos compitiendo por el mismo acto de firma.
--
-- Rollback:
--   DROP TABLE IF EXISTS firma_challenge;

CREATE TABLE IF NOT EXISTS firma_challenge (
    challenge_id   UUID         PRIMARY KEY DEFAULT gen_random_uuid(),
    solicitud_id   UUID         NOT NULL,
    firmante_id    UUID         NOT NULL,
    hash_documento CHAR(64)     NOT NULL,
    factor_tipo    TEXT         NOT NULL DEFAULT 'otp_email'
                   CHECK (factor_tipo IN ('otp_email')),
    otp_hash       TEXT         NOT NULL,
    estado         TEXT         NOT NULL DEFAULT 'pendiente'
                   CHECK (estado IN ('pendiente', 'verificado', 'consumido', 'expirado', 'bloqueado')),
    intentos       INT          NOT NULL DEFAULT 0,
    max_intentos   INT          NOT NULL,
    expira_at      TIMESTAMPTZ  NOT NULL,
    verificado_at  TIMESTAMPTZ,
    consumido_at   TIMESTAMPTZ,
    creado_at      TIMESTAMPTZ  NOT NULL DEFAULT now(),
    canal_masked   TEXT         NOT NULL,
    tenant_slug    TEXT         NOT NULL
);

-- Un solo challenge vivo por (solicitud, firmante, documento) — la emisión de
-- uno nuevo primero expira el anterior (reemplazo idempotente, ver Q1/Q2 del
-- contrato E06 Inc.2) para nunca violar este índice.
CREATE UNIQUE INDEX IF NOT EXISTS uq_firma_challenge_activo
    ON firma_challenge (solicitud_id, firmante_id, hash_documento)
    WHERE estado IN ('pendiente', 'verificado');

-- Barrido/expiración operativa por estado + vencimiento (uso futuro: job de
-- limpieza análogo a app/jobs/deadletter_retention.py; no forma parte de este
-- incremento, pero el índice ya deja el acceso listo).
CREATE INDEX IF NOT EXISTS ix_firma_challenge_expira
    ON firma_challenge (estado, expira_at);

COMMENT ON TABLE firma_challenge IS
    'Segundo factor (OTP por correo, RF-FIR-13) para la firma personal de un '
    'turno de firma_cadena. El OTP en claro NUNCA se persiste — solo su HMAC '
    '(otp_hash). Un challenge se emite atado a un hash_documento concreto y se '
    'consume atómicamente junto con el marcado del turno (anti-replay).';

COMMENT ON COLUMN firma_challenge.solicitud_id IS
    'FK lógica a firma_solicitud.id (no enforced — mismo patrón que firma_cadena.firma_id).';

COMMENT ON COLUMN firma_challenge.firmante_id IS
    'Debe coincidir con firma_cadena.firmante_id del turno activo en el momento '
    'de emitir el challenge (RF-FIR-11) — el emisor solo puede ser el propio firmante.';

COMMENT ON COLUMN firma_challenge.hash_documento IS
    'Snapshot de firma_solicitud.payload_sha256 al emitir el challenge. Ata el '
    'segundo factor al documento exacto (protección cross-documento, RF-FIR-13).';

COMMENT ON COLUMN firma_challenge.otp_hash IS
    'HMAC-SHA256(otp, signature_secret). El OTP en claro NUNCA se persiste, ni '
    'se loguea, ni se registra en audit_log/Redis, ni se devuelve en respuesta alguna.';

COMMENT ON COLUMN firma_challenge.estado IS
    'pendiente: emitido, esperando OTP. verificado: reservado para un futuro '
    'flujo de verificación desacoplada del acto de firma (no usado en Inc.2 — '
    '/sign verifica y consume en un solo paso). consumido: OTP correcto y ya '
    'aplicado a una firma (terminal, anti-replay). expirado: venció expira_at '
    'sin verificarse. bloqueado: agotó max_intentos.';

COMMENT ON COLUMN firma_challenge.intentos IS
    'Contador de verificaciones fallidas. Se incrementa y persiste de forma '
    'durable aunque el intento de firma se aborte (RF-FIR-13) — nunca se '
    'pierde con un rollback del acto de firma que lo originó.';

COMMENT ON COLUMN firma_challenge.max_intentos IS
    'Snapshot de settings.otp_max_intentos al emitir el challenge (cambios de '
    'configuración posteriores no alteran challenges ya emitidos).';

COMMENT ON COLUMN firma_challenge.canal_masked IS
    'Canal de entrega enmascarado para exhibición segura (p.ej. j***@dominio.gov.co). '
    'NUNCA el email completo en claro en esta columna.';

COMMENT ON COLUMN firma_challenge.tenant_slug IS
    'Slug del tenant al momento de emitir el challenge — trazabilidad explícita '
    'en la fila (redundante con el search_path del schema, igual que otras '
    'tablas de auditoría del proyecto).';

-- >>> signature-service/tenant/012_firma_xades_t_tsa.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
