-- Migración de tenant (E06, RF-FIR-15): material OCSP stapled en `firma`.
--
-- Aditiva e idempotente (ADD COLUMN IF NOT EXISTS): las firmas 'nativa', las
-- XAdES-B/-T y las XAdES-LT/LTA sin OCSP (kill-switch
-- signer_ocsp_enabled=False, o tenant sin ocsp.crt/ocsp.key montado) quedan
-- intactas, con estas columnas nuevas en NULL/DEFAULT. NO se toca el CHECK
-- de `firma.nivel_conformidad` (migración 013) ni `firma.xades_level` — OCSP
-- es ADITIVO a XAdES-LT/LTA, nunca un nivel de conformidad nuevo. El XML
-- firmado en MinIO (`minio_key_firmado`) sigue siendo la fuente de verdad
-- para xades:OCSPValues — estas columnas son para queryabilidad/auditoría
-- (mismo patrón que la migración 013), nunca autoridad.
--
-- PROHIBIDO: ninguna columna de esta migración persiste material PRIVADO
-- (ni la clave del responder OCSP ni ninguna otra) — solo la respuesta OCSP
-- PÚBLICA (BasicOCSPResponse DER), huellas y metadatos de fechas (RT-16,
-- línea roja del incremento — misma regla no-fuga que `seal.key`).
--
-- Rollback:
--   ALTER TABLE firma
--       DROP COLUMN IF EXISTS ocsp_present,
--       DROP COLUMN IF EXISTS ocsp_responder_fingerprint,
--       DROP COLUMN IF EXISTS ocsp_cert_status,
--       DROP COLUMN IF EXISTS ocsp_produced_at,
--       DROP COLUMN IF EXISTS ocsp_this_update,
--       DROP COLUMN IF EXISTS ocsp_next_update,
--       DROP COLUMN IF EXISTS ocsp_response_der;

ALTER TABLE firma
    ADD COLUMN IF NOT EXISTS ocsp_present               BOOLEAN NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS ocsp_responder_fingerprint  TEXT,
    ADD COLUMN IF NOT EXISTS ocsp_cert_status            TEXT,
    ADD COLUMN IF NOT EXISTS ocsp_produced_at            TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS ocsp_this_update            TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS ocsp_next_update            TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS ocsp_response_der           TEXT;

COMMENT ON COLUMN firma.ocsp_present IS
    'True cuando la firma incluye xades:RevocationValues/xades:OCSPValues '
    '(OCSP stapled, responder delegado emitido por la CA local de '
    'DESARROLLO, scripts/gen-dev-ocsp-responder.sh) — siempre false para '
    'firmas nativa/XAdES-B/XAdES-T/XAdES-LT/XAdES-LTA sin OCSP o cuando '
    'settings.signer_ocsp_enabled=false / el tenant no tiene '
    'ocsp.crt/ocsp.key montado junto a su sello (degradación observable, '
    'ver firma.ocsp_downgrade_no_responder en audit_log).';

COMMENT ON COLUMN firma.ocsp_responder_fingerprint IS
    'Huella SHA-256 (hex) del certificado del responder OCSP embebido en '
    'xades:OCSPValues al momento de firmar — ancla de confianza persistida '
    'para /verify (mismo patrón de pinning que firma.tsa_cert_fingerprint '
    'migración 012 y firma.ca_fingerprint migración 013): sin cotejar '
    'contra este valor, cualquiera podría anexar una respuesta OCSP firmada '
    'con su propio responder.';

COMMENT ON COLUMN firma.ocsp_cert_status IS
    'certStatus declarado por la respuesta OCSP al momento de firmar '
    '(''good''|''revoked''), derivado de la MISMA CRL embebida en '
    'xades:CRLValues — coherencia CRL<->OCSP, nunca dos fuentes de verdad '
    'de revocación divergentes dentro del mismo acto de firma.';

COMMENT ON COLUMN firma.ocsp_produced_at IS
    'producedAt declarado por la BasicOCSPResponse al momento de firmar.';

COMMENT ON COLUMN firma.ocsp_this_update IS
    'thisUpdate declarado por la respuesta OCSP al momento de firmar.';

COMMENT ON COLUMN firma.ocsp_next_update IS
    'nextUpdate declarado por la respuesta OCSP al momento de firmar '
    '(settings.signer_ocsp_validity_days desde thisUpdate) — un vencimiento '
    'NO invalida por sí solo una verificación posterior en este perfil no '
    'acreditado (se expone para diagnóstico, mismo criterio que '
    'firma.crl_next_update).';

COMMENT ON COLUMN firma.ocsp_response_der IS
    'BasicOCSPResponse (RFC 6960, DER en base64) — material PÚBLICO (igual '
    'que firma.tsa_token/archive_timestamp_token), persistido por '
    'conveniencia de consulta; la autoridad es el XML firmado en MinIO. '
    'NULL si ocsp_present=false. NUNCA la clave privada del responder OCSP '
    '(RT-16, misma regla no-fuga que seal.key).';

-- >>> signature-service/tenant/015_firma_checks_backfill.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Backfill de los CHECK de `firma` (`firma_nivel_conformidad_check`,
-- `firma_xades_level_check`, E06) en los tenants ya provisionados que los PERDIERON
-- por el bug de idempotencia de 008_firma_xades.sql (guard por `conname` global,
-- sin filtrar por schema: `conname` se repite entre tenants, así que el guard veía
-- la constraint de otro tenant y la omitía ⇒ tenants #2+ sin el CHECK).
--
-- 008 ya está corregida en su sitio (para provisiones frescas), pero el runner
-- registra las migraciones por `(schema, filename)` y no re-aplica 008 a un tenant
-- que ya la tiene marcada — de ahí esta reparación, aplicada a TODOS los tenants
-- (los que ya tienen las constraints las ven presentes y no hacen nada). Acotada al
-- schema activo con `current_schema()`. Si un tenant tuviera filas fuera de dominio,
-- el ADD CONSTRAINT falla ruidoso — correcto (no enmascarar datos corruptos).

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint c
          JOIN pg_class t ON t.oid = c.conrelid
          JOIN pg_namespace n ON n.oid = t.relnamespace
         WHERE c.conname = 'firma_nivel_conformidad_check'
           AND n.nspname = current_schema()
    ) THEN
        ALTER TABLE firma
            ADD CONSTRAINT firma_nivel_conformidad_check
            CHECK (nivel_conformidad IS NULL OR nivel_conformidad IN (
                'firma_electronica_nativa',
                'xades_b_no_acreditado',
                'xades_b_acreditado'
            ));
    END IF;

    IF NOT EXISTS (
        SELECT 1
          FROM pg_constraint c
          JOIN pg_class t ON t.oid = c.conrelid
          JOIN pg_namespace n ON n.oid = t.relnamespace
         WHERE c.conname = 'firma_xades_level_check'
           AND n.nspname = current_schema()
    ) THEN
        ALTER TABLE firma
            ADD CONSTRAINT firma_xades_level_check
            CHECK (xades_level IS NULL OR xades_level IN (
                'XAdES-B',
                'XAdES-T',
                'XAdES-LT',
                'XAdES-LTA'
            ));
    END IF;
END $$;

-- >>> signature-service/tenant/016_firma_nivel_personal.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E17/F4): admitir 'xades_personal_no_acreditado' en
-- `firma_nivel_conformidad_check`.
--
-- DEFECTO QUE CORRIGE — la firma personal por-usuario nunca llegó a
-- persistirse contra una base real. `PersonalSigningService` firma el
-- payload, lo sella con TSA, lo sube a MinIO... y el INSERT final revienta
-- con CheckViolationError, porque `SignerRef.nivel_conformidad` vale
-- 'xades_personal_no_acreditado' (app/services/personal_signing.py) y ese
-- valor no lo añadió NINGUNA de las tres migraciones que han tocado este
-- CHECK: la 008 lo creó con los tres valores del sello institucional, la 013
-- le sumó LT/LTA, y la 015 solo lo repone si falta. El incremento de firma
-- personal añadió el productor y se olvidó del consumidor.
--
-- Por qué no lo cazó ningún test: los nueve que usan el literal
-- (test_personal_signing_revocation, test_cadena_personal_signing y los seis
-- de archive-service/test_transferencia_acta_firma_personal) conducen el
-- repositorio con la base SIMULADA — un mock acepta cualquier cadena. Una
-- restricción de integridad no se prueba con mocks, igual que la atomicidad.
-- La protección contra recaída NO es esta migración sino el censo de
-- tests/test_nivel_conformidad_admitido.py, que compara los literales que el
-- código puede escribir contra los que el SQL admite.
--
-- El efecto se veía en pantalla como «signature-service no está disponible
-- para la firma personal» (503), a dos servicios de distancia de la causa.
--
-- NO se reserva un gemelo 'xades_personal_acreditado' —a diferencia de lo que
-- hizo la 008 con 'xades_b_acreditado'— porque no existe ninguna ruta que
-- pueda producirlo: la acreditación ONAC exige una CA acreditada que no está
-- integrada, y el día que se integre necesitará su propia migración de todos
-- modos. Un CHECK que admite lo que nadie escribe no protege nada.
--
-- Idempotente: no hay ADD CONSTRAINT IF NOT EXISTS para CHECK en Postgres, así
-- que se DROPea (IF EXISTS) y se re-crea siempre — mismo criterio que la 013.
-- Tras el DROP el estado es idéntico, sea la primera corrida o una repetición.
--
-- Rollback (manual, si hiciera falta):
--   ALTER TABLE firma DROP CONSTRAINT IF EXISTS firma_nivel_conformidad_check;
--   ALTER TABLE firma ADD CONSTRAINT firma_nivel_conformidad_check
--       CHECK (nivel_conformidad IS NULL OR nivel_conformidad IN (
--           'firma_electronica_nativa', 'xades_b_no_acreditado',
--           'xades_b_acreditado', 'xades_lt_no_acreditado',
--           'xades_lta_no_acreditado'));
--   -- Solo posible si no hay ya filas 'xades_personal_no_acreditado'.

ALTER TABLE firma DROP CONSTRAINT IF EXISTS firma_nivel_conformidad_check;
ALTER TABLE firma
    ADD CONSTRAINT firma_nivel_conformidad_check
    CHECK (nivel_conformidad IS NULL OR nivel_conformidad IN (
        'firma_electronica_nativa',
        'xades_b_no_acreditado',
        'xades_b_acreditado',        -- reservado: sin CA acreditada ONAC integrada
        'xades_lt_no_acreditado',
        'xades_lta_no_acreditado',
        'xades_personal_no_acreditado'  -- firma personal por-usuario (E17, art. 7 no acreditado)
    ));

COMMENT ON COLUMN firma.nivel_conformidad IS
    'Perfil de conformidad de la firma. ''firma_electronica_nativa'' = HMAC '
    'de retrocompatibilidad; ''xades_b_*''/''xades_lt_*''/''xades_lta_*'' = '
    'sello INSTITUCIONAL del tenant; ''xades_personal_no_acreditado'' = firma '
    'PERSONAL por-usuario (E17), con certificado de la sub-CA de usuarios y '
    'segundo factor TOTP. Ninguno de los perfiles ''no_acreditado'' proviene '
    'de una PKI acreditada ONAC (art. 7, no art. 28). Cuando el firmador '
    'añade material LT/LTA promueve el valor a ''xades_lta_no_acreditado'' '
    '(app/providers/local.py), también en la firma personal: la distinción '
    'personal/institucional se conserva entonces en `firma.tipo_firma`.';

-- >>> signature-service/tenant/017_nivel_conformidad_acreditado.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se
-- entrega SIN GARANTÍA ALGUNA. Véase LICENSE y <https://www.gnu.org/licenses/>.
--
-- 017 — El CHECK admite los perfiles LT/LTA ACREDITADOS (E06).
--
-- Por qué ahora: la acreditación ONAC dejó de ser deuda del PRODUCTO y pasó a
-- ser propia de cada INSTALACIÓN — depende de que la entidad contrate un
-- operador de firma acreditado y aporte su material. Para que esa decisión sea
-- ejecutable, el sistema tiene que poder DECLARAR acreditado un sello que lo es
-- (`<signer_cert_dir>/<slug>/acreditacion.json`, app/core/keys.py). Hasta hoy
-- `acreditado` era un literal `False` y el perfil se escribía siempre
-- `*_no_acreditado`: una entidad podía montar un certificado de una CA
-- acreditada y el sistema seguía SUB-declarando la conformidad que pagó.
--
-- El 'xades_b_acreditado' ya estaba admitido desde la 008 («reservado»). Lo que
-- faltaba eran sus gemelos LT/LTA, que es donde acaba una firma con material de
-- validación a largo plazo: sin ellos, un sello acreditado + CA/CRL montadas
-- produciría 'xades_lta_acreditado' y el INSERT lo rechazaría — exactamente el
-- fallo que motivó la 016, un literal del código fuera del CHECK.
--
-- NO se añade 'xades_personal_acreditado', y no es un olvido: la firma personal
-- se custodia en el servidor, así que no hay CONTROL EXCLUSIVO del firmante
-- (Ley 527/1999 art. 28) por muy acreditado que esté el certificado. Ese camino
-- se abre con HSM o firma en el dispositivo, no con una entrada en esta lista.
--
-- Idempotente: no hay ADD CONSTRAINT IF NOT EXISTS para CHECK en Postgres, así
-- que se DROPea (IF EXISTS) y se re-crea siempre — mismo criterio que la 013 y
-- la 016. Tras el DROP el estado es idéntico, sea la primera corrida o una
-- repetición.
--
-- Rollback (manual, si hiciera falta):
--   ALTER TABLE firma DROP CONSTRAINT IF EXISTS firma_nivel_conformidad_check;
--   ALTER TABLE firma ADD CONSTRAINT firma_nivel_conformidad_check
--       CHECK (nivel_conformidad IS NULL OR nivel_conformidad IN (
--           'firma_electronica_nativa', 'xades_b_no_acreditado',
--           'xades_b_acreditado', 'xades_lt_no_acreditado',
--           'xades_lta_no_acreditado', 'xades_personal_no_acreditado'));
--   -- Solo posible si no hay ya filas con los dos valores nuevos.

ALTER TABLE firma DROP CONSTRAINT IF EXISTS firma_nivel_conformidad_check;
ALTER TABLE firma
    ADD CONSTRAINT firma_nivel_conformidad_check
    CHECK (nivel_conformidad IS NULL OR nivel_conformidad IN (
        'firma_electronica_nativa',
        'xades_b_no_acreditado',
        'xades_b_acreditado',
        'xades_lt_no_acreditado',
        'xades_lt_acreditado',
        'xades_lta_no_acreditado',
        'xades_lta_acreditado',
        'xades_personal_no_acreditado'  -- firma personal por-usuario (E17, art. 7)
    ));

COMMENT ON COLUMN firma.nivel_conformidad IS
    'Perfil de conformidad de la firma. ''firma_electronica_nativa'' = HMAC '
    'de retrocompatibilidad; ''xades_b_*''/''xades_lt_*''/''xades_lta_*'' = '
    'sello INSTITUCIONAL del tenant; ''xades_personal_no_acreditado'' = firma '
    'PERSONAL por-usuario (E17), con certificado de la sub-CA de usuarios y '
    'segundo factor TOTP. El sufijo ''_acreditado'' lo produce ÚNICAMENTE un '
    'sello institucional cuyo directorio declara la acreditación en '
    'acreditacion.json (material de un operador acreditado ONAC aportado por '
    'la entidad); el sello de DESARROLLO nunca lo alcanza. La firma personal '
    'no tiene variante acreditada: con custodia en servidor no hay control '
    'exclusivo del firmante (art. 28), independientemente del certificado. '
    'Cuando el firmador añade material LT/LTA promueve el valor a '
    '''xades_lta_*'' (app/providers/local.py), también en la firma personal: '
    'la distinción personal/institucional se conserva en `firma.tipo_firma`.';

-- >>> signature-service/tenant/018_cadena_rol_e_invalidacion.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E23, RF-PRO-10/11): visto bueno y firma en UNA cadena,
-- y el estado que faltaba para poder invalidarla.
--
-- ── Qué había ───────────────────────────────────────────────────────────────
--
-- `firma_cadena` ya implementaba turnos ordenados con 2FA y rechazo con motivo.
-- Le faltaban dos cosas para servir al circuito real de una entidad:
--
--   1. **El rol.** En la práctica varias personas dan visto bueno y UNA firma:
--      la que compromete a la entidad y produce el documento definitivo.
--      Presentar los dos actos igual atribuiría a un revisor un compromiso que
--      no adquirió.
--   2. **Un estado de invalidación.** `estado` solo admitía
--      pendiente|firmado|rechazado, así que cuando el texto cambiaba no había
--      forma de decirlo: la cadena seguía «pendiente» sobre un documento que ya
--      no existe, o peor, «firmado» sobre uno que cambió después.

ALTER TABLE firma_cadena
    ADD COLUMN IF NOT EXISTS rol VARCHAR(12) NOT NULL DEFAULT 'firma';

-- El CHECK se declara aparte para poder reemplazarlo idempotentemente. `firma`
-- es el default a propósito: las cadenas que ya existen son todas de firma, y
-- un default distinto reescribiría su significado en silencio.
ALTER TABLE firma_cadena DROP CONSTRAINT IF EXISTS firma_cadena_rol_check;
ALTER TABLE firma_cadena ADD CONSTRAINT firma_cadena_rol_check
    CHECK (rol IN ('visto_bueno', 'firma'));

-- ── El CHECK de estado se REEMPLAZA, no se añade otro ──────────────────────
--
-- Dos CHECK sobre la misma columna se conjugan con AND: añadir uno nuevo con
-- 'invalidada' no habría admitido nada, porque el viejo la seguiría rechazando.
-- Y el modo de fallo es el peor de los conocidos en este proyecto: un valor que
-- el código produce y el CHECK no admite: el `503` acusa a un servicio sano y
-- nadie mira la restricción.
ALTER TABLE firma_solicitud DROP CONSTRAINT IF EXISTS firma_solicitud_estado_check;
ALTER TABLE firma_solicitud ADD CONSTRAINT firma_solicitud_estado_check
    CHECK (estado IN ('pendiente', 'firmado', 'rechazado', 'invalidada'));

ALTER TABLE firma_cadena DROP CONSTRAINT IF EXISTS firma_cadena_estado_check;
ALTER TABLE firma_cadena ADD CONSTRAINT firma_cadena_estado_check
    CHECK (estado IN ('pendiente', 'firmado', 'rechazado', 'invalidada'));

-- Motivo de la invalidación, para que la bandeja pueda decir POR QUÉ decayó un
-- turno que alguien tenía pendiente. «Desapareció» sin explicación es lo que
-- hace que la gente desconfíe de la herramienta.
ALTER TABLE firma_solicitud
    ADD COLUMN IF NOT EXISTS invalidada_at     TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS invalidada_motivo TEXT;

-- El índice de unicidad de cadena abierta ya filtra `WHERE estado='pendiente'`,
-- así que una solicitud invalidada NO bloquea la creación de la que la
-- sustituye. Se comprueba aquí explícitamente para que un cambio futuro del
-- índice no lo rompa por descuido: sin esto, invalidar dejaría el objeto sin
-- poder volver a someterse a firma nunca más.
DO $$
DECLARE
    predicado TEXT;
BEGIN
    SELECT pg_get_expr(i.indpred, i.indrelid) INTO predicado
      FROM pg_index i
      JOIN pg_class c ON c.oid = i.indexrelid
     WHERE c.relname = 'ux_firma_solicitud_objeto_abierta'
       AND c.relnamespace = current_schema()::regnamespace;
    IF predicado IS NULL OR predicado NOT LIKE '%pendiente%' THEN
        RAISE EXCEPTION
            'ux_firma_solicitud_objeto_abierta debe seguir filtrando por estado '
            '= ''pendiente'' (predicado actual: %). Sin ese filtro, una solicitud '
            'invalidada bloquearia para siempre la cadena que la sustituye.',
            COALESCE(predicado, '<sin indice>');
    END IF;
END $$;

COMMENT ON COLUMN firma_cadena.rol IS
    'visto_bueno | firma (E23, RF-PRO-10). El turno de rol=firma es el que '
    'compromete a la entidad y produce el documento definitivo; los vistos '
    'buenos son evidencia del tramite, no firmas.';

COMMENT ON COLUMN firma_solicitud.invalidada_motivo IS
    'Por que decayo la cadena (E23, RF-PRO-11), normalmente porque el texto '
    'cambio. Un turno que desaparece sin explicacion hace desconfiar de la '
    'herramienta.';

-- >>> signature-service/tenant/019_tipo_firma_default_vigente.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06/E23): el DEFAULT de `firma.tipo_firma` pertenecía a
-- un vocabulario que ya no existe.
--
-- ── Dos migraciones sobre la misma columna, y solo una llegó ────────────────
--
-- La `002` creó la columna:
--
--     ADD COLUMN IF NOT EXISTS tipo_firma VARCHAR(30) NOT NULL
--                              DEFAULT 'electronica-nativa'
--
-- con el vocabulario de entonces (`electronica-nativa | xades | pades`). La
-- `008` quiso redefinirla:
--
--     ADD COLUMN IF NOT EXISTS tipo_firma TEXT DEFAULT 'nativa'
--
-- y ese `IF NOT EXISTS` la convirtió en **no-op**: la columna ya existía. Lo
-- único de la `008` que sí se aplicó fue su `COMMENT` —los comentarios no
-- llevan guarda—, así que la columna quedó **documentando el vocabulario nuevo
-- (`nativa | sello_sistema | personal`) y con el DEFAULT del viejo**. Nadie lo
-- notó porque el DEFAULT no se usa nunca: el repositorio nombra la columna en
-- todos sus INSERT.
--
-- Esta migración alinea el DEFAULT con el vocabulario que el código lee y que
-- el propio COMMENT de la columna declara. No toca filas existentes: un DEFAULT
-- solo afecta a inserciones futuras que omitan la columna.
--
-- No se añade un CHECK. Sería lo natural para un vocabulario cerrado, pero esta
-- base puede tener filas históricas con `electronica-nativa` de antes de la
-- `008`, y una restricción que rechaza el pasado convierte una migración en una
-- avería de despliegue. El vocabulario se sostiene en el código y en el
-- comentario.

ALTER TABLE firma
    ALTER COLUMN tipo_firma SET DEFAULT 'nativa';

COMMENT ON COLUMN firma.tipo_firma IS
    'Tipo de acto de firma: ''nativa'' (HMAC de servicio) | ''sello_sistema'' '
    '(XAdES-B con el sello institucional del tenant, atribuido a la persona '
    'que actúa vía firmante_id + audit_log, RF-FIR-11) | ''personal'' (XAdES '
    'con la credencial PKI por-usuario, E17/F4). No confundir con provider, '
    'que identifica la IMPLEMENTACION pluggable. El DEFAULT se alineo a este '
    'vocabulario en la migracion 019: la 002 lo habia fijado en '
    '''electronica-nativa'' y la 008 no pudo cambiarlo por su IF NOT EXISTS.';

-- >>> signature-service/tenant/020_key_version_hkdf.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E06, AREA-04-11): `key_version` en `firma` y en
-- `firma_challenge`.
--
-- Hasta aquí un único `signature_secret` firmaba el HMAC de la firma nativa y
-- el HMAC del OTP, igual para todas las entidades, y el mensaje de la firma no
-- nombraba entidad ni objeto. Desde la 020 las claves salen de HKDF por
-- (propósito, entidad) y el mensaje ata entidad+tipo+objeto (la firma) o el
-- `challenge_id` (el OTP). Ver `app/core/secret_derivation.py`.
--
-- ── Por qué el DEFAULT es 0 y no 1 ──────────────────────────────────────────
--
-- 0 es el esquema ANTERIOR. Toda fila que existe hoy se produjo con él, así que
-- el DEFAULT hace que `ADD COLUMN` las deje etiquetadas correctamente sin
-- tocarlas (una firma es un hecho fechado y su fila no se reescribe): siguen
-- verificando con la clave raíz y el mensaje original. El código nuevo escribe
-- el valor ACTUAL (1) de forma explícita en cada INSERT.
--
-- ── Qué NO hace ─────────────────────────────────────────────────────────────
--
-- Solo importa para `firma.provider = 'nativa'` (las XAdES no llevan HMAC de
-- servicio; para ellas la columna vale 0 y no se lee). No re-firma nada ni
-- rota el secreto raíz.
--
-- Rollback (solo antes de que haya filas con key_version = 1, o esas dejarán de
-- verificar):
--   ALTER TABLE firma DROP COLUMN IF EXISTS key_version;
--   ALTER TABLE firma_challenge DROP COLUMN IF EXISTS key_version;

ALTER TABLE firma
    ADD COLUMN IF NOT EXISTS key_version SMALLINT NOT NULL DEFAULT 0
        CHECK (key_version IN (0, 1));

ALTER TABLE firma_challenge
    ADD COLUMN IF NOT EXISTS key_version SMALLINT NOT NULL DEFAULT 0
        CHECK (key_version IN (0, 1));

COMMENT ON COLUMN firma.key_version IS
    'Esquema del HMAC de la firma NATIVA: 0 = clave raiz directa y mensaje sin '
    'entidad ni objeto (anterior a la 020); 1 = clave HKDF por entidad y '
    'mensaje que ata entidad+tipo+objeto. Solo se lee para provider=nativa.';

COMMENT ON COLUMN firma_challenge.key_version IS
    'Esquema del HMAC del OTP: 0 = clave raiz directa, sin challenge_id; '
    '1 = clave HKDF por entidad y mensaje que ata el challenge_id.';

-- >>> signature-service/tenant/021_dead_letter_pk_por_grupo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (AREA-10-07, ADR-021): la PK de la tabla COMPARTIDA
-- evento_dead_letter pasa de (event_id) a (origin_group, event_id).
--
-- workflow, signature, notification y knowledge escriben en la MISMA tabla física
-- (misma base y mismo schema de tenant) y los cuatro leen `orpycamcp.document.events`
-- (o el stream de su dominio). Con PK solo por event_id, cuando un mismo evento
-- agotaba los reintentos en DOS grupos, el segundo INSERT ... ON CONFLICT DO NOTHING
-- era un no-op: ese grupo no dejaba fila ni asiento `evento.dead_letter`, su admin no
-- lo veía (el listado filtra por origin_group) y el XACK ya lo había sacado de la PEL.
-- Perdía en silencio la trazabilidad (Ley 594/2000 arts. 4 y 19).
--
-- IDEMPOTENTE y compartida entre los 4 servicios: corre primero el que llegue antes;
-- los demás ven la PK ya compuesta y no hacen nada. El LOCK evita que dos runners
-- simultáneos se pisen al soltar/crear la restricción.
--
-- Rollback (solo si no hay filas con el mismo event_id en dos grupos):
--   ALTER TABLE evento_dead_letter DROP CONSTRAINT evento_dead_letter_pkey,
--       ADD PRIMARY KEY (event_id);

DO $$
DECLARE
    cols text[];
BEGIN
    LOCK TABLE evento_dead_letter IN ACCESS EXCLUSIVE MODE;

    SELECT array_agg(a.attname::text ORDER BY k.ord)
      INTO cols
      FROM pg_constraint c
      CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord)
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
     WHERE c.conrelid = to_regclass('evento_dead_letter')
       AND c.contype = 'p';

    IF cols IS DISTINCT FROM ARRAY['origin_group', 'event_id'] THEN
        -- Una fila legada sin grupo quedaría fuera de la PK; el centinela 'unknown'
        -- es invisible a todas las consultas por servicio (fail-closed).
        UPDATE evento_dead_letter SET origin_group = 'unknown' WHERE origin_group IS NULL;
        ALTER TABLE evento_dead_letter ALTER COLUMN origin_group SET NOT NULL;
        ALTER TABLE evento_dead_letter DROP CONSTRAINT IF EXISTS evento_dead_letter_pkey;
        ALTER TABLE evento_dead_letter ADD PRIMARY KEY (origin_group, event_id);
    END IF;
END $$;

COMMENT ON TABLE evento_dead_letter IS
    'Copia durable (Postgres) de los eventos aparcados en el dead-letter de Redis. '
    'Tabla COMPARTIDA por los consumidores del tenant: la PK (origin_group, event_id) '
    'deja que cada grupo aparque el mismo evento una vez; repetir el mismo par es '
    'idempotente (ON CONFLICT (origin_group, event_id) DO NOTHING). El INSERT y el '
    'audit_log se escriben en la misma transacción (R-4, ADR-021).';

-- >>> signature-service/tenant/022_firma_xades_level_comment.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
