CREATE INDEX IF NOT EXISTS ix_edl_keyset
    ON evento_dead_letter (tenant_slug, origin_group, status, dead_lettered_at DESC, event_id DESC);

-- >>> signature-service/tenant/024_key_version_sin_legado.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (B9-5): se retira el esquema HMAC `key_version = 0`.
--
-- Hasta la 020 la firma nativa y el OTP usaban la clave raíz directa y un
-- mensaje sin entidad ni objeto. La 020 los dejó en `key_version = 0` y prometió
-- que «seguían verificando»; B9 retira esa rama del código: una fila NATIVA con 0
-- ya no verifica (`/verify` responde `motivo = esquema_hmac_retirado`).
--
-- `0` pasa a significar «sin HMAC de servicio» (relleno de las filas no nativas,
-- XAdES, que no lo usan). Se quita el DEFAULT: un default que significa «esquema
-- retirado» es justo cómo nace una fila mal etiquetada en silencio. Los dos
-- INSERT (`firma_repository`, `challenge_repository`) pasan el valor explícito.
-- El CHECK (0,1) se mantiene: endurecerlo exigiría tocar filas.
--
-- Solo esquema, idempotente. Sin backfill.

ALTER TABLE firma           ALTER COLUMN key_version DROP DEFAULT;
ALTER TABLE firma_challenge ALTER COLUMN key_version DROP DEFAULT;

COMMENT ON COLUMN firma.key_version IS
    'Esquema del HMAC de la firma NATIVA: 1 = clave HKDF por entidad y mensaje que ata '
    'entidad+tipo+objeto. 0 = sin HMAC de servicio (firmas no nativas). Una fila nativa '
    'con 0 (esquema anterior a la 020, retirado en B9) no verifica.';
COMMENT ON COLUMN firma_challenge.key_version IS
    'Esquema del HMAC del OTP: 1 = clave HKDF por entidad que ata el challenge_id. '
    '0 = esquema retirado (no verifica).';

-- >>> signature-service/tenant/025_firma_nativa_exige_key_version.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (B9-S7): una firma NATIVA solo existe con `key_version = 1`.
--
-- La 024 retiró el esquema HMAC 0 del código y quitó el DEFAULT, pero la base seguía
-- admitiendo una fila `provider = 'nativa'` con `key_version = 0`: justo la fila que
-- ningún código sabe verificar. El CHECK lo cierra donde nace.
--
-- ── Entorno de pruebas, sin backfill ────────────────────────────────────────
--
-- Se BORRA la fila sintética v0 que el desarrollo sembró para ejercitar el motivo
-- `esquema_hmac_retirado` (`d4e62969-824d-4802-9e40-b402d977b6fc`); no se
-- reetiqueta ni se reescribe: una firma es un hecho fechado y esta nunca fue real.
-- Es la única fila nativa con 0 (comprobado). Si otro entorno tuviera filas nativas
-- con 0, el ADD CONSTRAINT falla —ruidosamente— en vez de reescribirlas.
--
-- Idempotente.

DELETE FROM firma
 WHERE id = 'd4e62969-824d-4802-9e40-b402d977b6fc'
   AND provider = 'nativa'
   AND key_version = 0;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
         WHERE conname = 'firma_nativa_exige_key_version'
           AND conrelid = 'firma'::regclass
    ) THEN
        ALTER TABLE firma
            ADD CONSTRAINT firma_nativa_exige_key_version
            CHECK (provider <> 'nativa' OR key_version = 1);
    END IF;
END $$;

-- >>> signature-service/tenant/026_firma_sello_archivo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
