-- Migración de tenant (RF-FIR-13, cierre de fuga de OTP — seguimiento de
-- seguridad de E06 Inc.2): marca las notificaciones cuyo `body` fue
-- REDACTADO a propósito antes de persistirse.
--
-- Contexto: notification-service recibe el body REAL (p. ej. el código OTP
-- del 2FA por correo, RF-FIR-13) y SIEMPRE lo envía por SMTP tal cual, pero
-- cuando el emisor marca el envío como sensible (`NotificationSend.sensible`)
-- la fila persistida en esta tabla lleva
-- `body = '[contenido sensible omitido]'`, NUNCA el valor real. Esta columna
-- documenta esa redacción intencional (no es pérdida de datos) y permite
-- filtrar/auditar los envíos sensibles sin volver a exponer su contenido.
--
-- IDEMPOTENTE: ADD COLUMN IF NOT EXISTS + DEFAULT false no rompe filas
-- existentes (todo envío previo a esta migración era, por definición,
-- no-sensible bajo el invariante nuevo).
--
-- Rollback:
--   ALTER TABLE notifications DROP COLUMN IF EXISTS sensible;

ALTER TABLE notifications
    ADD COLUMN IF NOT EXISTS sensible BOOLEAN NOT NULL DEFAULT false;

COMMENT ON COLUMN notifications.sensible IS
    'true cuando body fue redactado a propósito antes de persistir (RF-FIR-13, p. ej. OTP de 2FA); el correo se envió con el body real por SMTP pero esta fila NUNCA lo contuvo.';

-- >>> notification-service/tenant/009_webhook_secret_cifrado.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Secreto HMAC de los webhooks CIFRADO EN REPOSO.
--
-- `secret` (003) guardaba en claro la clave con la que se firma cada entrega:
-- quien leyera la base, un respaldo o una inyección podía forjar entregas que el
-- receptor aceptaría. Ahora el secreto se guarda cifrado (AES-256-GCM, AAD =
-- tenant + id del webhook) con una KEK de la APLICACIÓN, que no está en la base.
--
-- Esta migración NO puede cifrar los existentes —la KEK no está en SQL—: añade
-- las columnas y cierra la puerta a escribir en claro de ahora en adelante. El
-- cifrado de las filas ya existentes (y dejar `secret` en NULL) lo hace la
-- aplicación: `python -m app.ops.cifrar_webhook_secrets`, idempotente, con asiento
-- en audit_log.

ALTER TABLE webhook_subscription
    ADD COLUMN IF NOT EXISTS secret_cifrado     BYTEA,
    ADD COLUMN IF NOT EXISTS secret_nonce       BYTEA,
    ADD COLUMN IF NOT EXISTS secret_kek_version INTEGER;

-- Las tres columnas van juntas o ninguna: un ciphertext sin su nonce o sin la
-- versión de KEK es un secreto irrecuperable.
DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'chk_webhook_secret_cifrado_completo'
          AND conrelid = 'webhook_subscription'::regclass
    ) THEN
        ALTER TABLE webhook_subscription
            ADD CONSTRAINT chk_webhook_secret_cifrado_completo CHECK (
                (secret_cifrado IS NULL AND secret_nonce IS NULL AND secret_kek_version IS NULL)
                OR (secret_cifrado IS NOT NULL AND secret_nonce IS NOT NULL
                    AND secret_kek_version IS NOT NULL AND secret_kek_version >= 1)
            );
    END IF;
    -- Nunca el secreto en claro Y cifrado a la vez.
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'chk_webhook_secret_un_solo_formato'
          AND conrelid = 'webhook_subscription'::regclass
    ) THEN
        ALTER TABLE webhook_subscription
            ADD CONSTRAINT chk_webhook_secret_un_solo_formato CHECK (
                secret IS NULL OR secret_cifrado IS NULL
            );
    END IF;
    -- NOT VALID: no se escribe NINGÚN secreto nuevo en claro (INSERT y UPDATE se
    -- comprueban), pero las filas heredadas todavía en claro no bloquean la
    -- migración; el paso de la aplicación las cifra y entonces valida.
    IF NOT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conname = 'chk_webhook_secret_sin_claro'
          AND conrelid = 'webhook_subscription'::regclass
    ) THEN
        ALTER TABLE webhook_subscription
            ADD CONSTRAINT chk_webhook_secret_sin_claro CHECK (secret IS NULL) NOT VALID;
    END IF;
END $$;

COMMENT ON COLUMN webhook_subscription.secret IS
    'OBSOLETO: secreto en claro heredado. Debe quedar siempre NULL; ver secret_cifrado.';
COMMENT ON COLUMN webhook_subscription.secret_cifrado IS
    'Secreto HMAC cifrado con AES-256-GCM; AAD tenant:{slug}:webhook:{id}:secret.';

-- >>> notification-service/tenant/010_dead_letter_pk_por_grupo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (AREA-10-07, ADR-021): la PK de la tabla COMPARTIDA
-- evento_dead_letter pasa de (event_id) a (origin_group, event_id).
--
-- workflow, signature, notification y knowledge escriben en la MISMA tabla física
-- (misma base y mismo schema de tenant) y los cuatro leen `orpycamcp.document.events`
-- (o el stream de su dominio). Con PK solo por event_id, cuando un mismo evento
-- agotaba los reintentos en DOS grupos, el segundo INSERT ... ON CONFLICT DO NOTHING
-- era un no-op: ese grupo no dejaba fila ni asiento `evento.dead_letter`, su admin no
-- lo veía (el listado filtra por origin_group) y el XACK ya lo había sacado de la PEL.
-- Perdía en silencio la trazabilidad (Ley 594/2000 arts. 4 y 19).
--
-- IDEMPOTENTE y compartida entre los 4 servicios: corre primero el que llegue antes;
-- los demás ven la PK ya compuesta y no hacen nada. El LOCK evita que dos runners
-- simultáneos se pisen al soltar/crear la restricción.
--
-- Rollback (solo si no hay filas con el mismo event_id en dos grupos):
--   ALTER TABLE evento_dead_letter DROP CONSTRAINT evento_dead_letter_pkey,
--       ADD PRIMARY KEY (event_id);

DO $$
DECLARE
    cols text[];
BEGIN
    LOCK TABLE evento_dead_letter IN ACCESS EXCLUSIVE MODE;

    SELECT array_agg(a.attname::text ORDER BY k.ord)
      INTO cols
      FROM pg_constraint c
      CROSS JOIN LATERAL unnest(c.conkey) WITH ORDINALITY AS k(attnum, ord)
      JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = k.attnum
     WHERE c.conrelid = to_regclass('evento_dead_letter')
       AND c.contype = 'p';

    IF cols IS DISTINCT FROM ARRAY['origin_group', 'event_id'] THEN
        -- Una fila legada sin grupo quedaría fuera de la PK; el centinela 'unknown'
        -- es invisible a todas las consultas por servicio (fail-closed).
        UPDATE evento_dead_letter SET origin_group = 'unknown' WHERE origin_group IS NULL;
        ALTER TABLE evento_dead_letter ALTER COLUMN origin_group SET NOT NULL;
        ALTER TABLE evento_dead_letter DROP CONSTRAINT IF EXISTS evento_dead_letter_pkey;
        ALTER TABLE evento_dead_letter ADD PRIMARY KEY (origin_group, event_id);
    END IF;
END $$;

COMMENT ON TABLE evento_dead_letter IS
    'Copia durable (Postgres) de los eventos aparcados en el dead-letter de Redis. '
    'Tabla COMPARTIDA por los consumidores del tenant: la PK (origin_group, event_id) '
    'deja que cada grupo aparque el mismo evento una vez; repetir el mismo par es '
    'idempotente (ON CONFLICT (origin_group, event_id) DO NOTHING). El INSERT y el '
    'audit_log se escriben en la misma transacción (R-4, ADR-021).';

