-- >>> notification-service/tenant/012_webhook_entregas.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (B4, ADR-018): constancia de CADA entrega de webhook saliente.
--
-- Hasta aquí `dispatch` era best-effort y mudo: un webhook que entregó, que falló o
-- que se rechazó por destino no dejaba rastro alguno, así que la entidad no podía
-- probar a quién salió qué evento ni cuándo (Ley 594/2000 arts. 4 y 19).
--
-- Dos filas por intento, APPEND-ONLY:
--   * `envio`     — se escribe ANTES del POST; si no puede escribirse, no se envía
--                   (fail-closed: nada sale sin constancia previa);
--   * `resultado` — se escribe DESPUÉS, con el desenlace (`entregado`, `http_error`,
--                   `error_red`, `destino_rechazado`, `secreto_inutilizable`).
-- Una entrega que no llega a enviarse (destino rechazado, secreto inutilizable)
-- deja solo la fila `resultado`.
--
-- Sin FK a `webhook_subscription`: borrar la suscripción NO borra la constancia
-- (por eso se guarda `url_destino` y su huella). NUNCA se guarda el cuerpo: solo su
-- SHA-256, porque el sobre puede llevar datos personales. `url_destino` es solo
-- esquema://host[:puerto] —ni credenciales, ni ruta, ni query— porque Slack/Teams
-- ponen el token en la ruta; `url_sha256` correlaciona sin exponerlo.
--
-- Retención/purga: PENDIENTE y declarada en ADR-018 (la tabla es append-only; una
-- purga exigirá un rol de ops y su propio asiento).
-- Idempotente. Rollback manual: DROP TABLE webhook_entregas;

CREATE TABLE IF NOT EXISTS webhook_entregas (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    entrega_id  UUID NOT NULL,
    fase        VARCHAR(9) NOT NULL CHECK (fase IN ('envio', 'resultado')),
    webhook_id  UUID NOT NULL,
    url_destino TEXT NOT NULL,
    url_sha256  CHAR(64) NOT NULL,
    event_id    TEXT,
    event_type  TEXT NOT NULL,
    intento     SMALLINT NOT NULL CHECK (intento >= 1),
    body_sha256 CHAR(64) NOT NULL,
    recortado   BOOLEAN NOT NULL DEFAULT false,
    firmado     BOOLEAN NOT NULL DEFAULT false,
    resultado   VARCHAR(24),
    http_status SMALLINT,
    error       VARCHAR(500),
    at          TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_webhook_entregas_resultado
        CHECK (resultado IS NULL OR resultado IN
               ('entregado', 'http_error', 'error_red', 'destino_rechazado', 'secreto_inutilizable')),
    -- `envio` no lleva desenlace; `resultado` siempre.
    CONSTRAINT chk_webhook_entregas_fase_resultado
        CHECK ((fase = 'envio' AND resultado IS NULL) OR (fase = 'resultado' AND resultado IS NOT NULL))
);

CREATE INDEX IF NOT EXISTS ix_webhook_entregas_webhook ON webhook_entregas (webhook_id, at DESC);
CREATE INDEX IF NOT EXISTS ix_webhook_entregas_event ON webhook_entregas (event_id);

CREATE OR REPLACE FUNCTION reject_webhook_entregas_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'webhook_entregas is append-only (constancia de entrega inmutable; Ley 594/2000 arts. 4 y 19)';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_webhook_entregas_immutable ON webhook_entregas;
CREATE TRIGGER trg_webhook_entregas_immutable
    BEFORE UPDATE OR DELETE ON webhook_entregas
    FOR EACH ROW EXECUTE FUNCTION reject_webhook_entregas_mutation();

-- TRUNCATE no dispara los triggers de fila: sin esta guarda vaciaría la tabla entera.
CREATE OR REPLACE FUNCTION reject_webhook_entregas_truncate() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'webhook_entregas is append-only: TRUNCATE denegado';
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_webhook_entregas_no_truncate ON webhook_entregas;
CREATE TRIGGER trg_webhook_entregas_no_truncate
    BEFORE TRUNCATE ON webhook_entregas
    FOR EACH STATEMENT EXECUTE FUNCTION reject_webhook_entregas_truncate();

-- Capa de privilegios: el rol de la aplicación no puede ni intentar mutar. Sin
-- `orpycamcp_app` (dev, donde la app corre como propietario) no hay a quién revocar.
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'orpycamcp_app') THEN
        EXECUTE format('REVOKE UPDATE, DELETE, TRUNCATE ON TABLE %I.webhook_entregas FROM orpycamcp_app',
                       current_schema());
    END IF;
END;
$$;

-- >>> notification-service/tenant/013_webhook_entregas_mensaje.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (B4, auditoría): matiza el mensaje del trigger append-only de
-- `webhook_entregas`. La tabla es TRAZA TÉCNICA de entregas salientes, no el registro de
-- comunicaciones oficiales (que es el radicado, Ley 594/2000): citar sus arts. 4 y 19
-- aquí sobre-declaraba lo que la tabla es. Solo cambia el texto de la excepción.
-- Nota: `url_sha256` pasa a ser la huella del ORIGEN; las filas ya escritas (append-only)
-- conservan la del URL completo y no pueden reescribirse.
-- Idempotente (CREATE OR REPLACE).

CREATE OR REPLACE FUNCTION reject_webhook_entregas_mutation() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'webhook_entregas is append-only (traza tecnica de entregas, inmutable)';
END;
$$ LANGUAGE plpgsql;

-- >>> knowledge-service/tenant/004_dead_letter.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (E21): tabla durable de dead-letter del worker de ingesta.
--
-- Espejo de la `evento_dead_letter` de workflow-service (ADR-021 Fase 2): almacena
-- los eventos de `orpycamcp.document.events` que agotaron los reintentos del
-- consumer-group `knowledge-ingest` sin poder ingestarse (fallo de embedding/BD).
-- El INSERT usa ON CONFLICT (origin_group, event_id) DO NOTHING para idempotencia por grupo: un reintento
-- del mismo mensaje (XADD ok pero XACK falló, at-least-once) no produce
-- duplicados ni dobles trazas en audit_log.
--
-- NOTA (tabla física COMPARTIDA, ver dead_letter_repository.py de workflow-service):
-- esta NO es una instancia propia de knowledge-service. Misma DDL que la de
-- workflow/signature/notification, creada con `CREATE TABLE IF NOT EXISTS` sobre la
-- MISMA base y el MISMO schema de tenant: es UNA sola tabla física que el primero en
-- migrar crea y los demás encuentran. Las filas se distinguen por `origin_group`
-- ("knowledge-ingest"). Por eso la PK se corrige a (origin_group, event_id) en la
-- migración 011_dead_letter_pk_por_grupo.sql (AREA-10-07): con PK solo por event_id,
-- el aparcamiento del segundo grupo para un mismo evento se perdía en silencio.
--
-- Rollback:
--   DROP TABLE IF EXISTS evento_dead_letter;
--   DROP INDEX IF EXISTS ix_evento_dead_letter_at;

CREATE TABLE IF NOT EXISTS evento_dead_letter (
    event_id          TEXT        PRIMARY KEY,           -- ID único del sobre de evento (idempotencia)
    event_type        TEXT,
    correlation_id    TEXT,
    tenant_slug       TEXT        NOT NULL,
    payload           JSONB       NOT NULL,              -- sobre íntegro (incl. payload de negocio)
    failure           JSONB       NOT NULL,              -- failure_meta: reason, last_error, counts, etc.
    origin_stream     TEXT,
    origin_group      TEXT,
    dead_lettered_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

COMMENT ON TABLE evento_dead_letter IS
    'Copia durable (Postgres) de los eventos aparcados en el dead-letter de Redis '
    'del worker de ingesta (E21). event_id como PK garantiza idempotencia '
    '(ON CONFLICT DO NOTHING). El INSERT y el audit_log se escriben en la misma '
    'transacción: no hay dead-letter sin traza durable.';

COMMENT ON COLUMN evento_dead_letter.payload IS
    'Sobre íntegro del evento (event_id, event_type, tenant_slug, occurred_at, actor, '
    'payload de negocio). Autosuficiente para reconstrucción forense (Ley 594/2000 art. 19).';

COMMENT ON COLUMN evento_dead_letter.failure IS
    'failure_meta del helper reclaim_stale: dead_letter_reason, dead_letter_last_error, '
    'dead_letter_delivery_count, dead_lettered_at, origin stream/group/consumer.';

-- Índice por dead_lettered_at para consultas de inspección y TTL operativo.
CREATE INDEX IF NOT EXISTS ix_evento_dead_letter_at
    ON evento_dead_letter (dead_lettered_at);

-- >>> knowledge-service/tenant/010_dead_letter_estado_y_grupo.sql
-- OrpycaMCP — Sistema de Gestión Documental Electrónico de Archivo (SGDEA).
-- Desarrollo original de Orpyca; adaptado a partir de Orfeo bajo licencia GPL.
-- Contacto: aurigadl@gmail.com
--
-- Software libre: este archivo se distribuye bajo la Licencia Pública General
-- Affero de GNU (AGPL) versión 3 o, a su elección, cualquier versión posterior,
-- conservando los términos de la GPL del Orfeo original del que deriva. Se entrega
-- SIN GARANTÍA ALGUNA. Véase el archivo LICENSE y <https://www.gnu.org/licenses/>.

-- Migración de tenant (AREA-10-10, E21): paridad de knowledge con el resto de
-- consumidores sobre la tabla COMPARTIDA evento_dead_letter, para poder
-- inspeccionarla y reprocesarla (admin DLQ).
--
-- knowledge creaba la tabla sin `status`/`resolved_at` ni NOT NULL en origin_group
-- (workflow/signature/notification sí). Si otro servicio migró antes, todo esto es
-- no-op; si knowledge migra primero, deja la tabla con la forma que esperan los
-- demás. Idempotente.
--
-- Rollback:
--   DROP INDEX IF EXISTS ix_edl_tenant_group_status, ix_edl_pending, ix_edl_resolved;

UPDATE evento_dead_letter SET origin_group = 'unknown' WHERE origin_group IS NULL;

ALTER TABLE evento_dead_letter
    ALTER COLUMN origin_group SET NOT NULL;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'evento_dead_letter' AND column_name = 'status'
    ) THEN
        ALTER TABLE evento_dead_letter
            ADD COLUMN status TEXT NOT NULL DEFAULT 'pending'
            CHECK (status IN ('pending', 'resolved', 'discarded'));
    END IF;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = current_schema()
          AND table_name = 'evento_dead_letter' AND column_name = 'resolved_at'
    ) THEN
        ALTER TABLE evento_dead_letter ADD COLUMN resolved_at TIMESTAMPTZ NULL;
    END IF;
END $$;

CREATE INDEX IF NOT EXISTS ix_edl_pending
    ON evento_dead_letter (dead_lettered_at) WHERE status = 'pending';

CREATE INDEX IF NOT EXISTS ix_edl_resolved
    ON evento_dead_letter (resolved_at) WHERE status IN ('resolved', 'discarded');

CREATE INDEX IF NOT EXISTS ix_edl_tenant_group_status
    ON evento_dead_letter (tenant_slug, origin_group, status);

